    ["02-10"] = {steps={[1]={npc="Maniveo Zumbang", tgt="Maniveo Zumbang"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Reúne 6 patas de reptador y colócalas en la caja mecánica 827.", desc="Recoge patas de los cangrejos de nivel 9-10 en la costa al sur de Auberdine. Si aún no tienes la misión de la criatura varada, acéptala la próxima vez que pases por el muelle a partir del nivel 11."}, [5]={hint="Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly'Leggonde a Auberdine."}, [6]={npc="Caja mecánica 827", npcObj=true}, [7]={npc="Caja mecánica 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Lleva 8 piezas de mineral de elunita y el Medallón de Elura a Elanaria en Darnassus."}, [11]={npc="Cerellean Zarpablanca", tgt="Cerellean Zarpablanca"}, [12]={hint="Recoge restos de la tortuga marina esquelética de las aguas del oeste de Auberdine y vuelve a Auberdine a hablar con Gwennyth Bly'Leggonde."}, [13]={hint="Consigue 3 ojos de trillador de los trilladores de Costa Oscura en las profundidades del mar, cerca de la caja mecánica 411."}, [14]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [15]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [16]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [17]={npc="Terenthis", tgt="Terenthis"}, [18]={hint="Captura un oso cardo rabioso vivo y llévaselo a Tharnariun."}, [19]={hint="Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee."}, [20]={npc="Asterion", tgt="Asterion"}, [21]={npc="Asterion", tgt="Asterion"}, [22]={hint="Consigue 8 pendientes de grell y llévaselos a Asterion a Bashal'Aran."}, [23]={npc="Asterion", tgt="Asterion"}, [24]={npc="Aste