    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={npc="Ilsa Corbin", tgt="Ilsa Corbin", tag="Opcional", desc="La misión de introducción es opcional: ve directamente a Harry Burlguard en Ventormenta y acepta Bartleby, el borracho."}, [3]={npc="Harry Burlguard", tgt="Harry Burlguard", tag="Opcional", desc="La misión de introducción es opcional: ve directamente a Harry Burlguard en Ventormenta y acepta Bartleby, el borracho."}, [4]={npc="Harry Burlguard", tgt="Harry Burlguard"}, [5]={npc="Bartleby", tgt="Bartleby"}, [6]={npc="Bartleby", tgt="Bartleby", desc="Habla con Bartleby y te atacará. Pelea hasta que se rinda."}, [7]={hint="Golpea a Bartleby y habla con él.", desc="Habla con Bartleby y te atacará. Pelea hasta que se rinda."}, [8]={npc="Bartleby", tgt="Bartleby", desc="Habla con Bartleby y te atacará. Pelea hasta que se rinda."}, [9]={npc="Bartleby", tgt="Bartleby"}, [10]={npc="Harry Burlguard", tgt="Harry Burlguard"}, [11]={npc="Harry Burlguard", tgt="Harry Burlguard"}, [12]={npc="Mariscal Haggard", tgt="Mariscal Haggard"}, [13]={npc="Mariscal Haggard", tgt="Mariscal Haggard", desc="Jack Dentomuerto está en el campamento al norte del Aserradero de la Vega del Este, en el Bosque de Elwynn."}, [14]={hint="Recupera la insignia de Haggar del campamento de Jack Dentomuerto y regresa con el mariscal Haggard.", desc="Jack Dentomuerto está en el campamento al norte del Aserradero de la Vega del Este, en el Bosque de Elwynn."}, [15]={npc="Mariscal Haggard", tgt="Mariscal Haggard", desc="Jack Dentomuerto está en el campamento al norte del Aserradero de la Vega del Este, en el Bosque de Elwynn."}, [16]={text="Desde el Aserradero de la Vega del Este, sigue el camino del Bosque de Elwynn hacia el oeste, pasa por Villadorada y cruza el puente para entrar en los Páramos de Poniente."}, [17]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra"}, [18]={npc="Remen Marcot", tgt="Remen Marcot", tag="Opcional", desc="Misión de introducción de los humanos en Villadorada. Puede