    ["05-d1"] = {name="El Salón de Señores Feudales", entrance="Forjaz 27.63, 47.83", pickup="Al pasar por Dun Morogh y Loch Modan, acepta primero las misiones previas a la mazmorra; no hace falta volver atrás justo antes de entrar. Los Skyborne se saltan {s:01-9}: la primera vez que vayas a Forjaz, ve al este hasta Dun Morogh a buscar a Videnterra Farsen, completa La vigilancia de Farsen, Párteles el coco y Mapa subterráneo y vuelve a Forjaz. Si no quieres dar el rodeo, sáltate Incursión en la Antigua Forjaz.", pickupS={{"Al pasar por Dun Morogh y Loch Modan, acepta primero las misiones previas a la mazmorra; no hace falta volver atrás justo antes de entrar"}, {"Los Skyborne se saltan {s:01-9}: la primera vez que vayas a Forjaz, ve al este hasta Dun Morogh a buscar a Videnterra Farsen, completa La vigilancia de Farsen, Párteles el coco y Mapa subterráneo y vuelve a Forjaz", {race={"Skyborne"}}}, {"Si no quieres dar el rodeo, sáltate Incursión en la Antigua Forjaz"}}, steps={[1]={npc="Mapa de Hierro Negro", npcObj=true, tag="Requisito de mazmorra"}, [2]={npc="Videnterra Farsen", tgt="Videnterra Farsen", tag="Requisito de mazmorra"}, [3]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [4]={npc="Afadra Muropardo", tgt="Afadra Muropardo"}, [5]={npc="Thom Birla", tgt="Thom Birla"}, [6]={text="Entrada: El Salón de Señores Feudales"}, [7]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [8]={hint="Ayuda al espíritu de Faldrim Yunquemar a descansar en paz y luego regresa con el asistente fantasmal en el Salón de Señores Feudales."}, [9]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [10]={hint="Mata 15 aparecidos iracundos y 10 almas atormentadas. Luego, ayuda al espíritu de Yunquemar a descansar en paz."}, [11]={hint="Reúne 8 reliquias de los enanos del Salón de Señores Feudales."}, [12]={hint="Entra en el Salón de Señores Feudales debajo de Antigua Forjaz y recupera la cabeza de Durgen Martillo de Endecha."}, [13]={npc="Treaty of Understanding", npcObj=true, desc="Haz clic derecho en Tratado del entendimiento en tu bolsa para empezar la misión. El jefe final lanza Miedo hacia el 35 % de salud. Limpia primero los esbirros y luego lleva al jefe a la sala anterior. Junto a quien da la misión hay una palanca. Tira de ella para abrir la puerta y sal en línea recta."}, [14]={npc="Thom Birla", tgt="Thom Birla"}, [15]={npc="Afadra Muropardo", tgt="Afadra Muropardo"}, [16]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [17]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}}},
    ["02-12"] = {steps={[1]={npc="Gryth Thurden", tgt="Gryth Thurden"}, [2]={node="Forjaz"}, [3]={to="Thelsamar", toA="{a:144}"}, [4]={text="Sal de Forjaz y sigue el camino hacia el este, atraviesa el túnel del paso oriental hasta Loch Modan y luego sigue el camino al noreste hasta Thelsamar.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [5]={nodeA="{a:144}", node="Thelsamar"}, [6]={npc="Montaraz Kadrell", tgt="Montaraz Kadrell"}, [7]={npc="Montaraz Ylva", tgt="Montaraz Ylva"}, [8]={hint="El montaraz Gravagau, de la torre de vigilancia sur, quiere que mates a 10 aplastacráneos y 10 videntes Rompecantos. Luego ve a informarle."}, [9]={hint="Levanta el estandarte de Forjaz, llama la atención del trogg partecabezas y acaba con él. Luego, preséntate ante el Capitán Rugelfuss."}, [10]={npc="Montaraz Gravagau", tgt="Montaraz Gravagau"}, [11]={npc="Montaraz Muroplof", tgt="Montaraz Muroplof"}, [12]={hint="Montaraz Muroplof en la torre de vigilancia sur quiere que mates 10 chamanes Rompecantos y 10 cascahuesos Rompecantos."}, [13]={npc="Montaraz Muroplof", tgt="Montaraz Muroplof"}, [14]={npc="Capitán Rugelfuss", tgt="Capitán Rugelfuss"}, [15]={hint="Coge el Símbolo de la Vida y resucita a Narm Faulk en Dun Morogh."}, [16]={npc="Narm Faulk", tgt="Narm Faulk"}, [17]={npc="Narm Faulk", tgt="Narm Faulk"}, [18]={hint="Consigue una misiva Hierro Negro de los enanos Hierro Negro que están cerca de Helm y luego vuelve a Forjaz y busca a Muiredon Forjabatalla."}, [19]={npc="Muiredon Forjabatalla", tgt="Muiredon Forjabatalla"}, [20]={npc="Muiredon Forjabatalla", tgt="Muiredon Forjabatalla", desc="Entrega la misión para aprender Redención."}, [21]={npc="Tiza Forjabatalla", tgt="Tiza Forjabatalla", desc="Entrega la misión para aprender Redención."}, [22]={npc="Jern Cornamenta", tgt="Jern Cornamenta"}, [23]={npc="Brock Buscapiedras", tgt="Brock Buscapiedras"}, [24]={npc="Magmar Ceñimal", tgt="Magmar Ceñimal"}, [25]={npc="Magmar Ceñimal", tgt="Magmar Ceñimal"}, [26]={npc="Prospector Vetaferro", tgt="Prospector Vetaferro"}, [27]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [28]={hint="Mata 6 águilas ratoneras montesas y regresa a la Cabaña del Errante con Daryl el Jovenzuelo en menos de 15 minutos."}, [29]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [30]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [31]={hint="Mata 5 jabalíes monteses mayores y regresa a la Cabaña del Errante con Daryl el Jovenzuelo en menos de 12 minutos."}, [32]={npc="Daryl el Jovenzuelo", tgt="Daryl el Jovenzuelo"}, [33]={npc="Marek Coracero", tgt="Marek Coracero"}, [34]={npc="Marek Coracero", tgt="Marek Coracero"}, [35]={npc="Bingles Pimpampum", tgt="Bingles Pimpampum"}, [36]={npc="Bingles Pimpampum", tgt="Bingles Pimpampum"}, [37]={hint="Encuentra y derrota al crocolisco Dagacolmillo y devuélvele el cuchillo a Marek."}, [38]={hint="Lleva 5 piezas de carne de crocolisco y 6 pieles de crocolisco a Marek Coracero, en la Cabaña del Errante."}, [39]={hint="Localiza las herramientas de Bingles y devuélveselas:"}, [40]={npc="Ingeniero jefe Hinderweir VII", tgt="Ingeniero jefe Hinderweir VII"}, [41]={npc="Barrica sospechosa", npcObj=true}, [42]={npc="Barrica sospechosa", npcObj=true}, [43]={npc="Ingeniero jefe Hinderweir VII", tgt="Ingeniero jefe Hinderweir VII"}, [44]={npc="Montaraz Pico Tormenta", tgt="Montaraz Pico Tormenta", desc="Desde la presa, sigue el camino del norte hacia el oeste hasta el puesto del paso."}, [45]={npc="Bingles Pimpampum", tgt="Bingles Pimpampum"}, [46]={npc="Marek Coracero", tgt="Marek Coracero"}, [47]={npc="Marek Coracero", tgt="Marek Coracero"}, [48]={hint="Llévale 8 ídolos de piedra grabados a Magmar Ceñimal."}, [49]={npc="Magmar Ceñimal", tgt="Magmar Ceñimal"}, [50]={npc="Jern Cornamenta", tgt="Jern Cornamenta"}, [51]={npc="Jern Cornamenta", tgt="Jern Cornamenta"}, [52]={}, [53]={npc="Argos Susurro Nocturno", tgt="Argos Susurro Nocturno"}, [54]={to="Auberdine", from="Stormwind", desc="Aborda en el muelle del puerto de Ventormenta."}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="¡Se busca: Viscoso!", npcObj=true}, [3]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [4]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [5]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [6]={npc="Gorbold Mano de Acero", tgt="Gorbold Mano de Acero"}, [7]={npc="Gorbold Mano de Acero", tgt="Gorbold Mano de Acero"}, [8]={npc="Gershala Susurro Nocturno", tgt="Gershala Susurro Nocturno"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Cristal rojo misterioso", npcObj=true}, [12]={npc="Cristal rojo misterioso", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Criatura marina varada", npcObj=true}, [15]={hint="Recupera el arcón del Amanecer de Plata y el arcón del Halo de Bruma para Gorbold Mano de Acero de Auberdine. Ambos objetos deberían estar en los cascos de los navíos naufragados al norte de la aldea."}, [16]={npc="Caja mecánica 411", npcObj=true}, [17]={npc="Caja mecánica 411", npcObj=true}, [18]={npc="Tortuga marina varada", npcObj=true}, [19]={text="Salta al río aquí y nada hasta la poza bajo la cascada. A partir de aquí, mata a los Cachorros Acechalunas y Osos cardo rabiosos que veas."}, [20]={hint="Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua."}, [21]={hint="Reúne 6 trozos de cangrejo de gran calidad para Gubber Blump de Auberdine."}, [22]={npc="Tortuga marina varada", npcObj=true}, [23]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [24]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [25]={hint="Reúne 4 papiros desgastados para Balthule Golpesombra acerca de La Torre de Althalaxx."}, [26]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [27]={npc="Balthule Golpesombra", tgt="Balthule Golpesombra"}, [28]={hint="Libra al bosque de 20 Osos Cardo rabiosos y ve a buscar a Tharnariun Espinarbolado a Costa Oscura."}, [29]={hint="Reúne 6 colmillos de Acechalunas y colócalos en la caja mecánica 323."}, [30]={hint="Lleva 5 boletos rudos y 1 oronja verde a Barithras Sombra Lunar a Auberdine."}, [31]={npc="Caja mecánica 323", npcObj=true}, [32]={npc="Caja mecánica 323", npcObj=true}, [33]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [34]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [35]={npc="Gorbold Mano de Acero", tgt="Gorbold Mano de Acero"}, [36]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [37]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [38]={npc="Centinela Glynda Nal'Shea", tgt="Centinela Glynda Nal'Shea"}, [39]={npc="Barithras Sombra Lunar", tgt="Barithras Sombra Lunar", desc="Llena el Cuenco de purificación vacío en el pozo de la luna."}, [40]={npc="Barithras Sombra Lunar", tgt="Barithras Sombra Lunar"}, [41]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [42]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [43]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [44]={npc="Gubber Blump", tgt="Gubber Blump"}, [45]={npc="Criatura marina varada", npcObj=true}, [46]={npc="Criatura marina varada", npcObj=true, desc="El evento solo se activa cerca de la hoguera. Hazlo ahora o cuando la ruta vuelva a pasar por aquí."}, [47]={npc="Tortuga marina varada", npcObj=true}, [48]={npc="Tortuga marina varada", npcObj=true}, [49]={npc="Criatura marina varada", npcObj=true}, [50]={npc="Centinela Aynasha", tgt="Centinela Aynasha", desc="De camino a la siguiente misión, mata a cada Patriarca Acechalunas que veas (las crías y la matriarca vendrán con él)."}, [51]={hint="Protege a la centinela Aynasha y luego ve a Vallefresno, a la Atalaya de Maestra, y habla con Onaeya."}, [52]={npc="Onus", tgt="Onus"}, [53]={npc="Onus", tgt="Onus"}, [54]={npc="Cuenco de visión", npcObj=true, desc="Ve a 39.2, 86.9 y usa el vial que te dio Onus para dejarlo en el suelo."}, [55]={npc="Cuenco de visión", npcObj=true}, [56]={npc="Escrito Crepuscular", npcObj=true}, [57]={npc="Escrito Crepuscular", npcObj=true}, [58]={npc="Escrito Crepuscular", npcObj=true}, [59]={hint="Obtén un ojo incomparable de un discípulo Crepuscular o un matón en La Espada del Maestro, en Costa Oscura, y encuentra a alguien en Auberdine que lo quiera."}, [60]={npc="Therylune", tgt="Therylune", desc="Misión de escolta: en grupo, espera a que todos vayan igual antes de aceptarla y desactiva la aceptación automática."}, [61]={hint="Ayuda a escapar a Therylune y luego dile a Therysil, en el Santuario de Aessina, que su hermana está a salvo."}, [62]={npc="Libro: Los Poderes inferiores", npcObj=true, tag="Opcional", desc="Haz clic derecho en Libro: Los Poderes inferiores en tu bolsa para empezar la misión. Los enemigos del foso tienen poca probabilidad de soltar «Libro: Los Poderes inferiores». Acéptala solo si cae."}, [63]={npc="Prospector Tripirrem", tgt="Prospector Tripirrem", desc="Misión de escolta: en grupo, espera a que todos vayan igual antes de aceptarla y desactiva la aceptación automática. Deja que el Prospector Tripirrem vaya delante y lucha solo contra los enemigos que lo ataquen primero."}, [64]={npc="Prospector Tripirrem", tgt="Prospector Tripirrem"}, [65]={hint="Protege al prospector Tripirrem mientras busca el fósil misterioso. Luego vuelve a Auberdine y busca a la arqueóloga Hollee."}, [66]={hint="Consigue 4 cueros cabelludos grisáceos de los osos cardo grisáceos del sur de Auberdine y colócalos en la caja mecánica 525."}, [67]={npc="Caja mecánica 525", npcObj=true}, [68]={hint="Encuentra 5 pelambres de Acechalunas refinadas y llévaselas a Terenthis a Auberdine."}, [69]={npc="Onus", tgt="Onus"}, [70]={npc="Onus", tgt="Onus"}, [71]={npc="Arbal", tgt="Arbal"}, [72]={hint="Encuentra y mata al múrloc conocido como Viscoso. Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua.", desc="Llegan varias oleadas de múrlocs, de 2-3 cada una. Aleja de la hoguera al último múrloc de cada oleada antes de matarlo, come y bebe, y luego atrae la siguiente. O busca grupo."}, [73]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [74]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [75]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [76]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [77]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [78]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [79]={npc="Centinela Glynda Nal'Shea", tgt="Centinela Glynda Nal'Shea"}, [80]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [81]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [82]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [83]={npc="Terenthis", tgt="Terenthis"}, [84]={npc="Terenthis", tgt="Terenthis"}, [85]={to="Rut'theran Village", toA="{a:702}", from="Auberdine"}, [86]={to="Rut'theran Village", toA="{a:702}"}, [87]={npc="Nessa Cantosombrío", tgt="Nessa Cantosombrío"}, [88]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus."}, [89]={npc="Arqueólogo Jefe Mostachogris", tgt="Arqueólogo Jefe Mostachogris"}, [90]={npc="Arqueólogo Jefe Mostachogris", tgt="Arqueólogo Jefe Mostachogris"}, [91]={npc="Elanaria", tgt="Elanaria"}, [92]={npc="Elanaria", tgt="Elanaria"}, [93]={npc="Mathiel", tgt="Mathiel"}, [94]={npc="Mathiel", tgt="Mathiel", desc="Recompensa: un arma de Elunita."}, [95]={npc="Mathiel", tgt="Mathiel", desc="Recompensa: un arma de Elunita."}, [96]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso", desc="Tras completar «Cuerpo y corazón» en la piedra de lechúcico lunar de Auberdine, vuelve a Darnassus para entregarla y aprender Forma de oso."}, [97]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso", tag="Puedes comprar ya en la casa de subastas (o pedir a un alter que te lo envíe) 5 × Raíz de tierra (para Reunir los ingredientes del remedio, más adelante)."}, [98]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [99]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [100]={hint="Recoge agua de Salto de Fonroca a la entrada de la cueva.", desc="Toma el vuelo exclusivo de druidas de Amparo de la Noche a Aldea Rut'theran y luego vuela a Auberdine."}, [101]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche"}, [102]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche", desc="Recoge Raíz de tierra y Hongo lunar en Costa Oscura y entrégalos en Auberdine. Raíz de tierra ×5 se puede comprar en la casa de subastas."}, [103]={hint="Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo.", desc="Recoge Raíz de tierra y Hongo lunar en Costa Oscura y entrégalos en Auberdine."}, [104]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche", desc="Recoge Raíz de tierra y Hongo lunar en Costa Oscura y entrégalos en Auberdine."}, [105]={npc="Alanndarian Arrullanoche", tgt="Alanndarian Arrullanoche", desc="Usa el remedio con los ciervos enfermos de Costa Oscura."}, [106]={hint="Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno.", desc="Usa el remedio con los ciervos enfermos de Costa Oscura."}, [107]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Después de curar a 10 ciervos, usa Teletransporte: Claro de la Luna para volver y entregar."}, [108]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Entrega la misión para aprender Curar veneno."}, [109]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso", desc="Entrega la misión para aprender Curar veneno. Toma el vuelo exclusivo de druidas de Amparo de la Noche a Aldea Rut'theran y usa el portal de la aldea para entrar en Darnassus."}, [110]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso"}, [111]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [112]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Encuentra el Adorno de altar en el fondo del Lago Elune'ara."}, [113]={hint="Lleva un adorno de altar del Lago Elune'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario.", desc="Encuentra el Adorno de altar en el fondo del Lago Elune'ara."}, [114]={npc="Tajarri", tgt="Tajarri", desc="Encuentra el Adorno de altar en el fondo del Lago Elune'ara."}, [115]={npc="Tajarri", tgt="Tajarri", desc="Los dos cofres cerrados extraños contienen cada uno media pieza de un colgante: uno está en el fondo del mar al norte de Auberdine, en Costa Oscura, y el otro en el fondo del mar frente a la costa noroeste de los Páramos de Poniente."}, [116]={hint="Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes.", desc="Toma el vuelo exclusivo de druidas de Amparo de la Noche a Aldea Rut'theran, vuela a Auberdine y nada hacia el norte hasta el cofre cerrado del fondo del mar. Después toma el barco de Auberdine a Ventormenta, vuela a la Colina del Centinela y ve al noroeste hasta la costa para sumergirte y abrir el otro cofre cerrado."}, [117]={text="Cuando tengas las dos mitades, usa Teletransporte: Claro de la Luna para volver y juntar las mitades del colgante cerca del Santuario de Remulos."}, [118]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [119]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar", desc="Entrega la misión para aprender Forma acuática."}, [120]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso", desc="Entrega la misión para aprender Forma acuática. Toma el vuelo exclusivo de druidas de Amparo de la Noche a Aldea Rut'theran y usa el portal de la aldea para entrar en Darnassus."}, [121]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran."}, [122]={nodeA="{a:702}", node="Rut'theran Village"}, [123]={to="Auberdine"}, [124]={hint="Encuentra a la madre del cubil y mátala."}, [125]={hint="Llena el cuenco purificador vacío en la Poza de la Luna de Auberdine."}, [126]={hint="Lleva 6 reliquias de Mathystra a Onus al Páramo de los Ancianos."}, [127]={hint="Elimina a 12 mirmidones Escama Tormentosa, 8 hechiceras Escama Tormentosa y 6 guerreros Escama Tormentosa para Arbal, en el Páramo de los Ancianos."}, [128]={hint="Encuentra a una dama de bestias Escama Tormentosa, mátala y regresa con su vara de dominio profundo."}, [129]={}}},
    ["05-d2"] = {name="Ruinas de Lordaeron", entrance="Entrañas 72.41, 11.37", steps={[1]={text="Opcional y lejana: la entrada está en las Ruinas de Lordaeron, sobre Entrañas, así que hay que cruzar territorio de la Horda. Desde Auberdine, ve primero en barco a Puerto de Menethil y sigue la ruta marítima del norte hasta Costasur. Baja allí y descubre su punto de vuelo; luego ve al norte por las Laderas de Trabalomas y el Bosque de Argénteos hasta los Claros de Tirisfal. Al salir de la mazmorra, usa la piedra de hogar para volver a Ventormenta y retoma la {s:02-14}.", tag="Opcional"}, [2]={text="Entrada: Ruinas de Lordaeron"}, [3]={}, [4]={npc="Insignia ensangrentada", npcObj=true, tag="Acepta si cae, Opcional", desc="Haz clic derecho en Insignia ensangrentada en tu bolsa para empezar la misión."}, [5]={hint="Recoge 10 insignias ensangrentadas y llévaselas al general Marcus Jonathan en la Ciudad de Ventormenta.", tag="Opcional"}, [6]={npc="Blasón de Lordaeron", npcObj=true, desc="Haz clic derecho en Blasón de Lordaeron en tu bolsa para empezar la misión."}, [7]={npc="Blood-Stained Parchment", npcObj=true, desc="Haz clic derecho en Blood-Stained Parchment en tu bolsa para empezar la misión."}, [8]={}, [9]={npc="Supervisora de huérfanos Ruiseñor", tgt="Supervisora de huérfanos Ruiseñor"}, [10]={npc="Lady Dena Kennedy", tgt="Lady Dena Kennedy"}, [11]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan", tag="Opcional"}}},
    ["02-14"] = {grind={[1]={mob="Partecaras de Crestagrana", note="El campamento de gnolls al norte de Villa del Lago; enemigos normales, cerca del punto de vuelo."}, [2]={mob="Avanzado Roca Negra", note="Los orcos Roca Negra de la orilla noreste del Lago Sempiterno; de nivel más adecuado, con brutos entre ellos, así que atráelos desde el borde."}}, steps={[1]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [2]={npc="Suma sacerdotisa Laurena", tgt="Suma sacerdotisa Laurena", desc="Acéptala en Ventormenta, entrégala en Forjaz y aprende Resguardo de miedo."}, [3]={npc="Sumo sacerdote Rohan", tgt="Sumo sacerdote Rohan", desc="Acéptala en Ventormenta, entrégala en Forjaz y aprende Resguardo de miedo."}, [4]={text="Toma el Tranvía Subterráneo en Forjaz para volver a Ventormenta."}, [5]={npc="Suma sacerdotisa Laurena", tgt="Suma sacerdotisa Laurena", desc="Acéptala en Ventormenta y entrégala en Dun Morogh."}, [6]={npc="Suma sacerdotisa Mims", tgt="Suma sacerdotisa Mims", desc="Acéptala en Ventormenta y entrégala en Dun Morogh."}, [7]={text="Vuelve a Forjaz y toma el Tranvía Subterráneo a Ventormenta."}, [8]={npc="Jennea Cañón", tgt="Jennea Cañón", desc="La taberna El Ermitaño Taciturno está en el Barrio de los Magos de Ventormenta."}, [9]={componentNpc="Engendro de falla", hint="Usa la fórmula en El Ermitaño Taciturno, en el Barrio de los Magos de Ventormenta. Debilita a una criatura de la falla hasta aturdirla, usa el cofre y recoge el arca del suelo. Necesitas tres.", desc="La taberna El Ermitaño Taciturno está en el Barrio de los Magos de Ventormenta."}, [10]={npc="Jennea Cañón", tgt="Jennea Cañón", desc="La taberna El Ermitaño Taciturno está en el Barrio de los Magos de Ventormenta."}, [11]={npc="Jennea Cañón", tgt="Jennea Cañón", desc="Necesitas 10 × Paño de lino y 6 × Gema cargada de la falla. Si vuelves a Loch Modan, entra en la mina por el norte (aprox. 35.9,18.2) y abre los cajones de los mineros. Sigue tu ruta mientras te falten materiales. Visita a Wynne en Ventormenta cuando el registro indique que puedes entregar la misión."}, [12]={npc="Wynne Larson", tgt="Wynne Larson", desc="Necesitas 10 × Paño de lino y 6 × Gema cargada de la falla. Si vuelves a Loch Modan, entra en la mina por el norte (aprox. 35.9,18.2) y abre los cajones de los mineros. Sigue tu ruta mientras te falten materiales. Visita a Wynne en Ventormenta cuando el registro indique que puedes entregar la misión."}, [13]={npc="Wynne Larson", tgt="Wynne Larson", desc="Recompensa: Toga Tejemaná."}, [14]={npc="Wynne Larson", tgt="Wynne Larson", desc="Recompensa: Toga Tejemaná."}, [15]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra"}, [16]={npc="Takar el Vidente", tgt="Takar el Vidente", desc="Toma el barco del puerto de Ventormenta a Auberdine, sigue la costa de Costa Oscura hacia el sur hasta Vallefresno, entra en Los Baldíos desde el este por la Empalizada de Mor'shan y ve al sur a buscar a Takar. El Cruce y el Campamento Taurajo son bastiones de la Horda; rodéalos."}, [17]={npc="Takar el Vidente", tgt="Takar el Vidente"}, [18]={npc="Takar el Vidente", tgt="Takar el Vidente"}, [19]={hint="Recupera el duramen de Vallefresno y llévaselo a Gakin el Presotenebra en el Barrio de los Magos de Ventormenta.", desc="Limpia primero los monstruos junto al árbol y luego haz clic en ese árbol cenarino para obtener duramen."}, [20]={hint="Recupera la figurilla de madera y llévasela a Gakin el Presotenebra en el Barrio de los Magos de Ventormenta."}, [21]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Al terminar en Vallefresno, usa la piedra de hogar para volver a Ventormenta. Si la piedra de hogar está en enfriamiento, vuelve al norte hasta Auberdine y toma el barco a Ventormenta."}, [22]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra"}, [23]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Úsalo en el círculo de invocación junto a Gakin el Presotenebra y derrota al súcubo invocado."}, [24]={hint="Utilizando el corazón del duramen, invoca y somete a un súcubo. Después devuelve el corazón del duramen a Gakin el Presotenebra en El Cordero Degollado.", desc="Úsalo en el círculo de invocación junto a Gakin el Presotenebra y derrota al súcubo invocado."}, [25]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra", desc="Úsalo en el círculo de invocación junto a Gakin el Presotenebra y derrota al súcubo invocado."}, [26]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra"}, [27]={hint="Usa la figurilla de madera para invocar y someter a un íncubo. Después, llévasela de regreso a Gakin el Presotenebra en El Cordero Degollado."}, [28]={npc="Gakin el Presotenebra", tgt="Gakin el Presotenebra"}, [29]={text="Desde Ventormenta, sigue el camino del Bosque de Elwynn hacia el este; ve primero a la Torre de Azora y acepta Un ojo vigilante con Theocritus; después continúa al este hasta la entrada de las Montañas Crestagrana para buscar al Guardia Parker y luego sigue el camino hasta Villa del Lago.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie., Antes de ir a las Montañas Crestagrana, puedes comprar en la casa de subastas (o pedir a un alter que te lo envíe) 8 × Aleta de múrloc (para Cazadores furtivos)."}, [30]={npc="Theocritus", tgt="Theocritus"}, [31]={npc="Guardia Parker", tgt="Guardia Parker"}, [32]={to="Lakeshire", toA="{a:69}", tag="Antes de ir a las Montañas Crestagrana, puedes comprar en la casa de subastas (o pedir a un alter que te lo envíe) 8 × Aleta de múrloc (para Cazadores furtivos).", desc="Si aún no has desbloqueado el punto de vuelo de Villa del Lago, ve a pie desde Ventormenta por el camino principal del Bosque de Elwynn hacia el este hasta Villa del Lago."}, [33]={npc="Guardia Parker", tgt="Guardia Parker", desc="Guardia Parker está en el cruce del camino principal al oeste de Montañas Crestagrana que lleva al Bosque de Elwynn."}, [34]={npc="Darcy", tgt="Darcy"}, [35]={npc="Wiley el Negro", tgt="Wiley el Negro"}, [36]={npc="Wiley el Negro", tgt="Wiley el Negro"}, [37]={npc="Maestro de embarcadero Baren", tgt="Maestro de embarcadero Baren"}, [38]={npc="Maestro de embarcadero Baren", tgt="Maestro de embarcadero Baren", desc="La Aleta de múrloc se puede comprar en la casa de subastas. Con 8 no hace falta farmear."}, [39]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [40]={npc="Verner Osbien", tgt="Verner Osbien"}, [41]={npc="Ayudante de alguacil Feldon", tgt="Ayudante de alguacil Feldon"}, [42]={npc="Ayudante de alguacil Feldon", tgt="Ayudante de alguacil Feldon"}, [43]={npc="Ayudante de alguacil Feldon", tgt="Ayudante de alguacil Feldon"}, [44]={npc="Lucius", tgt="Lucius"}, [45]={npc="Lucius", tgt="Lucius", desc="Usa Forzar cerradura en el cofre cerca del Molino de Alther."}, [46]={hint="Abre la caja fuerte de Lucius y llévale la muestra de robo a Villa del Lago.", desc="Usa Forzar cerradura en el cofre cerca del Molino de Alther."}, [47]={npc="Lucius", tgt="Lucius", desc="Usa Forzar cerradura en el cofre cerca del Molino de Alther."}, [48]={npc="Arantir", tgt="Arantir", tag="Opcional"}, [49]={hint="Lleva los Cuernos de Nez'ra a Arantir a Villa del Lago.", tag="Opcional"}, [50]={npc="Arantir", tgt="Arantir", tag="Opcional"}, [51]={nodeA="{a:69}", node="Lakeshire"}, [52]={npc="Yorus Cebadiz", tgt="Yorus Cebadiz", desc="Las Cuevas de Rethban están al noroeste de las Montañas Crestagrana y están llenas de ogros."}, [53]={npc="Yorus Cebadiz", tgt="Yorus Cebadiz", desc="Las Cuevas de Rethban están al noroeste de las Montañas Crestagrana y están llenas de ogros."}, [54]={npc="Yorus Cebadiz", tgt="Yorus Cebadiz"}, [55]={desc="Si aún no eres nivel 21 antes de salir de las Montañas Crestagrana, ve al campamento de gnolls al norte de Villa del Lago y sube al 21 matando Partecaras de Crestagrana."}, [56]={to="Sentinel Hill", toA="{a:108}"}, [57]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [58]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [59]={to="Stormwind"}, [60]={npc="Suma sacerdotisa Laurena", tgt="Suma sacerdotisa Laurena", desc="Aprende Retroalimentación."}, [61]={npc="Suma sacerdotisa Laurena", tgt="Suma sacerdotisa Laurena", desc="Aprende Retroalimentación."}, [63]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}, [64]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [65]={npc="Furen Barbalarga", tgt="Furen Barbalarga", tag="Mobs de nivel superior, Grupo recomendado, Opcional"}, [66]={hint="Reúne los materiales que necesita Furen Barbalarga y llévaselos a Ventormenta.", tag="Mobs de nivel superior, Grupo recomendado, Opcional"}, [67]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [68]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [69]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [70]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [71]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [72]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [74]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}, [75]={npc="Herrero Argus", tgt="Herrero Argus"}, [76]={npc="Herrero Argus", tgt="Herrero Argus"}, [77]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw"}, [78]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw"}, [79]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw"}, [80]={to="Sentinel Hill", toA="{a:108}"}, [81]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [82]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [83]={hint="Localiza al mensajero Defias de los Páramos de Poniente y lleva su mensaje a Mantorrecio."}, [84]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [85]={npc="El Traidor de los Defias", tgt="El Traidor de los Defias"}, [86]={hint="Escolta al Traidor de los Defias a la ladronera secreta de la Hermandad Defias. Cuando el Traidor de los Defias te enseñe dónde se esconden VanCleef y sus hombres, regresa con Gryan Mantorrecio con toda la información.", tag="Escolta", desc="Sigue al traidor de los Defias hasta Arroyo de la Luna; los monstruos del camino lo atacarán, así que ayúdalo. Cuando llegues, vuelve a Colina del Centinela."}, [87]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [88]={npc="Agente Kearnen", tgt="Agente Kearnen"}, [89]={npc="Agente Kearnen", tgt="Agente Kearnen", desc="Roba la carta sellada de la Torre Defias en los Páramos de Poniente. Después, aprende Venenos."}, [90]={hint="Roba la Llave de la Torre Defias, entra en la Torre Defias y descubre qué contiene el Cofre del Bosque del Ocaso. Lleva toda la información que encuentres a Mathias Shaw de Ventormenta. Lee el diario de Kearnen para saber cómo acceder a la torre.|n", desc="Roba la carta sellada de la Torre Defias en los Páramos de Poniente. Después, aprende Venenos."}, [91]={npc="Una carta sin enviar", npcObj=true, tag="Acepta si cae", desc="Lo suelta VanCleef en Las Minas de la Muerte: haz clic derecho para aceptar la misión."}, [92]={}, [93]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", desc="Roba la carta sellada de la Torre Defias en los Páramos de Poniente. Después, aprende Venenos."}, [94]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [95]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Opcional"}, [96]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Opcional"}, [97]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Opcional"}, [98]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Opcional", desc="Flores silvestres simples y Vial emplomado los venden los vendedores. Tubo de bronce se puede comprar en la casa de subastas. Bobina de hilo de seda verde pistacho se recoge en la sastrería de los Canales de Ventormenta."}, [99]={hint="Lleva a Doc Mixilpixil un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y una bobina de hilo de seda verde pistacho. La 'itis' no se cura sola, jovencito.", tag="Opcional"}, [100]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Opcional"}, [102]={text="Tubo de bronce", npc="Billibub Volopiñón", desc="Existencias limitadas. Cómpralo solo si está disponib