    ["05-d4"] = {name="Las Mazmorras", entrance="Ventormenta 52.41, 70.01", pickup="Acepta «Lo que sucede alrededor...» en Villa del Lago y «Crimen y castigo» en Villa Oscura. Para «El motín de Las Mazmorras» debes entregar primero la carta de VanCleef. Si no la tienes, haz las demás misiones. Busca grupo para «La furia mora en las profundidades» después de completar «La guerra contra los Hierro Negro» en Los Humedales.", pickupS={{"Acepta «Lo que sucede alrededor...» en Villa del Lago y «Crimen y castigo» en Villa Oscura"}, {"Para «El motín de Las Mazmorras» debes entregar primero la carta de VanCleef"}, {"Si no la tienes, haz las demás misiones"}, {"Busca grupo para «La furia mora en las profundidades» después de completar «La guerra contra los Hierro Negro» en Los Humedales"}}, steps={[1]={npc="Consejero Tallolino", tgt="Consejero Tallolino"}, [2]={text="Requisito previo: Lo que sucede alrededor..."}, [3]={npc="Una carta sin enviar", npcObj=true, tag="Acepta si cae", desc="Lo suelta VanCleef en Las Minas de la Muerte: haz clic derecho para aceptar la misión."}, [4]={npc="Baros Alexston", tgt="Baros Alexston"}, [5]={npc="Baros Alexston", tgt="Baros Alexston"}, [6]={npc="Celador Thelagua", tgt="Celador Thelagua"}, [7]={npc="Celador Thelagua", tgt="Celador Thelagua"}, [8]={npc="Celador Thelagua", tgt="Celador Thelagua"}, [9]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [10]={text="Entrada: Las Mazmorras"}, [11]={hint="El celador Thelagua de Ventormenta quiere que mates 10 prisioneros Defias, 8 presidiarios Defias y 8 insurgentes Defias en Las Mazmorras."}, [12]={hint="Mata a Bazil Thredd y lleva su cabeza al celador Thelagua en las Mazmorras."}, [13]={hint="Nikova Raskol, de Ventormenta, quiere que consigas 10 pañuelos de lana roja."}, [14]={hint="El consejero Tallolino de Villa Oscura quiere que le lleves la mano de Dextren Ward."}, [15]={hint="Lleva la cabeza de Targorr el Pavoroso al guardia Berton a Villa del Lago.", tag="Grupo recomendado, Opcional"}, [16]={hint