    ["02-19"] = {steps={[1]={to="Lakeshire", toA="{a:69}"}, [2]={npc="Supervisor Olento", tgt="Supervisor Olento"}, [3]={npc="Verner Osbien", tgt="Verner Osbien"}, [4]={npc="Dorin Filosón", tgt="Dorin Filosón", tag="Opcional, Grupo recomendado"}, [5]={npc="Dorin Filosón", tgt="Dorin Filosón", tag="Opcional, Grupo recomendado", desc="Si ya completaste el Sitio de Excavación de Los Humedales, acepta esta misión en Villa del Lago y busca a Daewyn la próxima vez que entres con un grupo."}, [6]={npc="Se busca: Gath'Ilzogg", npcObj=true, tag="Opcional, Grupo recomendado"}, [7]={npc="Se busca: incinerador Gar'im", npcObj=true, tag="Opcional, Grupo recomendado"}, [8]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [9]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [10]={npc="Se busca: Teniente Fangore", npcObj=true}, [11]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [12]={hint="Martie Jainrose de Villa del Lago quiere que mates a Panzallena. Llévale un colmillo como prueba."}, [13]={npc="Mariscal Haggard", tgt="Mariscal Haggard"}, [14]={npc="Mariscal Haggard", tgt="Mariscal Haggard"}, [15]={npc="Mariscal Haggard", tgt="Mariscal Haggard", desc="Sube y saquea el cofre."}, [16]={npc="Mariscal Haggard", tgt="Mariscal Haggard"}, [17]={npc="Theocritus", tgt="Theocritus"}, [18]={npc="Guardia Howe", tgt="Guardia Howe"}, [19]={hint="Entrega el bastón roto del incinerador Gar'im al magistrado Solomon en Villa del Lago.", tag="Opcional, Grupo recomendado"}, [20]={npc="Estatua de león antigua", npcObj=true, desc="Busca la estatua del león afuera, al este de la Torre de Ilgalar, y coloca el glifo allí."}, [21]={npc="Estatua de león antigua", npcObj=true, tag="Opcional, Grupo recomendado", desc="Si no encuentras el glifo que te dieron, revisa tus bolsas, el banco y el registro de misiones."}, [22]={hint="Desde el león ve al oeste hasta la torre de vigilancia intacta junto al Castillo de Petravista. Sube por la rampa al techo y busca el frasco vacío sobre los barriles. Cui