    ["02-20"] = {steps={[1]={to="Auberdine", from="Stormwind", desc="Aborda en el muelle del puerto de Ventormenta."}, [2]={npc="Terenthis", tgt="Terenthis"}, [3]={to="Astranaar", toA="{a:415}"}, [4]={npc="Faldreas Goeth'Shael", tgt="Faldreas Goeth'Shael"}, [5]={npc="Raene Correlobo", tgt="Raene Correlobo"}, [6]={npc="Raene Correlobo", tgt="Raene Correlobo"}, [7]={npc="Raene Correlobo", tgt="Raene Correlobo"}, [8]={text="Sal de Astranaar hacia el este hasta el cruce y luego sigue el camino hacia el norte."}, [9]={hint="Llévale la calavera de Dal Zarpasangrante a Raene Correlobo en Astranaar."}, [10]={hint="Lleva la lágrima de Elune a Pelturas en Astranaar."}, [11]={text="Desde la isla del lago, nada hacia el sur hasta la orilla (46.80, 49.20 → 47.00, 51.70) y luego ve al este."}, [12]={npc="Shael'dryn", tgt="Shael'dryn"}, [13]={npc="Shael'dryn", tgt="Shael'dryn"}, [14]={hint="Encuentra la llave de madera y una pieza de la vara de Dartol antes de regresar con Shael'dryn en la poza de la luna."}, [15]={npc="Shael'dryn", tgt="Shael'dryn"}, [16]={npc="Shael'dryn", tgt="Shael'dryn"}, [17]={hint="Mata a 1 vigía del cubil, 2 ursas, 10 totémicos y 12 guerreros de la tribu de los Maderiza y vuelve junto a Raene Correlobo en Astranaar."}, [18]={hint="Encuentra la última pieza de la vara de Dartol y regresa con Shael'dryn en la poza de la luna."}, [19]={npc="Colgante curvo resplandeciente", npcObj=true}, [20]={npc="Shael'dryn", tgt="Shael'dryn"}, [21]={npc="Shael'dryn", tgt="Shael'dryn"}, [22]={npc="Santuario Oculto", npcObj=true}, [23]={npc="Santuario Oculto", npcObj=true}, [24]={npc="Shael'dryn", tgt="Shael'dryn"}, [25]={npc="Shael'dryn", tgt="Shael'dryn"}, [26]={npc="Pelturas Lunablanca", tgt="Pelturas Lunablanca"}, [27]={npc="Pelturas Lunablanca", tgt="Pelturas Lunablanca"}, [28]={npc="Raene Correlobo", tgt="Raene Correlobo"}, [29]={npc="Raene Correlobo", tgt="Raene Correlobo"}, [30]={npc="Raene Correlobo", tgt="Raene Correlobo"}, [31]={npc="Maliynn", tgt="Maliynn"}, [32]=