    ["05-d5"] = {name="Cavernas de Brazanegra", entrance="Vallefresno 14.50, 14.20", pickup="Al llegar a Costa Oscura (2.ª visita), acepta primero Investigaciones acerca de la corrupción. Las tres misiones de Darnassus y Forjaz requieren nivel 18-20; acéptalas cuando pases con ese nivel.", pickupS={{"Al llegar a Costa Oscura (2.ª visita), acepta primero Investigaciones acerca de la corrupción"}, {"Las tres misiones de Darnassus y Forjaz requieren nivel 18-20; acéptalas cuando pases con ese nivel"}}, steps={[1]={npc="Gershala Susurro Nocturno", tgt="Gershala Susurro Nocturno"}, [2]={npc="Guardia Argenta Manados", tgt="Guardia Argenta Manados", desc="Requiere nivel 20. Si al entrar en Darnassus en la {s:02-13} aún no tienes nivel, acéptala la próxima vez que pases o sáltala."}, [3]={npc="Vigía del Alba Shaedlass", tgt="Vigía del Alba Shaedlass", desc="Requiere nivel 18; acéptala de paso al entrar en Darnassus en la {s:02-13}."}, [4]={npc="Gerrig Agarrahueso", tgt="Gerrig Agarrahueso", desc="Requiere nivel 18. La próxima vez que pases por Ventormenta, toma el Tranvía Subterráneo a Forjaz para aceptarla, o sáltala si no quieres ir expresamente."}, [5]={text="Entrada: Cavernas de Brazanegra"}, [6]={hint="Lleva el manuscrito de Lorgalis a Gerrig Agarrahueso en la Caverna Abandonada de Forjaz."}, [7]={hint="Gershala Susurro Nocturno en Auberdine quiere 8 bulbos raquídeos corruptos."}, [8]={npc="Guardia Argenta Thaelrid", tgt="Guardia Argenta Thaelrid"}, [9]={npc="Guardia Argenta Thaelrid", tgt="Guardia Argenta Thaelrid"}, [10]={hint="Lleva 10 colgantes crepusculares al guardia argenta Manados en Darnassus."}, [11]={hint="Lleva la cabeza del señor crepuscular Kelris al vigía del alba Selgorm en Darnassus."}, [12]={npc="Gershala Susurro Nocturno", tgt="Gershala Susurro Nocturno"}, [13]={npc="Guardia Argenta Manados", tgt="Guardia Argenta Manados"}, [14]={npc="Vigía del Alba Selgorm", tgt="Vigía del Alba Selgorm"}, [15]={npc="Gerrig Agarrahueso", tgt="Gerrig Agarrahueso"}}},
