    ["03-26"] = {name="Vega de Tuercespina", steps={[1]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [2]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Opcional, Grupo recomendado"}, [3]={hint="Utiliza la pesadilla de Morbent contra Morbent Vil, mata a Morbent Vil y luego ve al campamento de Sven y devuélvele la pesadilla de Morbent.", tag="Opcional, Grupo recomendado", desc="Las siguientes son misiones élite. Hazlas solo en grupo."}, [4]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Opcional, Grupo recomendado"}, [5]={text="Desde el oeste del Bosque del Ocaso, sigue el camino al sur hasta Vega de Tuercespina y ve primero al Campamento Rebelde."}, [6]={npc="Soldado Thorsen", tgt="Soldado Thorsen", tag="Opcional, Hazla si la encuentras", desc="Patrulla por el camino y solo da la misión si lo salvas cuando le tienden una emboscada; si no te lo encuentras, sáltatela."}, [7]={npc="Sargento Yohwa", tgt="Sargento Yohwa"}, [8]={npc="Sargento Yohwa", tgt="Sargento Yohwa"}, [9]={npc="Teniente Doren", tgt="Teniente Doren", tag="Opcional"}, [10]={npc="Teniente Doren", tgt="Teniente Doren"}, [11]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra"}, [12]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [13]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [14]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional", desc="Las páginas caen al azar de los enemigos de Tuercespina. Compra las que falten en la casa de subastas y entrega cuando tengas los cuatro capítulos."}, [15]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [16]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [17]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [18]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [19]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [20]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [21]={hint="Ajeck Rouack de la Expedición de Nesingwary quiere que mates 10 tigres jóvenes de Tuercespina."}, [22]={npc