    ["03-27"] = {steps={[1]={npc="Jennea Cañón", tgt="Jennea Cañón", tag="Puedes comprar ya en la casa de subastas (o pedir a un alter que te lo envíe) 1 × Jade (para Objetos de poder, más adelante en el Marjal Revolcafango).", desc="Entrégala a Tabetha en el Marjal Revolcafango."}, [3]={npc="Elling Trias", tgt="Elling Trias"}, [4]={npc="Elling Trias", tgt="Elling Trias"}, [5]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [6]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [7]={hint="Derrota a Dashel Puñopiedra en Ventormenta."}, [8]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [9]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [10]={npc="Elling Trias", tgt="Elling Trias"}, [11]={npc="Elling Trias", tgt="Elling Trias"}, [12]={text="Ve al Distrito de los Enanos de Ventormenta y toma el Tranvía Subterráneo a Forjaz."}, [13]={npc="Gran mampostero Marmolez", tgt="Gran mampostero Marmolez"}, [14]={npc="Gran mampostero Marmolez", tgt="Gran mampostero Marmolez"}, [15]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [16]={npc="Gerrig Agarrahueso", tgt="Gerrig Agarrahueso", tag="Opcional", desc="Entrégala solo si recogiste Libro: Los Poderes inferiores en Costa Oscura."}, [17]={npc="Alto expedicionario Magellas", tgt="Alto expedicionario Magellas"}, [18]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [19]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [20]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [21]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [22]={npc="Yago Llavenegra", tgt="Yago Llavenegra"}, [23]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Vuela de Forjaz a Bahía del Botín (con escala en Ventormenta) y toma el barco a Trinquete."}, [24]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [25]={npc="Krom Brazorrecio", tgt="Krom Brazorrecio", desc="Toma el barco de Trinquete a Bahía del Botín y vuela a Forjaz."}, [26]={npc="Krom Brazorrecio", tgt="Krom B