    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="Centinela Melyria Sombrigélida", tgt="Centinela Melyria Sombrigélida"}, [3]={npc="Illiyana", tgt="Illiyana"}, [4]={npc="Pelturas Lunablanca", tgt="Pelturas Lunablanca"}, [5]={text="Rodea por el norte y entra en el valle desde aquí."}, [6]={hint="Ve a la Vega del Aullido y estudia el libro de Mel'Thandris. Luego, regresa con la centinela Melyria Sombrigélida en el Santuario de Aessina.", desc="Entra en la cueva para coger el libro. Es fácil atraer de más, y es más difícil si está el raro."}, [7]={hint="Recupera una piedra lunar caída del Oráculo Sombramatorral y llévasela a Pelturas en Astranaar."}, [8]={text="Vuelve a la carretera principal del norte y entra en el valle por este desvío."}, [9]={hint="Libera las almas de los Altonato atrapadas en la Senda de la Noche y en Satyrnaar y vuelve junto a Delgren el Purificador en la Atalaya de Maestra."}, [10]={npc="Anilia", tgt="Anilia"}, [11]={npc="Anilia", tgt="Anilia"}, [12]={hint="Mata a Geltharis y vuelve a ver a Illiyana con la rama de Cenarius en el Santuario de Aessina."}, [13]={npc="Kayneth Ventoleve", tgt="Kayneth Ventoleve"}, [14]={npc="Maseara Lunaotoño", tgt="Maseara Lunaotoño"}, [15]={hint="Maseara Lunaotoño quiere que busques al oeste de Canción del Bosque, cerca de los demonios Satyrnaar. Infórmale cualquier señal que encuentres de Kurothel, su esposo."}, [16]={npc="Maseara Lunaotoño", tgt="Maseara Lunaotoño"}, [17]={nodeA="{a:3137}", node="Talrendis Point", desc="Desde Canción del Bosque, sigue el camino hacia el este hasta entrar en Azshara; el campamento está justo al lado de la entrada."}, [18]={to="Astranaar", toA="{a:415}"}, [19]={npc="Pelturas Lunablanca", tgt="Pelturas Lunablanca"}, [20]={npc="Centinela Melyria Sombrigélida", tgt="Centinela Melyria Sombrigélida"}, [21]={npc="Centinela Melyria Sombrigélida", tgt="Centinela Melyria Sombrigélida", tag="Opcional"}, [22]={npc="Illiyana", tgt="Illiyana"}, [23]={npc="Delgren el Purificador", tgt="Delgren el Purificador"}}},
    ["03-29"] = {grind={[1]={mob="Observador Piedra de sal", note="El extremo sur de El Desierto de Sal; enemigos normales, en la misma zona que los basiliscos de Un bache en la carretera."}, [2]={mob="Vitropiel Piedra de sal", note="Mezclados con los Observadores; hay más y son de nivel un poco más bajo."}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="Opcional", desc="Poca experiencia en el tramo de Darnassus. Omítelo si tienes prisa."}, [2]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus.", tag="Opcional"}, [3]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [4]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [5]={hint="Busca el diario de Velinde en su cofre y llévaselo, junto con la llave, a Thyn'tel Tejespada a Darnassus.", tag="Opcional"}, [6]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [7]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [8]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran.", tag="Opcional"}, [9]={text="Si hiciste las misiones opcionales de Darnassus, vuela de Aldea Rut'theran a Trinquete (con escalas en Auberdine y Punta Talrendis); si las saltaste, vuela desde Astranaar (con escala en Punta Talrendis). Sigue el camino principal hacia el sur, rodea el Campamento Taurajo y baja a Las Mil Agujas por el Gran Elevador. Usa la Empalizada de Mor'shan solo si no has descubierto ninguno de los dos puntos."}, [10]={text="Baja hasta el fondo en el Gran Elevador."}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón"}, [13]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón"}, [14]={npc="Fizzle Pernolatón", tgt="Fizzle Pernolatón"}, [15]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [16]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [17]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [18]={npc="Pozzik", tgt="Pozzik"}, [19]={npc="Maestro rastreador Zherin", tgt="Maestro rastreador Zherin"}, [20]={hint="Consigue 10 huesos huecos de buitre para Pozzik en El Desierto de Sal."}, [21]={hint="El maestro rastreador Zherin quiere que mates a 10 basiliscos Piedra de sal, 10 vitropieles Piedra de sal y 6 observadores Piedra de sal en El Desierto de Sal."}, [22]={hint="Llévale 9 caparazones de tortuga endurecidos a Wizzle Pernolatón, que está en El Desierto de Sal."}, [23]={hint="Llévale 30 piezas de coche cohete a Kravel Karbarbán, que está en El Desierto de Sal."}, [24]={hint="Llévale 6 glándulas de veneno de escórpidos salados a Fizzle Pernolatón, que está en El Desierto de Sal."}, [25]={npc="Pozzik", tgt="Pozzik"}, [26]={npc="Maestro rastreador Zherin", tgt="Maestro rastreador Zherin"}, [27]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón"}, [28]={npc="Fizzle Pernolatón", tgt="Fizzle Pernolatón"}, [29]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [30]={desc="Si aún no eres nivel 35 antes de salir de El Desierto de Sal, sube al 35 matando Observadores Piedra de sal y Vitropieles Piedra de sal al sur de la pista de carreras."}, [31]={text="Desde El Desierto de Sal, sigue el camino al sur hasta Tanaris, abre el punto de vuelo de Gadgetzan y luego usa la piedra de hogar.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [32]={nodeA="{a:976}", node="Gadgetzan"}, [33]={}}},
    ["03-30"] = {name="Tierras Altas de Arathi", grind={[1]={mob="Kóbold Mostacho Seco", note="Por la entrada del Cañón Mostacho Seco; enemigos normales, justo al lado de donde terminas La princesa encerrada."}, [2]={mob="Cavador Mostacho Seco", note="Junto al cristal, en lo profundo del cañón; de nivel más adecuado."}, [3]={mob="Tosco Puño de Roca", note="Los ogros de los alrededores de la Sala Puño de Roca; te quedan de paso cuando vayas por la varita."}, [4]={mob="Cazador de las Sombras Secacorteza", note="El Poblado Secacorteza, al sureste; los mismos trols que para Valer su peso en oro."}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="Si no tienes Refugio de la Zaga, vuela a Puerto de Menethil, sigue el camino al noreste por Los Humedales, cruza el Puente Thandol hasta las Tierras Altas de Arathi y sigue la carretera hasta Refugio de la Zaga."}, [2]={npc="Capitana Nials", tgt="Capitana Nials"}, [3]={npc="Tablón de Se busca", npcObj=true, tag="Grupo recomendado, Opcional"}, [4]={npc="Tablón de Se busca", npcObj=true, tag="Grupo recomendado, Opcional", desc="Otto y Lord Cresta de Halcón son élites de nivel 38 y 40."}, [5]={npc="Skuerto", tgt="Skuerto"}, [6]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten"}, [7]={npc="Fragmentos de Myzrael", npcObj=true}, [8]={hint="Recolecta 12 motas de Myzrael y llévalas a los fragmentos iridiscentes en el Cañón Mostacho Seco."}, [9]={npc="Fragmentos iridiscentes", npcObj=true}, [10]={desc="Sube hasta unos tres cuartos del nivel 36; mata Kóbolds Mostacho Seco y Cavadores Mostacho Seco aquí mismo, en el Cañón Mostacho Seco."}, [11]={npc="Fragmentos iridiscentes", npcObj=true, desc="La Piedra de Vínculo Este está de camino al oeste, tómala primero; la Piedra de Vínculo Exterior, tómala de camino al Refugio de la Zaga."}, [12]={npc="Quae", tgt="Quae"}, [13]={npc="Quae", tgt="Quae"}, [14]={hint="Encuentra a la mensajera Renegada y lleva su carpeta sellada a Quae cerca de la Granja Go'shek.", desc="La Mensajera Renegada patrulla el camino por la zona de la Granja Go'shek; mátala en cuanto la veas y quédate con la Carpeta sellada."}, [15]={hint="Encuentra 10 colmillos Secacorteza, 4 bolsas de medicina Secacorteza y un cuchillo de cazador de las Sombras para el aprendiz Kryten en el Refugio de la Zaga.", desc="Cuidado con la Mensajera Renegada que patrulla."}, [16]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten"}, [17]={npc="Capitana Nials", tgt="Capitana Nials", desc="Entrega a Demar Brant en el Castillo de Farholde, en Claros del Río; irás allí en la próxima parada."}, [18]={npc="Skuerto", tgt="Skuerto"}, [19]={desc="Si aún no eres nivel 37 antes de enfrentarte a Kor'gresh Ira Helada (nivel 39), mata Toscos Puño de Roca fuera de la Sala Puño de Roca o ve al Poblado Secacorteza, al este, y mata Trols Secacorteza hasta el 37."}, [20]={hint="Encuentra la varita de evocación de Trelane y llévasela a Skuerto en el Refugio de la Zaga."}, [21]={npc="Quae", tgt="Quae"}, [22]={npc="Quae", tgt="Quae"}, [23]={npc="Kinelory", tgt="Kinelory"}, [24]={npc="Kinelory", tgt="Kinelory"}, [25]={hint="Protege a Kinelory hasta que haya regresado con Quae.", desc="Misión de escolta; sigue a Kinelory, habrá emboscadas por el camino."}, [26]={npc="Quae", tgt="Quae"}, [27]={npc="Quae", tgt="Quae"}, [28]={npc="Skuerto", tgt="Skuerto"}, [29]={npc="Skuerto", tgt="Skuerto", tag="Grupo recomendado, Opcional"}, [30]={hint="Reúne la llave ardiente, la llave blasonada y la llave del trueno de la Piedra de Vínculo Occidental, la Piedra de Vínculo Este y la Piedra de Vínculo Exterior."}, [31]={hint="Mata a 10 bandoleros de la Hermandad y 6 mercenarios de la Hermandad."}, [32]={npc="Capitana Nials", tgt="Capitana Nials"}, [33]={npc="Capitana Nials", tgt="Capitana Nials", tag="Grupo recomendado, Opcional"}, [34]={npc="Piedra de Vínculo Interior", npcObj=true}, [35]={hint="Llévale la cabeza de Marez a la capitana Nials en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [36]={hint="Llévale la cabeza de Otto y la de Lord Falconcrest a la capitana Nials en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [37]={hint="Lleva distintivos de Stromgarde a la capitana Nials en Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [38]={hint="Encuentra un ágata azur y llévasela al aprendiz Kryten en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [39]={npc="Capitana Nials", tgt="Capitana Nials", tag="Grupo recomendado, Opcional"}, [40]={npc="Capitana Nials", tgt="Capitana Nials", tag="Grupo recomendado, Opcional"}, [41]={npc="Capitana Nials", tgt="Capitana Nials", tag="Grupo recomendado, Opcional"}, [42]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten", tag="Grupo recomendado, Opcional"}, [43]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten"}, [44]={npc="Skuerto", tgt="Skuerto"}, [45]={npc="Skuerto", tgt="Skuerto"}, [46]={hint="Encuentra la filacteria de Trelane, el orbe de Trelane y el ágata de ascuas de Trelane, y llévaselo todo a Skuerto en el Refugio de la Zaga.", tag="Hazla cuando te quede de paso"}, [47]={npc="Skuerto", tgt="Skuerto"}, [48]={npc="Skuerto", tgt="Skuerto"}, [49]={hint="Roba un uniforme de la Hermandad de la Mansión Redilnorte para infiltrarte en el Castillo de Stromgarde.", desc="Roba un uniforme de la Hermandad en la Mansión Redilnorte, en las Tierras Altas de Arathi."}, [50]={npc="Baúl de la Hermandad", npcObj=true}, [51]={npc="Baúl de la Hermandad", npcObj=true}, [52]={hint="Mientras estás disfrazado como un miembro de la Hermandad, encuentra a alguien dentro del Castillo de Stromgarde que sepa sobre el acuerdo secreto."}, [53]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [54]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [55]={hint="Encuentra algo dentro del Castillo de Stromgarde que convenza a Anastasia de darte detalles sobre el acuerdo secreto."}, [56]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [57]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [58]={hint="Interrumpe el intercambio secreto y obtén el objeto que la Hermandad quiere conseguir. Luego, regresa con Myrokos Silenforma en la Mansión Ravenholdt."}, [59]={npc="Myrokos Silenforma", tgt="Myrokos Silenforma"}, [60]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno"}, [61]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Grupo recomendado, Opcional", desc="Requiere hacer Horado Rajacieno (la mazmorra del sur de Los Baldíos); hazla cuando tengas grupo. Sáltate también la continuación, Tormenta, Tierra y Fuego."}, [62]={hint="Derrota a Chargla Filonavaja en Horado Rajacieno y consigue información acerca de los planes de los jabaespines.", tag="Grupo recomendado, Opcional"}, [63]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Grupo recomendado, Opcional", desc="A Veyric Horcatrueno también lo encuentras en Forjaz (47.10, 13.79)."}, [64]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Opcional", desc="Los cuatro tipos de tótems retorcidos los sueltan los enemigos de Marjal Revolcafango, las Tierras Inhóspitas, el Pantano de las Penas y Desolace; ve reuniéndolos por el camino en las próximas paradas. Al final, entrégala a Veyric Horcatrueno en Forjaz."}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="Phin Odelic", tgt="Phin Odelic"}, [67]={npc="Magistrado Henry Maleb", tgt="Magistrado Henry Maleb"}, [68]={desc="Si tu piedra de hogar está en reutilización, vuela de Costasur a Forjaz y toma el Tranvía Subterráneo de vuelta a Ventormenta."}}},
    ["05-d8"] = {name="Monasterio Escarlata", entrance="Claros de Tirisfal 82.60, 33.80", pickup="Acepta las misiones de la mazmorra al pasar por Los Humedales (2.ª visita); así no tendrás que volver antes de entrar.", pickupS={{"Acepta las misiones de la mazmorra al pasar por Los Humedales (2.ª visita); así no tendrás que volver antes de entrar"}}, steps={[1]={npc="Bibliotecaria Mae Palipolvo", tgt="Bibliotecaria Mae Palipolvo"}, [2]={to="Southshore", toA="{a:271}", desc="Harás escala en Forjaz."}, [3]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional"}, [4]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Grupo recomendado"}, [5]={npc="Magus Olvek", tgt="Magus Olvek", tag="Opcional"}, [6]={text="Desde Trabalomas, ve al oeste al Bosque de Argénteos y sigue la carretera principal hacia el norte hasta Tirisfal. Rodea los guardias de El Sepulcro, Entrañas y Brill y sigue al Monasterio Escarlata al noreste."}, [7]={text="Entrada: Monasterio Escarlata"}, [8]={hint="Coge Mitología de los titanes en el monasterio y llévaselo a la bibliotecaria Mae Palipolvo a Forjaz.", desc="Ubicación: Estante de libros en las últimas salas de la biblioteca.", spot="Estante de libros en las últimas salas de la biblioteca."}, [9]={hint="Ve al Monasterio Escarlata y recupera el libro La magia perdida de los maestros de runas.", tag="Opcional"}, [10]={hint="Mata a la alta inquisidora Melenablanca, al Comandante Escarlata Mograine, a Herod, el Campeón Escarlata y al maestro de canes Loksey. A continuación, preséntate ante Raleigh el Devoto, en Costasur.", tag="Opcional", desc="Derrota a Loksey en la biblioteca, a Herod en la armería y a Mograine y Melenablanca en la catedral. Puedes completar las alas en visitas distintas."}, [11]={npc="Magus Olvek", tgt="Magus Olvek", tag="Opcional"}, [12]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Requiere materiales"}, [13]={npc="Bibliotecaria Mae Palipolvo", tgt="Bibliotecaria Mae Palipolvo", tag="Opcional", desc="Regresa por Tirisfal y el Bosque de Argénteos hasta Costasur. Vuela a Forjaz si tienes la ruta. Si no, toma el barco al Puerto de Menethil, sigue el camino de montaña al sur de Los Humedales hasta Loch Modan y cruza el túnel hacia Dun Morogh para llegar a Forjaz. Si tienes la piedra de hogar lista y vinculada a Ventormenta, puedes volver allí y tomar el Tranvía Subterráneo."}}},
    ["03-31"] = {tips={{k="提醒", text="Rog'mar, en el centro del mapa, es una población de la Horda; no te acerques.", s={{"Rog'mar, en el centro del mapa, es una población de la Horda; no te acerques"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="Antes de ir a Claros del Río, puedes comprar en la casa de subastas (o pedir a un alter que te lo envíe) 8 × Piedra de afilar sólida (para Las hojas más afiladas).", desc="El Castillo de Farholde aún no tiene punto de vuelo, así que la primera vez ve al este por el camino desde Villa del Lago hasta la entrada occidental de Claros del Río."}, [2]={npc="Dorin Filosón", tgt="Dorin Filosón", tag="Opcional, Grupo recomendado"}, [3]={text="Tras la entrada al este de las Montañas Crestagrana están las Colinas Erizadas; los gnolls de nivel 36-38 de la entrada golpean fuerte.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [4]={npc="Explorador Bolain", tgt="Explorador Bolain"}, [5]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [6]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [7]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [8]={npc="Cedric Dalton", tgt="Cedric Dalton", tag="Opcional, Grupo recomendado", desc="Snargl es un élite de nivel 40; si no puedes con él, sáltatelo."}, [9]={npc="Curly", tgt="Curly"}, [10]={npc="Halligan Turner", tgt="Halligan Turner"}, [11]={npc="Halligan Turner", tgt="Halligan Turner"}, [12]={npc="Hurley", tgt="Hurley"}, [13]={npc="Hurley", tgt="Hurley"}, [14]={hint="Ve con Hurley a salvar a Curly.", desc="Sigue a Hurley para rescatar a Curly."}, [15]={hint="Mata a 8 místicos de Crestagrana, 8 tramperos de Crestagrana y 6 toscos de Crestagrana a pedido de Cedric Dalton en Avanzada del Sur."}, [16]={hint="Recupera 8 hojas serradas de los campamentos gnoll en las Colinas Espinosas y llévaselas a Halligan Turner en el aserradero.", desc="Las hojas de sierra están esparcidas por el suelo del campamento gnoll."}, [17]={hint="Busca a Snargl en las Colinas Espinosas, mátalo, toma su hocico y llévaselo a Cedric Dalton en Avanzada del Sur.", tag="Opcional, Grupo recomendado", desc="Snargl es un élite de nivel 40; si no puedes con él, sáltatelo."}, [18]={npc="Halligan Turner", tgt="Halligan Turner"}, [19]={npc="Halligan Turner", tgt="Halligan Turner"}, [20]={npc="Eleanor Holmsby", tgt="Eleanor Holmsby"}, [21]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [22]={npc="Vigía Fredericks", tgt="Vigía Fredericks"}, [23]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [24]={npc="Cedric Dalton", tgt="Cedric Dalton", tag="Opcional"}, [25]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [26]={hint="Mata a 8 oráculos Aletalodos y 8 guerreros Aletalodo a lo largo del río cerca de Cortijo de Wheeler."}, [27]={hint="Reúne 4 caparazones de centollo gigante, 4 piezas de estiércol fresco y 8 cabezas de múrloc Aletalodo para Halligan Turner.", desc="Mata a los múrlocs Aletabarro para sacar las cabezas y a los demonios de agua dulce; luego ve al norte a matar langostas enormes y recoger Fertilizante fresco."}, [28]={hint="Encuentra el sombrero de Robbie en el río cerca de los múrlocs.", desc="Busca el sombrero en el campamento de los múrlocs Aletabarro."}, [29]={nodeA="{a:16724}", node="Farholde Keep"}, [30]={npc="Demar Brant", tgt="Demar Brant"}, [31]={npc="Demar Brant", tgt="Demar Brant"}, [32]={npc="Demar Brant", tgt="Demar Brant"}, [33]={npc="Demar Brant", tgt="Demar Brant"}, [34]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [35]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [36]={npc="Ember Filosusurro", tgt="Ember Filosusurro"}, [37]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [38]={npc="Bertrand Frente Férrea", tgt="Bertrand Frente Férrea"}, [39]={npc="Cassandra Wheeler", tgt="Cassandra Wheeler"}, [40]={hint="Mata 5 murciumbríos posados en la Catedral de Farholde para la hermana Rowland."}, [41]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [42]={npc="Hermana Rowland", tgt="Hermana Rowland", tag="Opcional, Requiere materiales", desc="Requiere 5 velas sagradas, que venden los vendedores de componentes. Si no las tienes, sáltate esta misión y la siguiente."}, [43]={npc="Hermana Rowland", tgt="Hermana Rowland", tag="Opcional"}, [44]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [45]={hint="Pon 3 velas conmemorativas en las tumbas del cementerio de la capilla para la hermana Rowland en la Fortaleza de Farholde.", desc="La tumba está junto a la capilla de Farholde."}, [46]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [47]={hint="Reúne 3 fardos de heno para Ember en el campo de entrenamiento.", desc="Las pacas de heno están en los campos cerca de Farholde."}, [48]={npc="Ember Filosusurro", tgt="Ember Filosusurro"}, [49]={npc="Ember Filosusurro", tgt="Ember Filosusurro", tag="Opcional, Requiere materiales", desc="Necesita 8 × Piedra de afilar sólida. Cómpralas en la casa de subastas o pídeselas a un herrero. Sáltala si no los llevas encima."}, [50]={npc="Ember Filosusurro", tgt="Ember Filosusurro", tag="Opcional"}, [51]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [52]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [53]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [54]={hint="Busca pistas del paradero de los caballos desaparecidos cerca de los establos de Cortijo de Wheeler.", desc="Busca pruebas alrededor de los establos de la granja."}, [55]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [56]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [57]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [58]={hint="Mata al coyote Pelihollín y trae su piel a Benjy Wheeler."}, [59]={hint="Encuentra uno de los caballos que huyó de Cortijo de Wheeler después del ataque de los coyotes y dale un poco de pienso.", desc="El caballo perdido está cerca de la granja."}, [60]={npc="Caballo perdido", tgt="Caballo perdido"}, [61]={npc="Caballo perdido", tgt="Caballo perdido"}, [62]={hint="Lleva el caballo perdido de vuelta a Cortijo de Wheeler.", desc="Lleva el caballo extraviado de vuelta a la granja."}, [63]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [64]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [65]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [66]={npc="Halligan Turner", tgt="Halligan Turner"}, [67]={npc="Halligan Turner", tgt="Halligan Turner"}, [68]={npc="Halligan Turner", tgt="Halligan Turner"}, [69]={hint="Planta 5 retoños en el aserradero con el kit para germinar árboles de Halligan Turner."}, [70]={npc="Halligan Turner", tgt="Halligan Turner"}, [71]={hint="Encuentra el cajón de supervisor y llévaselo a Bertrand Frente Férrea en la Fortaleza de Farholde.", desc="La caja del capataz está en el aserradero de Turner."}, [72]={npc="Granjero Elbrim", tgt="Granjero Elbrim"}, [73]={npc="Pelusa", tgt="Pelusa"}, [74]={hint="Ayuda a Demar Brant a derrotar a 8 Asaltantes Crepusculares, 8 Sombramantes Crepusculares y 8 Neófitos Crepusculares en Claro Soleado."}, [75]={hint="Recoge 5 recuerdos de los granjeros que tienen los asaltantes Crepusculares y colócalos en las tumbas al oeste de la Granja de Elbrim.", desc="Mata a los Asaltantes Crepusculares para conseguir los recuerdos y colócalos en las tumbas al oeste de la Granja de Elbrim."}, [76]={hint="Reúne 25 talismanes crepusculares de sombramantes Crepusculares y neófitos Crepusculares en Claro Soleado para Ashe Salámbar, que se encuentra en la Fortaleza de Farholde."}, [77]={hint="Reúne 5 páginas crepusculares en Claro Soleado para Ashe Salámbar, que se encuentra en la Fortaleza de Farholde.", desc="Las páginas del Crepúsculo están esparcidas por Claro Soleado."}, [78]={npc="Registro de mariscal de campo", npcObj=true, tag="Acepta si cae, Opcional", desc="Los Crepusculares sueltan el registro de Mariscal de campo; haz clic derecho en él en tu mochila para aceptar la misión."}, [79]={hint="Llévale 20 falanges crepusculares a Pelusa.", desc="Los dedos óseos Crepusculares salen de los mismos Crepusculares que para Salvar Clarosol."}, [80]={npc="Pelusa", tgt="Pelusa"}, [81]={npc="Pelusa", tgt="Pelusa", desc="Sigue a Pelusa mientras huye. Al final se vuelve contra ti con 2 gnolls;