    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="Maestro de vigilantes Sorigal", tgt="Maestro de vigilantes Sorigal"}, [3]={text="Desde Villa Oscura, ve al este por el Paso de la Muerte hasta el Pantano de las Penas."}, [4]={npc="Vigía Biggs", tgt="Vigía Biggs"}, [5]={hint="Llévale 10 pizcas de polvo onírico a Krazek a Bahía del Botín. El polvo onírico se obtiene de las crías de dragón que habitan en el Pantano de las Penas."}, [6]={hint="Mata a 8 crocoliscos Denteserra jóvenes, 10 hilapenas y 10 jaguares del pantano, y después ve a ver al vigía Biggs al Pantano de las Penas."}, [7]={npc="Vigía Biggs", tgt="Vigía Biggs"}, [8]={npc="Vigía Biggs", tgt="Vigía Biggs"}, [9]={npc="Cayada de Noboru", npcObj=true, tag="Opcional", desc="Haz clic derecho en Cayada de Noboru en tu bolsa para empezar la misión. Mata a Noboru el Garrote para conseguir una cayada gris y haz clic derecho en ella para empezar la misión."}, [10]={npc="Magtoor", tgt="Magtoor", tag="Opcional"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={hint="Llévale 6 cristales draenetistas a Magtoor que está en El Puerto del Pantano de las Penas."}, [13]={hint="Encuentra el cofre de la caravana en Retiro Fangoso, consigue los componentes de zahorí y llévaselos al vigía Biggs."}, [14]={npc="Galen Bonguarda", tgt="Galen Bonguarda"}, [15]={hint="Pon a salvo a Galen, y después encuentra su campamento en el Pantano de las Penas y abre su caja fuerte.", tag="Escolta", desc="Sigue a Galen para salir del Retiro Fangoso (el campamento de los Perdidos); los enemigos del camino lo atacarán, así que protégelo. Tras la escolta, ve a su campamento y abre la caja fuerte."}, [16]={npc="Caja fuerte de Galen", npcObj=true}, [17]={npc="Magtoor", tgt="Magtoor"}, [18]={npc="Vigía Biggs", tgt="Vigía Biggs"}, [19]={npc="Vigía Biggs", tgt="Vigía Biggs"}, [20]={hint="Llévale 8 piezas de madera a la deriva desecada al vigilante Biggs en el Pantano de las Penas."}, [21]={hint="Brohann Barriliga, en Ventormenta, quiere que