    ["03-37"] = {tips={{k="提醒", text="Rog'mar, en el centro del mapa, es una población de la Horda; no te acerques.", s={{"Rog'mar, en el centro del mapa, es una población de la Horda; no te acerques"}}}}, steps={[1]={to="Farholde Keep", toA="{a:16724}", tag="Antes de ir a Claros del Río, puedes comprar en la casa de subastas (o pedir a un alter que te lo envíe) 20 × Paño de tejido mágico (para Gasas para heridas).", desc="Harás escala en Villa Oscura y Villa del Lago."}, [2]={npc="Demar Brant", tgt="Demar Brant"}, [3]={npc="Demar Brant", tgt="Demar Brant"}, [4]={npc="Demar Brant", tgt="Demar Brant", desc="Primero tienes que entregar el Registro de mariscal de campo que se activa al soltarse, o no podrás aceptarla."}, [5]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [6]={npc="Bertrand Frente Férrea", tgt="Bertrand Frente Férrea"}, [7]={npc="Hermano Lowley", tgt="Hermano Lowley", tag="Opcional, Requiere materiales", desc="Necesita 20 × Paño de tejido mágico. Se puede comprar en la casa de subastas. Sáltala si no los llevas encima."}, [8]={npc="Hermano Lowley", tgt="Hermano Lowley", tag="Opcional"}, [9]={npc="Hermano Lowley", tgt="Hermano Lowley"}, [10]={hint="Venda a 3 soldados heridos para el hermano Lowley.", desc="Los soldados heridos están justo al lado del Hermano Lowley."}, [11]={npc="Hermano Lowley", tgt="Hermano Lowley"}, [12]={npc="Hermano Lowley", tgt="Hermano Lowley"}, [13]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [14]={npc="Tessa Deslumbralba", tgt="Tessa Deslumbralba"}, [15]={hint="Reúne 6 manzanas frescas para Tessa Deslumbralba en la Fortaleza de Farholde.", desc="Las manzanas frescas están bajo los manzanos cerca de Farholde."}, [16]={npc="Tessa Deslumbralba", tgt="Tessa Deslumbralba"}, [17]={npc="Tessa Deslumbralba", tgt="Tessa Deslumbralba"}, [18]={hint="Reúne 3 pelambres de coyote para Tessa Deslumbralba en la Fortaleza de Farholde."}, [19]={npc="Tessa Deslumbralba", tgt="Tessa Deslumbralba"}, [20]={npc="Tessa Deslumbralba", tgt="Tessa Deslumbralba"}, [21]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [22]={text="Desde la Avanzada de Terral ve al oeste, pasando al sur de Clarosol, hasta el sargento Riftan, frente a Sudario Crepuscular. Al pasar por el Aserradero de Turner, recoge la madera."}, [23]={hint="Recoge 10 fardos de madera del Aserradero de Turner para Bertrand Frente Férrea en la Fortaleza de Farholde.", desc="Las pilas de madera están en el aserradero de Turner."}, [24]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [25]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [26]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [27]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [28]={hint="Invoca a un esclavo Crepuscular de un conducto en el Sudario Crepuscular y captúralo con la piedra de alma de Salámbar.", desc="En el conducto de Sudario Crepuscular, invoca a un Siervo Crepuscular y captúralo con una piedra de alma."}, [29]={npc="Alguacil Ryan", tgt="Alguacil Ryan"}, [30]={npc="Alguacil Ryan", tgt="Alguacil Ryan"}, [31]={hint="Ayuda al sargento Riftan a rescatar a 5 exploradores de Farholde en el Sudario Crepuscular.", desc="Los exploradores están encerrados por todo el Sudario Crepuscular."}, [32]={hint="Derrota a 8 fanáticos Crepusculares, a 8 corruptores Crepusculares y a 8 campeones Crepusculares dentro del Sudario Crepuscular para el sargento Riftan."}, [33]={hint="Ayuda al sargento Riftan a derrotar a 5 mineros ogros y 5 subyugadores Crepusculares en la cueva cerca del Sudario Crepuscular."}, [34]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [35]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [36]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [37]={npc="Sargento Riftan", tgt="Sargento Riftan", tag="Opcional, Grupo recomendado", desc="Señor supremo Kilgar es un élite de nivel 46."}, [38]={hint="Derrota al señor supremo Kilgar en el Sudario Crepuscular y llévale su cabeza al sargento Riftan.", tag="Opcional, Grupo recomendado", desc="Señor supremo Kilgar es un élite de nivel 46."}, 