    ["03-38"] = {steps={[1]={npc="Klannoc Macleod", tgt="Klannoc Macleod"}, [2]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Derrota cuatro oleadas de rivales seguidas en la arena de Isla de Batalla."}, [3]={hint="Mata a Will el Grande y habla con Klannoc Macleod en Isla de Batalla.", desc="Derrota cuatro oleadas de rivales seguidas en la arena de Isla de Batalla."}, [4]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Derrota cuatro oleadas de rivales seguidas en la arena de Isla de Batalla."}, [5]={npc="Klannoc Macleod", tgt="Klannoc Macleod"}, [6]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Necesitas unas Togas de Arcana. Pídeselas a un sastre o cómpralas en la casa de subastas."}, [7]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Necesitas unas Togas de Arcana. Pídeselas a un sastre o cómpralas en la casa de subastas."}, [8]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Barra de oro ×1 se puede comprar en la casa de subastas."}, [9]={hint="Llévale un lingote de oro a Xizk Cortefino en la Vega de Tuercespina."}, [10]={npc="Xizk Cortefino", tgt="Xizk Cortefino", desc="Toma el barco de Trinquete a Bahía del Botín."}, [11]={npc="Xizk Cortefino", tgt="Xizk Cortefino"}, [12]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Toma el barco de Bahía del Botín de vuelta a Trinquete."}, [13]={npc="Menara Nadiz", tgt="Menara Nadiz"}, [14]={hint="Llévale 10 viales de sangre Odio Feroz y 1 piedra Infernal inferior a Menara Nadiz en Los Baldíos."}, [15]={npc="Menara Nadiz", tgt="Menara Nadiz"}, [16]={npc="Xizk Cortefino", tgt="Xizk Cortefino", desc="Toma el barco de Trinquete a Bahía del Botín."}, [17]={npc="Xizk Cortefino", tgt="Xizk Cortefino"}, [18]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Toma el barco de Bahía del Botín de vuelta a Trinquete."}, [19]={hint="Llévale unos hilos finos de oro, 2 trozos de ascuas humeantes y 1 fragmento de alma a Menara Nadiz en Los Baldíos.", desc="Tramo de Arathi: toma el barco de Trinquete a Bahía del Botín y vuela al Refugio de la Zaga (con escalas en Ventormenta y Forjaz). A la vuelta, haz el camino inverso."}, [20]={npc="Menara Nadiz", tgt="Menara Nadiz"}, [21]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Recompensa: Toga de sangre dorada encantada."}, [22]={hint="Espera a que Menara Nadiz complete tu túnica y vuelve entonces a hablar con ella.", desc="Recompensa: Toga de sangre dorada encantada."}, [23]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Recompensa: Toga de sangre dorada encantada."}, [24]={npc="Menara Nadiz", tgt="Menara Nadiz"}, [25]={npc="Menara Nadiz", tgt="Menara Nadiz"}, [26]={npc="Acólito Wytula", tgt="Acólito Wytula", desc="Fragmento de manáfago. Elige esta o la Fragmento de infernal."}, [27]={npc="Acólito Magaz", tgt="Acólito Magaz", tag="Opcional", desc="Fragmento de infernal. Elige esta o la Fragmento de can manáfago."}, [28]={hint="Habla con los acólitos de Menara que están en el interior de la torre que domina Trinquete y elige uno de sus caminos para seguirlo."}, [29]={hint="Coge el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago encarcelado a Menara Nadiz en Los Baldíos.", desc="Fragmento de manáfago. Elige esta o la Fragmento de infernal."}, [30]={hint="Coge la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal encarcelado a Menara Nadiz en Los Baldíos.", tag="Opcional", desc="Fragmento de infernal. Elige esta o la Fragmento de can manáfago."}, [31]={npc="Menara Nadiz", tgt="Menara Nadiz", desc="Fragmento de manáfago. Elige esta o la Fragmento de infernal."}, [32]={npc="Menara Nadiz", tgt="Menara Nadiz", tag="Opcional", desc="Fragmento de infernal. Elige esta o la Fragmento de can manáfago."}, [33]={npc="Tabetha", tgt="Tabetha"}, [34]={npc="Tabetha", tgt="Tabetha", tag="Grupo recomendado, Opcional"}, [35]={hint="Mata al demonio del orbe y luego habla con Tabetha.", 