    ["03-40"] = {grind={[1]={mob="Pícaro Vagayermo", note="El campamento Vagayermo al sureste de Gadgetzan; los mismos enemigos que para Justicia para los Vagayermos."}, [2]={mob="Mago oscuro Vagayermo", note="El mismo campamento; lanzadores de hechizos, atráelos de uno en uno."}}, steps={[1]={to="Gadgetzan", toA="{a:976}"}, [2]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [3]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [4]={npc="Fizzle Pernolatón", tgt="Fizzle Pernolatón"}, [5]={npc="Pozzik", tgt="Pozzik"}, [6]={npc="Zamek", tgt="Zamek"}, [7]={npc="Zamek", tgt="Zamek"}, [8]={npc="Planes sin vigilancia de Rizzle", npcObj=true, desc="Espera a que Rizzle Pernolatón salga del edificio antes de actuar."}, [9]={npc="Planes sin vigilancia de Rizzle", npcObj=true}, [10]={npc="Pozzik", tgt="Pozzik"}, [11]={npc="Cartel de Se busca", npcObj=true}, [12]={npc="Cartel de Se busca", npcObj=true}, [13]={npc="Grifoperador Llantalunket", tgt="Grifoperador Llantalunket"}, [14]={npc="Ingeniero jefe Pasaquillas", tgt="Ingeniero jefe Pasaquillas"}, [15]={npc="Jhordy Lapforge", tgt="Jhordy Lapforge"}, [16]={hint="Jhordy Lapforge quiere verte luego de que hayas arrojado el cajón de los residuos radiactivos en el desierto de Tanaris a una distancia segura de Gadgetzan y de otros tipos de basura.", desc="Busca un claro de camino al campamento Vagayermo y usa ahí el objeto de misión."}, [17]={hint="Acaba con 10 bandidos y ladrones Vagayermos al este de Gadgetzan y después vuelve a ver al ingeniero jefe Pasaquillas."}, [18]={desc="Si aún no eres nivel 44, quédate en el campamento Vagayermo y sube al 44 matando Pícaros Vagayermo y Magos oscuros Vagayermo."}, [19]={npc="Modista Jactancia", tgt="Modista Jactancia"}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Stoley", tgt="Stoley"}, [22]={npc="Stoley", tgt="Stoley"}, [23]={npc="Jefe de seguridad Pasaquillas", tgt="Jefe de seguridad Pasaquillas", desc="Déjala para tu segunda visita a Tanaris, cuando pelees contra los ogros Mach