    ["05-d10"] = {name="Zul'Farrak", entrance="Tanaris 38.70, 20.10", pickup="Acepta las misiones de la mazmorra al pasar por Vega de Tuercespina (3.ª visita); así no tendrás que volver antes de entrar.", pickupS={{"Acepta las misiones de la mazmorra al pasar por Vega de Tuercespina (3.ª visita); así no tendrás que volver antes de entrar"}}, steps={[1]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón", tag="Opcional, Grupo recomendado"}, [2]={npc="Tabetha", tgt="Tabetha", tag="Opcional, Grupo recomendado"}, [3]={npc="Krazek", tgt="Krazek"}, [4]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [5]={hint="Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.", tag="Requisito de mazmorra", desc="Mata vociferadores del valle en la costa de la Isla del Terror, en Feralas. Usa la zarza de Yeh'kinya en cada cadáver y habla con el espíritu que aparezca hasta que el registro de misiones cuente tres."}, [6]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [7]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Opcional"}, [8]={npc="Tran'rek", tgt="Tran'rek", tag="Opcional"}, [9]={npc="Ingeniero jefe Pasaquillas", tgt="Ingeniero jefe Pasaquillas", tag="Opcional"}, [10]={npc="Trenton Mazaligera", tgt="Trenton Mazaligera", tag="Opcional"}, [11]={text="Entrada: Zul'Farrak"}, [12]={hint="Lleva la tiara de las profundidades a Tabetha en el Marjal Revolcafango.", tag="Opcional, Grupo recomendado", spot="Derrota a la hidromántica Velratha junto al estanque y recoge su tiara."}, [13]={hint="Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal.", tag="Opcional, Grupo recomendado", spot="Un miembro del grupo necesita el Mazo de Zul'Farrak para invocar a Gahz'rilla con el gong de la poza. Si el jefe ya está presente, derrótenlo y recojan la escama."}, [14]={hint="Lleva el medallón de Nekrum a Thadius Sombramacabra a Las Tierras Devastadas.", tag="Opcional, Grupo recomendado", sp