    ["03-41"] = {steps={[1]={to="Thalanaar", toA="{a:489}"}, [2]={text="Desde Thalanaar ve al oeste por Feralas hasta el muelle de la costa y toma el barco al Bastión Plumaluna."}, [3]={nodeA="{a:1116}", node="Feathermoon Stronghold"}, [4]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [5]={npc="Mardrack Fonverde", tgt="Mardrack Fonverde"}, [6]={text="Vincula tu piedra de hogar en la posada del Bastión Plumaluna (31.00, 43.20).", bindA="{a:1116}"}, [7]={npc="Shandris Plumaluna", tgt="Shandris Plumaluna"}, [8]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna"}, [9]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}, [10]={npc="Angelas Brisaluna", tgt="Angelas Brisaluna"}, [11]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [12]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [13]={npc="Glorieta de Solarsal", npcObj=true}, [14]={npc="Glorieta de Solarsal", npcObj=true}, [15]={npc="Shandris Plumaluna", tgt="Shandris Plumaluna"}, [16]={npc="Shandris Plumaluna", tgt="Shandris Plumaluna"}, [17]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna"}, [18]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna"}, [19]={hint="Consigue 10 escamas de naga Crestafuria para Latronicus Lanzaluna en el Bastión Plumaluna.", desc="Las nagas de la costa al sur de Bastión Plumaluna sueltan escamas; recógelas y vuelve a la fortaleza."}, [20]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna"}, [21]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna", tag="Mobs de nivel superior, Opcional"}, [22]={hint="Elimina a Lord Shalzaru y luego lleva la reliquia misteriosa que desenterró a Latronicus Lanzaluna al Bastión Plumaluna.", tag="Mobs de nivel superior, Opcional"}, [23]={text="Costa de la Isla del Terror: usa la zarza en el cadáver y habla con el espíritu."}, [24]={hint="Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.", desc="Mata vociferadores del valle en la costa de la Isla del Terror, en Feralas. Usa la zarza de Yeh'kinya en cada cadáver y habla con el espíritu que aparezca hasta que el registro de misiones cuente tres."}, [25]={npc="Restos de un bote de remos", npcObj=true}, [26]={npc="Restos de un bote de remos", npcObj=true}, [27]={bindA="{a:1116}"}, [28]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [29]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [30]={npc="Quintis Jonguja", tgt="Quintis Jonguja"}, [31]={npc="Quintis Jonguja", tgt="Quintis Jonguja"}, [32]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [33]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [34]={hint="Lleva 10 pellejos de yeti gruesos a Pratt McGrubben al Bastión Plumaluna."}, [35]={hint="Angelas Brisaluna quiere que mates a 8 brujos Gordunni, 8 chamanes Gordunni y 8 toscos Gordunni."}, [36]={npc="Kindal Tejeluna", tgt="Kindal Tejeluna"}, [37]={hint="Utiliza la llave de jaula de bambú para liberar a los duendes dardo del campamento Tótem Siniestro. Deben sobrevivir al menos 6 duendes dardo y Kindal Tejeluna.", desc="Límite de 6 minutos; antes de aceptar, recupera toda la salud y limpia los monstruos cerca del recinto."}, [38]={npc="Kindal Tejeluna", tgt="Kindal Tejeluna"}, [39]={npc="Jer'kai Tejeluna", tgt="Jer'kai Tejeluna"}, [40]={hint="Mata a 12 naturalistas Tótem Siniestro, 10 asaltantes Tótem Siniestro y 6 chamanes Tótem Siniestro antes de volver con Jer'kai Tejeluna a Feralas."}, [41]={npc="Jer'kai Tejeluna", tgt="Jer'kai Tejeluna"}, [42]={npc="Jer'kai Tejeluna", tgt="Jer'kai Tejeluna"}, [43]={npc="Mochilas de piel grandes", npcObj=true}, [44]={npc="Mochilas de piel grandes", npcObj=true}, [45]={text="El capullo está dentro de la cueva; entra por la boca (73.20, 63.90 → 72.30, 64.20)."}, [46]={npc="Vaina de Zukk'ash", npcObj=true}, [47]={npc="Vaina de Zukk'ash", npcObj=true}, [48]={hint="Libera a Raschal de la vaina de los Zukk'ash."}, [49]={npc="Localizador de emergencia OOX-22/FE", npcObj=true, tag="Acepta si cae, Opcional", desc="Haz clic derecho en el Localizador de emergencia OOX-22/FE en tu bolsa para empezar la misión."}, [50]={npc="Robot mensajero OOX-22/FE", tgt="Robot mensajero OOX-22/FE", tag="Opcional"}, [51]={npc="Robot mensajero OOX-22/FE", tgt="Robot mensajero OOX-22/FE", tag="Opcional"}, [52]={hint="Escolta a OOX-22/FE hasta el muelle de La Costa Olvidada, y preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", tag="Opcional", desc="Escolta al pollo robot hasta el muelle de La Costa Olvidada, al noroeste; hay emboscadas por el camino. Se entrega en Bahía del Botín."}, [53]={hint="Escolta a OOX-22/FE hasta el muelle de La Costa Olvidada, y preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", tag="Opcional", desc="Escolta fallida: abandona la misión en el registro y vuelve a aceptarla del robot."}, [54]={npc="Angelas Brisaluna", tgt="Angelas Brisaluna"}, [55]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [56]={npc="Ginro Mechogar", tgt="Ginro Mechogar"}, [57]={npc="Shandris Plumaluna", tgt="Shandris Plumaluna"}, [58]={npc="Shandris Plumaluna", tgt="Shandris Plumaluna"}, [59]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna"}, [60]={npc="Latronicus Lanzaluna", tgt="Latronicus Lanzaluna"}, [61]={npc="Vestia Lanzaluna", tgt="Vestia Lanzaluna"}, [62]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [63]={to="Rut'theran Village", toA="{a:702}"}}},
    ["04-42"] = {grind={[1]={mob="Quebrador Resptacostas", note="La playa frente al Bastión Plumaluna; llegas en cuanto bajas del barco."}, [2]={mob="Guerrero Crestafuria", note="Los nagas del extremo sur de la Isla de Sardor; cerca del bastión, de nivel un poco más bajo."}}, steps={[1]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [2]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [3]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [4]={npc="Feralas: Una historia", npcObj=true}, [5]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [6]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [7]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus.", tag="Puedes comprar ya en la casa de subastas (o pedir a un alter que te lo envíe) 15 × Paño de seda (para Atrapado, más adelante en La Garganta de Fuego)."}, [8]={npc="Gracina Poderespíritu", tgt="Gracina Poderespíritu"}, [9]={npc="Tyrande Susurravientos", tgt="Tyrande Susurravientos"}, [10]={bindA="{a:1116}"}, [11]={desc="El Templo Sumergido no se puede aceptar hasta el nivel 46; si te falta poco, sube al 46 matando enemigos cerca del Bastión Plumaluna. El círculo de piedra, que viene más adelante, es su continuación."}, [12]={npc="Angelas Brisaluna", tgt="Angelas Brisaluna"}, [13]={to="Gadgetzan", toA="{a:976}"}, [14]={npc="Curgle Saltamanivela", tgt="Curgle Saltamanivela"}, [15]={npc="Curgle Saltamanivela", tgt="Curgle Saltamanivela"}, [16]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [17]={hint="Utiliza la pipeta de muestras abierta en la poza de agua de Vigía Penas de Arena. Cuando hayas recogido la muestra, llévale la pipeta de muestras cerrada al perito jefe Picoflojo, que está en Gadgetzan."}, [18]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [19]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}}},
    ["04-43"] = {steps={[1]={npc="Marin Tragonublo", tgt="Marin Tragonublo"}, [2]={npc="Andi Lynn", tgt="Andi Lynn", tag="Opcional"}, [3]={npc="Tran'rek", tgt="Tran'rek", tag="Mobs de nivel superior, Opcional"}, [4]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones"}, [5]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones"}, [6]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones"}, [7]={hint="Andi Lynn de Gadgetzan quiere que destruyas la Base Machacaduna y para conseguirlo tendrás que matar 10 toscos Machacadunas, 10 déspotas Machacadunas y a Gor'marok el Devastador.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [8]={hint="El jefe de seguridad Pasaquillas de Puerto Bonvapor en Tanaris quiere que recuperes un brazalete particularmente brillante, que se ha perdido cerca de la base de los ogros Machacadunas."}, [9]={hint="Llévale 5 trozos de insectos centipaar de La Guarida Ponzoñosa al alquimista Morterozugg de Gadgetzan."}, [10]={hint="Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz'rilo."}, [11]={hint="Consigue una glándula cargada de rocío y llévasela a Marin Tragonublo a Gadgetzan."}, [12]={hint="Tran'rek de Gadgetzan quiere que mates a 8 Cardizales nudosos y a 8 enraizadores Cardizales.", tag="Mobs de nivel superior, Opcional"}, [13]={npc="Localizador de emergencia OOX-17/TN", npcObj=true, tag="Acepta si cae, Opcional", desc="Haz clic derecho en el Localizador de emergencia OOX-17/TN en tu bolsa para empezar la misión."}, [14]={npc="Tooga", tgt="Tooga", tag="Opcional, Escolta, Hazla si la encuentras", desc="Acepta la misión solo si encuentras a Tooga y puedes escoltarlo a pie."}, [15]={hint="Muéstrale a Tooga el camino de vuelta con su esposa, Thorta.", tag="Opcional, Escolta", desc="Escolta a Tooga a pie hasta Torta, al suroeste de Puerto Bonvapor. Ten cuidado con las emboscadas."}, [16]={npc="Robot mensajero OOX-17/TN", tgt="Robot mensajero OOX-17/TN", tag="Opcional", desc="Misión de escolta: en grupo, espera a que todos vayan igual antes de aceptarla y desactiva la aceptación automática."}, [17]={npc="Robot mensajero OOX-17/TN", tgt="Robot mensajero OOX-17/TN", tag="Opcional"}, [18]={hint="Escolta a OOX-17/TN a Puerto Bonvapor y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", tag="Opcional"}, [19]={hint="Escolta a OOX-17/TN a Puerto Bonvapor y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", tag="Opcional", desc="Escolta fallida: abandona la misión en el registro y vuelve a aceptarla del robot."}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Thorta", tgt="Thorta", tag="Opcional, Escolta"}, [22]={text="La escolta de Tooga falló. Puedes seguir la ruta principal. Si quieres volver a intentarlo, abandona la misión y busca de nuevo a Tooga."}, [23]={npc="Jefe de seguridad Pasaquillas", tgt="Jefe de seguridad Pasaquillas"}, [24]={npc="Andi Lynn", tgt="Andi Lynn", tag="Opcional"}, [25]={npc="Marin Tragonublo", tgt="Marin Tragonublo"}, [26]={npc="Marin Tragonublo", tgt="Marin Tragonublo"}, [27]={npc="Roxio", tgt="Roxio"}, [28]={npc="Roxio", tgt="Roxio"}, [29]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg"}, [30]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [31]={npc="Tran'rek", tgt="Tran'rek"}, [32]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones"}, [33]={text="El equipo está al fondo de la cueva; baja por la rampa desde la entrada (55.00, 70.00 → 54.20, 72.90 → 56.30, 72.20)."}, [34]={hint="Descubre qué le ha ocurrido al perito adjunto Patagolpe y llévalo a él o su equipo de análisis ante el perito jefe Picoflojo, en Gadgetzan."}, [35]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [36]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [37]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg"}, [38]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg"}, [39]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [40]={npc="Perito jefe Picoflojo", tgt="Perito jefe Picoflojo"}, [41]={to="Theramore"}, [42]={to="Menethil Harbor", toA="{a:150}", from="Theramore", desc="El barco del muelle de Theramore va directo a Puerto de Menethil."}, [43]={to="Stormwind", desc="Si no aceptaste En búsqueda del templo, no hace falta ir a Ventormenta; vuela directo de Puerto de Menethil a Costasur."}, [44]={npc="Brohann Barriliga", tgt="Brohann Barriliga"}, [45]={npc="Brohann Barriliga", tgt="Brohann Barriliga"}}},
    ["04-44"] = {grind={[1]={mob="Lechubestia salvaje", note="El bosque del centro de las Tierras del Interior; hay muchos, los mismos enemigos que para las Plumas de lechúcico salvaje."}, [2]={mob="Acechador melenargenta", note="Las manadas de lobos de más al este; están dispersos y puedes matarlos de uno en uno."}}, steps={[1]={to="Southshore", toA="{a:271}", desc="Si no tienes Costasur, vuela a Puerto de Menethil, toma el barco a Auberdine en el muelle norte y baja en Costasur."}, [2]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional"}, [3]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Grupo recomendado", desc="Derrota a Loksey en la biblioteca, a Herod en la armería y a Mograine y Melenablanca en la catedral. Puedes completar las alas en visitas distintas."}, [4]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Requiere materiales"}, [5]={text="Toma el sendero de montaña hacia el noreste para entrar en Tierras del Interior."}, [6]={npc="Falstad Martillo Salvaje", tgt="Falstad Martillo Salvaje"}, [7]={nodeA="{a:348}", node="Aerie Peak"}, [8]={npc="Falstad Martillo Salvaje", tgt="Falstad Martillo Salvaje"}, [9]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [10]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [11]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [12]={npc="Fraggar Mantrueno", tgt="Fraggar Mantrueno"}, [13]={npc="Fraggar Mantrueno", tgt="Fraggar Mantrueno"}, [14]={text="Vincula tu piedra de hogar en la posada del Pico Nidal (13.80, 41.60).", bindA="{a:348}"}, [15]={npc="Rapsodio Machacacanillas", tgt="Rapsodio Machacacanillas", desc="De camino a las lechubestias; la continuación pide llevar licor, no la aceptes."}, [16]={hint="Recoge 15 plumas de lechúcico salvaje de las Tierras del Interior y llévaselas a Erelas Cieloámbar a la Aldea Rut'theran."}, [17]={hint="Mira en las jaulas de los poblados Secacorteza y vuelve a ver al maestro de grifos Garracha."}, [18]={desc="Si aún no eres nivel 47, ve al este y sube al 47 matando Lechubestias salvajes y Acechadores melenargenta; de paso, reúne Plumas de lechúcico salvaje."}, [19]={hint="Lleva 5 collares tribales trol a Fraggar Mantrueno a Pico Nidal."}, [20]={hint="Roxio de Gadgetzan quiere que consigas un tragano violeta y se lo lleves."}, [21]={hint="Mata 10 lodos verdes y 10 mocos de jade e informa a Fraggar Mantrueno en Pico Nidal."}, [22]={npc="Fraggar Mantrueno", tgt="Fraggar Mantrueno"}, [23]={npc="Fraggar Mantrueno", tgt="Fraggar Mantrueno"}, [24]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [25]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [26]={hint="Mira en el Altar de Zul y vuelve a ver al maestro de grifos Garracha."}, [27]={npc="Localizador de emergencia OOX-09/TI", npcObj=true, tag="Acepta si cae, Opcional", desc="Haz clic derecho en el Localizador de emergencia OOX-09/HL en tu bolsa para empezar la misión."}, [28]={npc="Robot mensajero OOX-09/TI", tgt="Robot mensajero OOX-09/TI", tag="Opcional"}, [29]={npc="Robot mensajero OOX-09/TI", tgt="Robot mensajero OOX-09/TI", tag="Opcional"}, [30]={hint="Escolta a OOX-09/TI a la costa pasando los Acantilados Dominantes, y preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", tag="Opcional"}, [31]={hint="Escolta a OOX-09/TI a la costa pasando los Acantilados Dominantes, y preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", tag="Opcional", desc="Escolta fallida: abandona la misión en el registro y vuelve a aceptarla del robot."}, [32]={hint="Utiliza la Superinstantánea FX para sacar una instantánea de Gammerita y luego vuelve a la Aldea Rut'theran con Daryn Brisela."}, [33]={hint="Whiskey el Delgado, en la Bahía del Botín, quiere que le lleves las botellas de oporto Pupellyverbos que perdió."}, [34]={bindA="{a:348}"}, [35]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [36]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [37]={to="Thelsamar", toA="{a:144}"}, [38]={text="Vincula tu piedra de hogar en la posada de Thelsamar (35.40, 48.40).", bindA="{a:144}"}, [39]={text="Sal de Loch Modan por el sur y toma aquí el sendero de montaña hacia las Tierras Inhóspitas."}, [40]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Grupo recomendado, Opcional", desc="Solo podrás aceptarla después de completar Ayuda elemental (Horado Rajacieno) y Tormenta, Tierra y Fuego."}, [41]={hint="Usa los tótems retorcidos para ponerle fin al ritual de los jabaespines.", tag="Grupo recomendado, Opcional", desc="Vuela del Refugio de la Zaga a Puerto de Menethil, toma el barco del muelle sur a Theramore, vuela a Thalanaar y camina hacia el este hasta Las Mil Agujas."}, [42]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Grupo recomendado, Opcional", desc="Vuela de Thalanaar a Theramore, toma el barco a Puerto de Menethil y vuela al Refugio de la Zaga."}, [43]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Opcional"}, [44]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento", tag="Opcional"}, [45]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento"}, [46]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento", desc="Necesita Colmillo Sangrapellejo ×30, Vidarraíz ×8 y Esencia del exilio ×1. Para Esencia del exilio, lleva 8 × de cada uno de Talismán ardiente, Talismán del trueno y Talismán blasonado al caldero que está al lado. Vidarraíz y los tres talismanes se pueden comprar en la casa de subastas."}, [47]={hint="Lleva los objetos sobre el papiro de Bath'rah a Bath'rah el Vigía del viento en Alterac."}, [48]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento"}, [49]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento"}, [50]={hint="Lleva el corazón de espirálico a Bath'rah el Vigía del viento."}, [51]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento"}, [52]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento", desc="Recompensa: un arma torbellino."}, [53]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento", desc="Recompensa: un arma torbellino."}}},
    ["04-45"] = {tips={{k="取捨", text="Haz juntas las cinco recolecciones. Para entregarlo todo necesitas en total 5 mandíbulas, 6 pulmones de jabalí, 6 pinzas de escorpión, 11 cerebros de lagarto y 14 mollejas de buitre. Cada entrega gasta materiales."}, {k="取捨", text="Si hay mucha competencia por los buitres o los basiliscos, deja sin terminar El bocado de basilisco o El vigor del buitre y sigue al norte hacia el Pantano de las Penas, como estaba previsto."}}, grind={[1]={mob="Capataz Hierro Negro", note="Los enanos Hierro Negro de los alrededores de La Caldera; de nivel adecuado."}, [2]={mob="Esclavista Hierro Negro", note="El lado sur de La Caldera; de nivel un poco más bajo y dispersos."}}, steps={[1]={npc="Sigrun Extracero", tgt="Sigrun Extracero", tag="Opcional", desc="Por el camino sueles conseguir Encantamientos Llamarada ígnea. Si no cae ninguno, abandónala."}, [2]={npc="Garek", tgt="Garek", tag="Grupo recomendado, Opcional", desc="Hay que matar a dos dracos negros élite de nivel 50; sáltala si no tienes grupo."}, [3]={hint="Usa el Signo de la Tierra para activar los pilares de amatista, de ópalo y de diamante y así obtener las piedras rúnicas.", tag="Hazla cuando te quede de paso, Grupo recomendado, Opcional"}, [4]={npc="Sello de la Tierra", npcObj=true, tag="Grupo recomendado, Opcional"}, [5]={npc="Sello de la Tierra", npcObj=true, tag="Grupo recomendado, Opcional"}, [6]={npc="Garek", tgt="Garek", tag="Grupo recomendado, Opcional"}, [7]={npc="Sigrun Extracero", tgt="Sigrun Extracero", tag="Opcional"}, [8]={hint="Mata al embajador Infernus en la Fortaleza de Angor y llévale la prueba de su muerte al consejero Belgrum en Forjaz.", tag="Grupo recomendado, Opcional"}, [9]={text="Desde Tierras Inhóspitas, ve al oeste y entra en La Garganta de Fuego por el sendero de montaña junto al campamento de la Horda de Kargath. Rodea Kargath.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [10]={npc="Letrina de madera", npcObj=true, desc="El Paño de seda se puede comprar en la casa de subastas. Necesitas 15."}, [11]={hint="Mata a 8 geólogos Hierro Negro y lleva 15 paños de seda a la persona encerrada en las letrinas de La Garganta de Fuego."}, [12]={text="Mata a Margol la Furiosa: da mucha experiencia.", tag="Opcional", desc="Cuerno de Margol inicia la cadena de misiones de la Llave de la Garganta de Fuego; si no quieres pelear, sáltatela: los pasos relacionados de más adelante se omitirán automáticamente y al final volarás de Forjaz de vuelta al Puesto del Torio."}, [13]={npc="Cuerno de Margol", npcObj=true, tag="Opcional, Grupo recomendado", desc="Haz clic derecho en Cuerno de Margol en tu bolsa para empezar la misión."}, [14]={npc="Letrina de madera", npcObj=true}, [15]={npc="Letrina de madera", npcObj=true, tag="Opcional", desc="La entrega requiere cuatro cosas: el libro de contabilidad junto a la letrina, patas de Araña Cristalderma ×20, el paquete atrasado del Marjal Revolcafango y la espada de Jarquia del Pantano de las Penas. No vayas a propósito por lo que te falte."}, [16]={hint="Coge el libro de contabilidad de Buenacero y busca los objetos de la lista antes de ir a verlo a Tanaris.", tag="Requiere materiales"}, [17]={npc="Dorius Cuidarrocas", tgt="Dorius Cuidarrocas", desc="Escolta a Dorius hacia el norte; tras la emboscada, recoge la Carta chamuscada allí mismo y entrégala."}, [18]={npc="Carta chamuscada", npcObj=true}, [19]={npc="Carta chamuscada", npcObj=true}, [20]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [21]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [22]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [23]={nodeA="{a:1446}", node="Thorium Point"}, [24]={npc="Se busca/Desaparecido/Objetos perdidos", npcObj=true, tag="Grupo recomendado, Opcional", desc="El Capataz Maltorius es una élite de nivel 50; sáltala si no tienes grupo."}, [25]={npc="Se busca/Desaparecido/Objetos perdidos", npcObj=true}, [26]={npc="Se busca/Desaparecido/Objetos perdidos", npcObj=true}, [27]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas"}, [28]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas", tag="Opcional"}, [29]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas"}, [30]={npc="Herrero maestro Burninate", tgt="Herrero maestro Burninate"}, [31]={bindA="{a:144}"}, [32]={npc="Montaraz Guijarro", tgt="Montaraz Guijarro", tag="Opcional"}, [33]={npc="Montaraz Guijarro", tgt="Montaraz Guijarro"}, [34]={to="Forjaz"}, [35]={npc="Veyric Horcatrueno", tgt="Veyric Horcatrueno", tag="Opcional"}, [37]={npc="Comisario Torio", tgt="Comisario Torio"}, [38]={npc="Comisario Torio", tgt="Comisario Torio"}, [39]={npc="Comisario Torio", tgt="Comisario Torio", tag="Opcional"}, [40]={npc="Comisario Torio", tgt="Comisario Torio"}, [41]={npc="Consejero Belgrum", tgt="Consejero Belgrum", tag="Grupo recomendado, Opcional"}, [42]={npc="Consejero Belgrum", tgt="Consejero Belgrum", tag="Opcional, Grupo recomendado"}, [43]={to="Thelsamar", toA="{a:144}", tag="Opcional", desc="Vuelve con Guijarro por la llave solo si tienes ¡Al fin!; si no la tienes, sáltatelo y vuela directamente de Forjaz de vuelta al Puesto del Torio."}, [44]={npc="Montaraz Guijarro", tgt="Montaraz Guijarro", tag="Opcional"}, [45]={text="Usa la llave de La Garganta de Fuego que acabas de conseguir para abrir la puerta junto a la montañera Pebblebitty y atraviesa el túnel hasta La Garganta de Fuego.", tag="Opcional"}, [46]={to="Thorium Point", toA="{a:1446}", desc="Si no tienes la llave de La Garganta de Fuego, vuela directamente de Forjaz de vuelta a La Garganta de Fuego. Si ya entraste por el túnel, sáltalo."}, [47]={hint="Lleva 4 corazones de llama y 4 globos de aceite gólem a Velarok Espada del Viento."}, [48]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [49]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [50]={hint="Encuentra la tobera y el catalejo y llévaselos al capataz Scrange a La Garganta de Fuego."}, [51]={hint="Mata a 15 Capataces y 15 esclavistas Hierro Negro y ve a ver al capataz Scrange a La Garganta de Fuego."}, [52]={hint="Hansel Manospesadas quiere que mates 20 gólems de guerra pesados."}, [53]={hint="Hansel Manospesadas quiere que mates 20 arañas de lava superiores en La Garganta de Fuego. Las encontrarás en las mesetas y los estanques de lava de La Garganta de Fuego.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [54]={text="Desde la entrada este con los mineros, gira a la derecha y sigue el corredor inferior junto a la lava hasta la caverna de los incendosaurios."}, [55]={hint="Hansel Manospesadas quiere que mates 20 incendosaurios."}, [56]={desc="Si aún te falta experiencia para el nivel 48, quédate en la mina y atrae de uno en uno a los incendosaurios normales por el pasillo que ya despejaste. Si no hay combates seguros, vuelve a salir por el mismo camino y termina el nivel con capataces o esclavistas Hierro Negro en los alrededores de la Caldera."}, [57]={hint="El traidor Hierro Negro llamado sobrestante Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego.", tag="Hazla cuando te quede de paso, Grupo recomendado, Opcional"}, [58]={text="Si vas por los planos desde el este, cruza el puente y gira a la izquierda en el gran salón. Los planos están en la mesa detrás del sobrestante, en la plataforma superior. Si hay élites vigilando, omite el paso y retómalo cuando esté despejado o vayas en grupo."}, [59]={hint="Busca los diseños secretos: flujo ígneo robados por el sobrestante Maltorius en La Fosa de la Escoria de La Caldera. Llévaselos al herrero maestro Burninate a La Garganta de Fuego.|n", desc="El sobrestante Maltorius o un centinela de élite puede vigilar la plataforma superior. Si vas solo, revisa si es seguro acercarte a la mesa. Solo la misión de recompensa exige matar al sobrestante."}, [60]={hint="Lleva 8 dagas bañadas en torio a Velarok Espada del Viento."}, [61]={npc="Arqueólogo moribundo", tgt="Arqueólogo moribundo"}, [62]={npc="Arqueólogo moribundo", tgt="Arqueólogo moribundo"}, [63]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [64]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento", tag="Opcional"}, [65]={hint="Encuentra el artefacto misterioso que protegen los idólatras de Martillo Crepuscular en el cuadrante noroeste de La Garganta de Fuego y tráelo al altar de Suntara en la Fosa de la Escoria.", tag="Hazla cuando te quede de paso"}, [66]={hint="Lleva un Símbolo de Ragnaros a Velarok Espada del Viento.", tag="Grupo recomendado, Opcional, Hazla cuando te quede de paso", desc="Solo los élites sueltan el Símbolo de Ragnaros."}, [67]={npc="Zamael Cardolún", tgt="Zamael Cardolún"}, [68]={npc="Zamael Cardolún", tgt="Zamael Cardolún"}, [69]={npc="Zamael Cardolún", tgt="Zamael Cardolún", tag="Grupo recomendado, Opcional"}, [70]={npc="Capitán de vigía Lolo Zancalarga", tgt="Capitán de vigía Lolo Zancalarga", tag="Grupo recomendado, Opcional"}, [71]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas"}, [72]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas", tag="Opcional"}, [73]={npc="Hansel Manospesadas", tgt="Hansel Manospesadas"}, [74]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [75]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [76]={npc="Herrero maestro Burninate", tgt="Herrero maestro Burninate"}, [77]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento", tag="Opcional"}, [78]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [79]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [80]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [81]={npc="Antorcha de reprensión", npcObj=true}, [82]={npc="Kalaran Espada del Viento", tgt="Kalaran Espada del Viento"}, [83]={npc="Escudero Maltrake", tgt="Escudero Maltrake"}, [84]={npc="Escudero Maltrake", tgt="Escudero Maltrake"}, [85]={hint="Entra en las 4 torres del centinela e incéndialas con la antorcha de reprensión.|n"}, [86]={npc="Altar de Suntara", npcObj=true}, [87]={npc="Arqueólogo moribundo", tgt="Arqueólogo moribundo", tag="Grupo recomendado, Opcional", desc="Lathoric el Negro y Obsidion son ambos élites de nivel 52; busca un grupo para hacerla."}, [88]={hint="Lleva la cabeza de Lathoric el Negro y el corazón de Obsidion a Torio a Forjaz.", tag="Grupo recomendado, Opcional"}, [89]={npc="Escudero Maltrake", tgt="Escudero Maltrake"}, [90]={npc="Tesoro oculto del Vuelo Negro", npcObj=true}, [91]={npc="Tesoro oculto del Vuelo Negro", npcObj=true, desc="Guarda la Muda de piel de Vuelo Negro y entrégala a Cyrus Therepentio en las Estepas Ardientes."}, [92]={tag="Opcional, Grupo recomendado", desc="Sube aquí hasta el 52 solo con grupo para las Profundidades de Roca Negra. En solitario, omítelo."}, [93]={to="Forjaz", desc="Si tu piedra de hogar está lista, úsala para volver a Thelsamar y vuela desde allí; si no, regresa a Puesto del Torio (37.90, 30.40) y busca al maestro de vuelo."}, [94]={npc="Comisario Torio", tgt="Comisario Torio", tag="Grupo recomendado, Opcional"}, [95]={npc="Alto expedicionario Magellas", tgt="Alto expedicionario Magellas"}, [96]={npc="Alto expedicionario Magellas", tgt="Alto expedicionario Magellas", desc="Solo se puede aceptar después de hacer Los discos de platino en Uldaman."}, [97]={npc="Karnik el Historiador", tgt="Karnik el Historiador"}, [98]={npc="Karnik el Historiador", tgt="Karnik el Historiador"}, [99]={text="Vincula tu piedra de hogar en la posada de Forjaz (18.60, 51.60).", bind="Forjaz"}, [100]={to="Nethergarde Keep", toA="{a:1438}", desc="Si no tienes el Castillo de Nethergarde, vuela a Villa Oscura, ve al este por el Paso de la Muerte hasta el Pantano de las Penas y luego al sur, a Las Tierras Devastadas, hasta el Castillo de Nethergarde."}, [101]={npc="Thadius Sombramacabra", tgt="Thadius Sombramacabra"}, [102]={npc="Thadius Sombramacabra", tgt="Thadius Sombramacabra", tag="Opcional, Grupo recomendado"}, [103]={npc="Mago sangriento Drazial", tgt="Mago sangriento Drazial"}, [104]={npc="Mago sangriento Drazial", tgt="Mago sangriento Drazial"}, [105]={npc="Mago sangriento Drazial", tgt="Mago sangriento Drazial"}, [106]={npc="Maga sangrienta Lynnore", tgt="Maga sangrienta Lynnore"}, [107]={npc="Maga sangrienta Lynnore", tgt="Maga sangrienta Lynnore"}, [108]={hint="Llévale 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok al mago sangriento Drazial."}, [109]={hint="Llévale 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco al mago sangriento Drazial.|n"}, [110]={hint="Llévale 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito al mago sangriento Drazial.|n"}, [111]={hint="Llévale 10 cerebros de basilisco y 2 mollejas de buitre a la maga sangrienta Lynnore.|n"}, [112]={hint="Llévale 10 mollejas de buitre y 2 papadas de hiena risitas a la maga sangrienta Lynnore.|n"}, [113]={npc="Mago sangriento Drazial", tgt="Mago sangriento Drazial"}, [114]={npc="Mago sangriento Drazial", tgt="Mago sangriento Drazial"}, [115]={npc="Mago sangriento Drazial", tgt="Mago sangriento Drazial"}, [116]={npc="Maga sangrienta Lynnore", tgt="Maga sangrienta Lynnore"}, [117]={npc="Maga sangrienta Lynnore", tgt="Maga sangrienta Lynnore"}, [118]={npc="El enigma de Cortello", npcObj=true, desc="Haz clic derecho en El enigma de Cortello en tu bolsa para empezar la misión. Requiere nivel 50 para aceptarla."}, [119]={text="Desde la Fortaleza de Nethergarde, ve al norte saliendo de las Tierras Devastadas hacia el Pantano de las Penas y sigue el camino al oeste hasta la parte occidental del pantano."}, [120]={npc="Un viejo pergamino", npcObj=true}, [121]={npc="Un viejo pergamino", npcObj=true}}},
    ["04-46"] = {grind={[1]={mob="Gorila Cieloleno", note="La isla pequeña donde está el Rey Mukla; enemigos normales, límpialos de paso después de matar al rey."}, [2]={mob="Acechador de Jaguero", note="El lado oeste de la misma isla."}}, steps={[1]={to="Booty Bay", toA="{a:35}", desc="El Pantano de las Penas no tiene punto de vuelo de la Alianza: ve al oeste por el Paso de la Muerte de vuelta a Villa Oscura y vuela desde allí."}, [2]={npc="Loquillo Pinchabujas", tgt="Loquillo Pinchabujas"}, [3]={npc="Loquillo Pinchabujas", tgt="Loquillo Pinchabujas"}, [4]={npc="Whiskey el Delgado", tgt="Whiskey el Delgado"}, [5]={npc="MacKinley Lobo de Mar", tgt="MacKinley Lobo de Mar"}, [6]={npc="Fin Fizqueta", tgt="Fin Fizqueta"}, [7]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Opcional"}, [8]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Opcional"}, [9]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Opcional"}, [10]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Opcional"}, [11]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus", tag="Opcional"}, [12]={npc="Nota doblada con cuidado", npcObj=true, desc="Haz clic derecho en Nota doblada con cuidado en tu bolsa para empezar la misión. Haz clic derecho ahora en la nota doblada que conseguiste antes para empezar la misión."}, [13]={npc="Princesa Poobah", tgt="Princesa Poobah"}, [14]={npc="Princesa Poobah", tgt="Princesa Poobah", tag="Grupo recomendado, Opcional"}, [15]={hint="Mata al rey Mukla y vuelve a por la princesa Poobah con la llave para liberarla.", tag="Grupo recomendado, Opcional"}, [16]={npc="Princesa Poobah", tgt="Princesa Poobah", tag="Grupo recomendado, Opcional"}, [17]={hint="Busca al médico brujo Unbagwa y haz que invoque a Mokk el Salvaje. Lleva el corazón de Mokk a Fin Fizqueta.", tag="Hazla cuando te quede de paso"}, [18]={npc="Fin Fizqueta", tgt="Fin Fizqueta"}, [19]={desc="Si aún no eres nivel 49, ve a la isla de la princesa Poobah y sube al 49 matando Gorilas Cieloleno y Acechadores Jaguero."}, [20]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [21]={hint="Recupera el círculo de piedra del taller de Marvon Buscarroblones, en Trinquete."}, [22]={to="Theramore"}, [23]={npc="Pergamino mohoso", npcObj=true}, [24]={npc="Pergamino mohoso", npcObj=true, tag="Opcional"}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", toA="{a:976}", desc="El pergamino está en la cueva de raptores al suroeste del Marjal Revolcafango. Camina primero hacia el este de vuelta a Theramore (67.48, 51.30) y luego vuela."}, [2]={npc="Krinkle Buenacero", tgt="Krinkle Buenacero", tag="Requiere materiales"}, [3]={npc="Roxio", tgt="Roxio"}, [4]={npc="Roxio", tgt="Roxio"}, [5]={npc="Marin Tragonublo", tgt="Marin Tragonublo"}, [6]={npc="Marin Tragonublo", tgt="Marin Tragonublo"}, [7]={npc="Marin Tragonublo", tgt="Marin Tragonublo"}, [8]={text="Desde Gadgetzan sigue el camino al norte hasta Desierto de Sal en Las Mil Agujas."}, [9]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [10]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [11]={npc="Encargado de foso gnomo", tgt="Encargado de foso gnomo"}, [12]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón", tag="Opcional"}, [13]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón", tag="Opcional, Grupo recomendado"}, [14]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones"}, [15]={npc="Pedestal de Uldum", npcObj=true}, [16]={npc="Vigía de piedra de Norgannon", tgt="Vigía de piedra de Norgannon"}, [17]={npc="Pedestal de Uldum", npcObj=true}, [18]={npc="Pedestal de Uldum", npcObj=true}, [19]={text="Ve al noroeste hasta el comienzo del sendero hacia el Cráter de Un'Goro."}}},
    ["04-48"] = {grind={[1]={mob="Azotador Sangrepétalo", note="Las plantas del lado este; mátalas en cuanto entres al cráter."}, [2]={mob="Gorila de Un'Goro", note="Afuera de la cueva de los gorilas, al noreste; los mismos enemigos que para las pieles de gorila."}, [3]={mob="Pterrordáctilo", note="La pared de roca al este del Refugio de Marshal."}, [4]={mob="Rondador de alquitrán", note="Las fosas de alquitrán al sur del campamento; de nivel algo alto, atráelos de uno en uno."}}, steps={[1]={text="Desde el camino de montaña al oeste de Tanaris, baja por la rampa hasta el Cráter de Un'Goro. Torwa Abrecaminos está justo junto a la entrada, al pie de la rampa.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [2]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos", tag="Mobs de nivel superior, Opcional"}, [3]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [4]={npc="Una balsa estropeada", npcObj=true, desc="Reúne 7 cristales de cada color (rojo, azul, verde y amarillo) y consigue «Un diario destrozado» de los raptores."}, [5]={npc="Un paquetito", npcObj=true}, [6]={npc="Un paquetito", npcObj=true}, [7]={hint="Encuentra la última presa muerta de Lar'korwi y roba un trozo de trillanodonte muerto, y después ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro."}, [8]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [9]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [10]={hint="Llévale 2 glándulas de feromonas de ravasaurio a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro."}, [11]={npc="Escama de cristal imbuido", npcObj=true, tag="Opcional"}, [12]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos", tag="Opcional, Requiere materiales"}, [13]={text="Usa la Escama de cristal imbuido que llevas en la bolsa para iniciar Contaminación microcristálica y entrega ambas misiones a Torwa Abrecaminos."}, [14]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [15]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos", tag="Opcional"}, [16]={hint="Utiliza el contenido de la faltriquera de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.", tag="Grupo recomendado, Opcional", desc="Esta es más difícil. Puedes dejarla para cuando vuelvas a Un'Goro."}, [17]={npc="Karna Tripirrem", tgt="Karna Tripirrem"}, [18]={npc="Linken", tgt="Linken"}, [19]={npc="Linken", tgt="Linken"}, [20]={nodeA="{a:541}", node="Marshal's Refuge"}, [21]={npc="Williden Marshal", tgt="Williden Marshal"}, [22]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [23]={npc="Chispik Minamal", tgt="Chispik Minamal"}, [24]={npc="J.D. Collie", tgt="J.D. Collie", desc="Recoge cristales de poder por el camino. Si llevas siete de cada color cuando veas por primera vez a J.D. Collie, entrégaselos allí mismo. Si te faltan, termina en la próxima visita."}, [25]={npc="Cuidado con los pterrordáctilos", npcObj=true}, [26]={npc="Muigin", tgt="Muigin"}, [27]={npc="Shizzle", tgt="Shizzle"}, [28]={hint="Lleva 8 huesos de dinosaurio a Chispik Minamal en el Cráter de Un'Goro."}, [29]={hint="Llévale 2 pelambres de gorila de Un'Goro, 2 pelambres de vapuleador de Un'Goro y 2 pelambres de tronador de Un'Goro a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro.", tag="Mobs de nivel superior, Opcional"}, [30]={desc="Si aún no eres nivel 50, quédate afuera de la cueva de los gorilas y sube al 50 matando Gorilas de Un'Goro."}, [31]={hint="Recoge 15 pétalos de sangre y ve a ver a Muigin."}, [32]={text="Recoge el cajón de víveres en el campamento oriental."}, [33]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [34]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [35]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [36]={text="Para la muestra hay que entrar en la colmena: ve al suroeste hasta la entrada de la cueva y adéntrate (50.40, 78.80 → 48.70, 85.20)."}, [37]={hint="Utiliza el vial de raspadura para recoger una Muestra de pared de colmena de uno de los criaderos Gorishi del Cráter de Un'Goro. Busca las cámaras con los huevos de larva colgantes."}, [38]={text="Termina las misiones de matar y recolectar que tengas."}, [39]={hint="Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro.", desc="El Cajón de comestibles está al este (de camino a la cueva de los gorilas y a Torwa) y el Equipo de investigación al suroeste (de camino de la colmena a los pterrordáctilos), así que toma uno de cada al pasar."}, [40]={hint="Recoge 8 escamas de diemetradón palmeadas y 8 escamas de pterrordáctilo palmeadas para Shizzle, en el Refugio de Marshal."}, [41]={hint="Mata a 10 pterrordáctilos y 15 pterrordáctilos demenciados, y habla con Spraggle Frock en Refugio de Marshal."}, [42]={npc="Shizzle", tgt="Shizzle"}, [43]={npc="Muigin", tgt="Muigin"}, [44]={npc="Muigin", tgt="Muigin"}, [45]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [46]={npc="Chispik Minamal", tgt="Chispik Minamal"}, [47]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [48]={npc="Williden Marshal", tgt="Williden Marshal"}, [49]={npc="Un diario destrozado", npcObj=true, tag="Opcional", desc="Haz clic derecho para aceptarla solo si consigues Un diario destrozado de los enemigos."}, [50]={npc="Williden Marshal", tgt="Williden Marshal", tag="Opcional"}, [51]={desc="Si aún no eres nivel 51, sube al 51 matando pterrordáctilos al este del campamento, o Rondadores de alquitrán en las fosas de alquitrán del sur."}, [52]={bind="Forjaz", desc="Si tu piedra de hogar está vinculada a Forjaz, úsala cuando esté disponible. Los sacerdotes pueden aceptar «Ayuda a Cenarion» de Sumo sacerdote Rohan y los magos, si quieren, «Pura magia» de Dink."}, [53]={text="Ve solo si quieres aceptar la introducción de Ventormenta: toma el Tranvía Subterráneo de Forjaz a Ventormenta.", tag="Opcional"}, [54]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Opcional", desc="Puedes saltarte la introducción de Ventormenta. Al llegar a Azshara, aun así tienes que buscar primero a Sanath Lim-yo para que te teletransporte al acantilado."}, [55]={text="Vuela de Ventormenta al Puerto de Menethil y retoma la ruta.", tag="Opcional"}, [56]={npc="Sumo sacerdote Rohan", tgt="Sumo sacerdote Rohan", tag="Puedes comprar ya en la casa de subastas (o pedir a un alter que te lo envíe) 1 × Icor de no-muerto (para El icor de los no-muertos, más adelante en Azshara).", desc="Entrégala a Ogtinc en Azshara."}, [57]={to="Menethil Harbor", toA="{a:150}", desc="Revisa el mapa de vuelos en el Refugio de Marshal. Vuela a Auberdine o a la Aldea Rut'theran si hay un vuelo disponible. Si no, vuelve a Tanaris por la rampa sureste y revisa los vuelos en Gadgetzan."}, [58]={to="Auberdine", from="Menethil Harbor", fromA="{a:150}", desc="Este barco hace escala en Costasur. Baja en Auberdine."}, [59]={to="Rut'theran Village", toA="{a:702}", desc="Cambia de transporte en Auberdine para ir a la Aldea Rut'theran. Si estás a bordo, baja cuando atraque el barco. Toma un vuelo disponible o el barco del muelle norte (33.3, 39.8)."}, [60]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [61]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [62]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [63]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus.", tag="Puedes comprar ya en la casa de subastas (o pedir a un alter que te lo envíe) 1 × Envoltura de mitril (para Buscando a Memo 01, más adelante en el Cráter de Un'Goro)."}, [64]={npc="Gracina Poderespíritu", tgt="Gracina Poderespíritu"}, [65]={npc="Gracina Poderespíritu", tgt="Gracina Poderespíritu"}, [66]={npc="Astarii Buscaestelar", tgt="Astarii Buscaestelar", tag="Grupo recomendado, Opcional"}, [67]={npc="Dorion", tgt="Dorion", desc="Acéptala en Darnassus (o Forjaz, Ventormenta) y entrégala a Ogtinc en Azshara."}, [68]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran."}, [69]={to="Astranaar", toA="{a:415}"}, [70]={text="Vincula tu piedra de hogar en la posada de Astranaar (37.00, 49.20).", bindA="{a:415}"}, [71]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Opcional", desc="Entrégala aquí solo si aceptaste la introducción."}, [72]={text="Habla con Sanath Lim-yo y pídele que te teletransporte al acantilado para buscar al archimago Xylem."}, [73]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [74]={hint="Llévale 10 puñados de polvo relumbrante al archimago Xylem."}, [75]={npc="Archimago Xylem", tgt="Archimago Xylem", desc="El polvo está al pie de la montaña; vuelve con Sanath Lim-yo del mismo modo para que te teletransporte arriba."}, [76]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [77]={hint="Reúne 6 corales encantados y llévaselos al archimago Xylem."}, [78]={npc="Archimago Xylem", tgt="Archimago Xylem"}, [79]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Grupo recomendado, Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [80]={hint="Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem.", tag="Grupo recomendado, Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [81]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Grupo recomendado, Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [82]={text="Ve a Frondavil por Astranaar. Si tu piedra de hogar está vinculada a Astranaar y lista, úsala para volver a la posada. Una vez abajo y a salvo, consulta el mapa de vuelo de Punta Talrendis. Si puedes, vuela a Astranaar. Si no, toma el camino principal hacia el oeste por el este de Vallefresno. Desde Astranaar, toma el camino principal hacia el norte hasta Frondavil."}, [83]={npc="Ogtinc", tgt="Ogtinc"}, [84]={npc="Ogtinc", tgt="Ogtinc"}, [85]={hint="Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [86]={npc="Ogtinc", tgt="Ogtinc"}, [87]={npc="Ogtinc", tgt="Ogtinc", desc="Icor de no-muerto ×1 se puede comprar en la casa de subastas."}, [88]={hint="Consigue un icor de no-muerto para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [89]={npc="Ogtinc", tgt="Ogtinc"}, [90]={npc="Ogtinc", tgt="Ogtinc", tag="Grupo recomendado, Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [91]={text="Si sigues en Azshara, vuelve a Punta Talrendis, vuela a Astranaar y ve al norte hacia Frondavil. Al salir del templo, ve directamente al Santuario Esmeralda en Frondavil."}, [92]={npc="Ogtinc", tgt="Ogtinc", desc="Acéptala en Darnassus (o Forjaz, Ventormenta) y entrégala a Ogtinc en Azshara."}, [93]={npc="Ogtinc", tgt="Ogtinc"}, [94]={hint="Llévale una cornamenta perfecta de trotador a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [95]={npc="Ogtinc", tgt="Ogtinc"}, [96]={npc="Ogtinc", tgt="Ogtinc"}, [97]={hint="Llévale 6 escamas de descarnador marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}, [98]={npc="Ogtinc", tgt="Ogtinc"}, [99]={npc="Ogtinc", tgt="Ogtinc", tag="Grupo recomendado, Opcional", desc="El draco verde está en el Templo de Atal'Hakkar."}, [100]={hint="Llévale el diente de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tag="Grupo recomendado, Opcional", desc="El draco verde está en el Templo de Atal'Hakkar."}, [101]={npc="Ogtinc", tgt="Ogtinc", tag="Grupo recomendado, Opcional", desc="El draco verde está en el Templo de Atal'Hakkar."}, [102]={text="Vuelve a Punta Talrendis y vuela a Astranaar; luego sigue el camino hacia el norte hasta entrar en Frondavil."}, [103]={text="Revisa tu ubicación. Si estás a bordo, baja cuando el barco atraque en tu destino. En Auberdine, cambia de transporte para ir a la Aldea Rut'theran. Una vez en tierra allí, entrega tus misiones."}, [104]={text="Para la misión de clase de los Reinos del Este, revisa los vuelos a Auberdine en el Refugio de Marshal. Si no hay ninguno disponible, regresa a Tanaris por la rampa sureste y revisa los de Gadgetzan. En Auberdine, toma el barco directo a Ventormenta."}, [105]={text="Toma el barco directo de Auberdine a Ventormenta. Si aún estás a bordo de otro barco, baja cuando atraque y espera en el muelle de Ventormenta (30.5, 40.9)."}, [106]={text="Regresa a Auberdine desde el Puerto de Ventormenta. Espera en el muelle de Auberdine (21.8, 56.9) y sigue tu ruta por Kalimdor al desembarcar."}, [107]={text="Revisa tu ubicación y tu registro de misiones. Deja un espacio libre antes de cruzar para recibir la misión de clase. Si estás a bordo, espera a llegar al puerto de destino."}, [108]={text="Baja cuando el barco atraque en el Puerto de Ventormenta y busca en la ciudad a quien ofrece la misión de clase. Si sigues en el mar, quédate a bordo."}, [109]={npc="Hermano Joshua", tgt="Hermano Joshua"}, [110]={npc="Dink", tgt="Dink", tag="Opcional"}, [111]={text="Consulta al maestro de vuelo de Forjaz si hay un vuelo al Puerto de Menethil. Si no está disponible, toma el Tranvía Subterráneo a Ventormenta y, desde el puerto, el barco a Auberdine."}}},
    ["04-49"] = {grind={[1]={mob="Guardián Jaedenar", note="Por la entrada de Jaedenar; enemigos normales."}, [2]={mob="Cultor Jaedenar", note="Mezclados con los Guardianes; lanzadores de hechizos."}}, steps={[1]={to="Talrendis Point", toA="{a:3137}"}, [2]={npc="Loh'atu", tgt="Loh'atu"}, [3]={npc="Loh'atu", tgt="Loh'atu"}, [4]={hint="Mata a 6 aparecidas Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara."}, [5]={hint="Mata 6 sátiros Haldarr, 2 tramposos Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno."}, [6]={npc="Loh'atu", tgt="Loh'atu"}, [7]={npc="Loh'atu", tgt="Loh'atu"}, [8]={to="Astranaar", toA="{a:415}"}, [9]={text="Desde Astranaar, sigue el camino al norte hasta Frondavil.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [10]={npc="Arathandris Cielargento", tgt="Arathandris Cielargento"}, [11]={npc="Grazle", tgt="Grazle"}, [12]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [13]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo", tag="Grupo recomendado, Opcional, Requiere materiales"}, [14]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [15]={npc="Taronn Plumarroja", tgt="Taronn Plumarroja"}, [16]={hint="Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda."}, [17]={npc="Grazle", tgt="Grazle"}, [18]={npc="Grazle", tgt="Grazle"}, [19]={hint="Mata a 11 jurapenas Fuego de Jade, 9 acechasombras Fuego de Jade, 9 pícaros Fuego de Jade y a Xavathras. Vuelve con Eridan Vientoazul a Frondavil cuando hayas completado la misión."}, [20]={hint="Entra en Jaedenar y mata a 4 canes Jaedenar, 4 guardianes Jaedenar, 6 adeptos Jaedenar y 6 cultores Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil."}, [21]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [22]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [23]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [24]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [25]={hint="Lleva la cantimplora vacía a la Poza de la Luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil."}, [26]={desc="Mata enemigos alrededor de 35, 59 en Jaedenar."}, [27]={hint="Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen agua vil corrupta, vuelve con Taronn Plumarroja a Frondavil."}, [28]={hint="Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho."}, [29]={npc="Flauta de Xavaric", npcObj=true, desc="Haz clic derecho en Flauta de Xavaric en tu bolsa para empezar la misión."}, [30]={hint="Lleva la Flauta de Xavaric y 5 muestras de lazo vil de fuego de jade a Eridan Vientoazul al Frondavil meridional."}, [31]={hint="Lleva 15 unidades de ámbar de sangre a Arathandris Cielargento a Frondavil."}, [32]={nodeA="{a:1998}", node="Talonbranch Glade"}, [33]={npc="Nafien", tgt="Nafien"}, [34]={npc="Nafien", tgt="Nafien"}, [35]={hint="Nafien quiere que mates a 6 vigías del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión Fauces de Madera."}, [36]={npc="Nafien", tgt="Nafien"}, [37]={text="Entra aquí en la cueva del Bastión Fauces de Madera y atraviésala para llegar a Cuna del Invierno."}, [38]={node="Claro de la Luna", desc="En la cueva de Bastión Fauces de Madera hay una bifurcación que lleva a Claro de la Luna; ve primero para abrir el punto de vuelo y luego vuelve a la cueva y sigue hacia Cuna del Invierno. Para la parte del Monte Hyjal más adelante, volarás a Claro de la Luna."}, [39]={npc="Salfa", tgt="Salfa"}, [40]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [41]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [42]={npc="Meggi Rocaliz", tgt="Meggi Rocaliz"}, [43]={npc="Jessica Rutagrana", tgt="Jessica Rutagrana"}, [44]={nodeA="{a:2255}", node="Everlook"}, [45]={npc="Niby el Todopoderoso", tgt="Niby el Todopoderoso"}, [46]={npc="Diblis", tgt="Diblis"}, [47]={npc="Diblis", tgt="Diblis", desc="Tela vil ×1 se puede comprar en la casa de subastas."}, [48]={hint="Lleva un retal de tela vil a Diblis a Frondavil."}, [49]={npc="Diblis", tgt="Diblis"}, [50]={npc="Diblis", tgt="Diblis"}, [51]={hint="Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil."}, [52]={npc="Diblis", tgt="Diblis"}, [53]={npc="Diblis", tgt="Diblis", tag="Grupo recomendado, Opcional"}, [54]={hint="Reúne un total de 6 plumas vudú en el Templo Sumergido.", tag="Grupo recomendado, Opcional"}, [55]={npc="Diblis", tgt="Diblis", tag="Grupo recomendado, Opcional"}, [56]={npc="Diblis", tgt="Diblis"}, [57]={hint="Diblis de Frondavil te ha pedido que le lleves 3 esencias viles impecables que provengan de 3 lugares distintos."}, [58]={npc="Diblis", tgt="Diblis"}, [59]={npc="Diblis", tgt="Diblis", desc="Kroshius está al norte de Frondavil. Necesitas grupo."}, [60]={hint="Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego vil cerca de ellos y espera el regreso de Kroshius. Cuando el infernal se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius.", desc="Kroshius está al norte de Frondavil. Necesitas grupo."}, [61]={npc="Niby el Todopoderoso", tgt="Niby el Todopoderoso", desc="Kroshius está al norte de Frondavil. Necesitas grupo."}}},
    ["05-d14"] = {name="El Templo de Atal'Hakkar", entrance="Pantano de las Penas 69.50, 52.50 (marca el exterior del templo)", steps={[1]={npc="Angelas Brisaluna", tgt="Angelas Brisaluna", tag="Requisito de mazmorra"}, [2]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones", tag="Requisito de mazmorra"}, [3]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones", tag="Requisito de mazmorra"}, [4]={hint="Recupera el círculo de piedra del taller de Marvon Buscarroblones, en Trinquete.", tag="Requisito de mazmorra"}, [5]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones", tag="Requisito de mazmorra"}, [6]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones", preText="El círculo de piedra"}, [7]={npc="Marvon Buscarroblones", tgt="Marvon Buscarroblones", preText="El círculo de piedra"}, [8]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [9]={hint="Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.", tag="Requisito de mazmorra", desc="Mata vociferadores del valle en la costa de la Isla del Terror, en Feralas. Usa la zarza de Yeh'kinya en cada cadáver y habla con el espíritu que aparezca hasta que el registro de misiones cuente tres."}, [10]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [11]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [12]={hint="Llévale la primera y segunda tablillas Mosh'aru a Yeh'kinya, que está en Tanaris.", tag="Requisito de mazmorra"}, [13]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [14]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [15]={hint="Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris.", tag="Requisito de mazmorra"}, [16]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Requisito de mazmorra"}, [17]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="El huevo antiguo"}, [18]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Requisito de mazmorra"}, [19]={hint="Llévale 10 puñados de polvo relumbrante al archimago Xylem.", tag="Requisito de mazmorra"}, [20]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Requisito de mazmorra"}, [21]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Requisito de mazmorra"}, [22]={hint="Reúne 6 corales encantados y llévaselos al archimago Xylem.", tag="Requisito de mazmorra"}, [23]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Requisito de mazmorra"}, [24]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [25]={npc="Hermano Joshua", tgt="Hermano Joshua", tag="Requisito de mazmorra"}, [26]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [27]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [28]={hint="Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tag="Requisito de mazmorra"}, [29]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [30]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [31]={hint="Consigue un icor de no-muerto para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tag="Requisito de mazmorra"}, [32]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [33]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [34]={npc="Dorion", tgt="Dorion", tag="Requisito de mazmorra"}, [35]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [36]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [37]={hint="Llévale una cornamenta perfecta de trotador a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tag="Requisito de mazmorra"}, [38]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [39]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [40]={hint="Llévale 6 escamas de descarnador marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tag="Requisito de mazmorra"}, [41]={npc="Ogtinc", tgt="Ogtinc", tag="Requisito de mazmorra"}, [42]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="El draco verde está en el Templo de Atal'Hakkar."}, [43]={text="Entrada: El Templo de Atal'Hakkar"}, [44]={hint="Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.", desc="Ubicación: Toma la ruta plana de la derecha hacia abajo. Encuentra el Altar de Hakkar en el anillo.", spot="Toma la ruta plana de la derecha hacia abajo. Encuentra el Altar de Hakkar en el anillo."}, [45]={npc="Altar de Hakkar", npcObj=true, spot="Altar de Hakkar en el corredor circular inferior"}, [46]={hint="Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.", desc="Un orden equivocado activa una trampa. Ubicación: Haz clic en las seis estatuas por orden en el corredor circular inferior y luego ve al centro a matar al jefe. Orden: Sur → norte → suroeste → sureste → noroeste → noreste.", spot="Activa las seis estatuas del anillo inferior en orden y luego mata al jefe del centro."}, [47]={npc="Ídolo de Hakkar", npcObj=true, spot="Centro del nivel inferior: la estatua Hakkari"}, [48]={hint="Llévale el huevo de Hakkar relleno a Yeh'kinya, que está en Tanaris.", desc="Entra primero con todo el grupo a la sala y luego inicia el evento. Ve por el pasadizo oeste a la sala de Hakkar. Ubicación: Desde el Foso del Sacrificio ve por el corredor oeste a la sala de Hakkar, reúne al grupo y usa el huevo. Orden: El corredor oeste lleva a Hakkar y el este, a Jammal'an.", spot="Toma el pasillo oeste desde el Pozo de Sacrificio hasta la sala de Hakkar; reúne al grupo antes de usar el huevo."}, [49]={hint="Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem.", tag="Opcional"}, [50]={hint="Mata a Morphaz en El Templo Sumergido de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas.", tag="Opcional"}, [51]={hint="Llévale el diente de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tag="Opcional"}, [52]={npc="Esencia de Eranikus", npcObj=true, tag="Opcional, Grupo recomendado", desc="Tras derrotar al jefe final, haz clic derecho en la esencia que recogiste para iniciar la misión."}, [53]={hint="Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido.", tag="Opcional, Grupo recomendado", spot="Coloca la esencia en la fuente de esencia junto al jefe final."}, [54]={npc="Fuente de esencia", npcObj=true, tag="Opcional, Grupo recomendado", spot="Coloca la esencia en la fuente de esencia junto al jefe final."}, [55]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [56]={npc="Archimago Xylem", tgt="Archimago Xylem", tag="Opcional", desc="Morphaz está en el Templo de Atal'Hakkar."}, [57]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="El draco verde está en el Templo de Atal'Hakkar."}, [58]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo", tag="Opcional, Requiere materiales"}}},
    ["04-50"] = {steps={[1]={to="Feathermoon Stronghold", toA="{a:1116}"}, [2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}, [4]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}, [5]={npc="Gregan Tirabirras", tgt="Gregan Tirabirras"}, [6]={hint="Busca a Gregan Tirabirras en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno.", desc="Gregan te da un cebo: úsalo para alejar a Miblon, toma la Raíz del mal y regresa para cambiarla por el Elixir de Videre."}, [7]={npc="Muerdepiedras", tgt="Muerdepiedras"}, [8]={hint="Energiza el báculo de Troyas y encuentra el Monolito de Equinex.", desc="Más adelante puedes saltar hacia arriba para atajar."}, [9]={npc="Monolito de Equinex", npcObj=true, desc="Usa el bastón de tu bolsa."}, [10]={npc="Monolito de Equinex", npcObj=true}, [11]={npc="Shay Correhoja", tgt="Shay Correhoja"}, [12]={npc="Shay Correhoja", tgt="Shay Correhoja", tag="Escolta"}, [13]={hint="Coge la campana de Shay del cofre."}, [14]={npc="Muerdepiedras", tgt="Muerdepiedras"}, [15]={hint="Lleva 10 pellejos de yeti Cicatriz de Rabia a Pratt McGrubben al Bastión Plumaluna en Feralas."}, [16]={npc="Pellejo de yeti prístino", npcObj=true, tag="Opcional", desc="Si te cae un Pellejo de yeti prístino al matar yetis, haz clic derecho en él."}, [17]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [18]={npc="Pratt McGrubben", tgt="Pratt McGrubben", tag="Opcional"}, [19]={npc="Troyas Brisaluna", tgt="Troyas Brisaluna"}}},
    ["04-51"] = {grind={[1]={mob="Abrecaminos Nevada", note="El campamento de furbolgs Nevada al norte de Donova; los mismos enemigos que para la misión de los furbolgs."}, [2]={mob="Totémico Nevada", note="El mismo campamento; lanzadores de hechizos."}}, steps={[1]={bindA="{a:415}", desc="Si tu piedra de hogar está en reutilización, vuela de Bastión Plumaluna a Astranaar (con escala en Auberdine) y luego camina al norte hasta Frondavil."}, [2]={npc="Arathandris Cielargento", tgt="Arathandris Cielargento"}, [3]={npc="Arathandris Cielargento", tgt="Arathandris Cielargento"}, [4]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [5]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo", tag="Grupo recomendado, Opcional, Requiere materiales"}, [6]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [7]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [8]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [9]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [10]={npc="Taronn Plumarroja", tgt="Taronn Plumarroja"}, [11]={hint="Botín de: Moco maldito, Moco corrupto, Moco malvado", desc="Solo caen si llevas la Antorcha Cenarion en las bolsas; las Lechuzas Cortezaférrea están al oeste del santuario y los cienos, en las pozas del noroeste."}, [12]={npc="Arathandris Cielargento", tgt="Arathandris Cielargento"}, [13]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado", desc="Vuelve a Astranaar, vuela al Claro Ramaespolón y sigue al norte por el Bastión Fauces de Madera hasta Cuna del Invierno."}, [14]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado", desc="Bébete el Elixir de Videre en el cementerio a las afueras de Gadgetzan y busca a Gaeriyan como espíritu."}, [15]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [16]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [17]={desc="Mata furbolgs alrededor de 32, 36 en el campamento Nevada."}, [18]={npc="Gregor Pedragris", tgt="Gregor Pedragris"}, [19]={npc="Gregor Pedragris", tgt="Gregor Pedragris"}, [20]={to="Ratchet", toA="{a:392}", desc="Harás escala en Punta Talrendis."}, [21]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [22]={npc="Islen Vidente del Agua", tgt="Islen Vidente del Agua"}, [23]={npc="Islen Vidente del Agua", tgt="Islen Vidente del Agua"}, [24]={to="Gadgetzan", toA="{a:976}"}, [25]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg"}, [26]={text="Tras beber el Elixir de Videre, sigue muerto y busca al PNJ de la misión en forma de espíritu."}, [27]={npc="Gaeriyan", tgt="Gaeriyan"}, [28]={npc="Gaeriyan", tgt="Gaeriyan"}, [29]={text="Vuelve a tu cadáver y resucita."}, [30]={npc="Una lápida llamativa", npcObj=true}, [31]={npc="Una lápida llamativa", npcObj=true}, [32]={npc="Tran'rek", tgt="Tran'rek"}, [33]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg", tag="Opcional"}}},
    ["04-52"] = {name="Cráter de Un'Goro", steps={[1]={to="Marshal's Refuge", toA="{a:541}"}, [2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Collie", tgt="J.D. Collie"}, [5]={npc="J.D. Collie", tgt="J.D. Collie"}, [6]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [7]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Opcional, If offered", desc="Misión de entrega de un libro: acéptala si el PNJ la ofrece y llévalo a la Cima de la Eternidad, en el Monte Hyjal. Si no ves la misión, sáltala por ahora."}, [8]={hint="Reúne 12 muestras de alquitrán muy pegajoso para Tran'rek de Gadgetzan."}, [9]={npc="Krakle", tgt="Krakle"}, [10]={hint="Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete."}, [11]={hint="Krakle, en el Cráter de Un'Goro, quiere que encuentres la zona más caliente de la Cresta del Penacho en Llamas.", desc="Sube por el sendero de la Cresta del Penacho en Llamas para medir la temperatura. Recoge cenizas por el camino si tienes esa misión. Tras medir la temperatura, sigue el sendero hasta Ringo. Al comenzar la escolta, ve directamente al norte hasta el Refugio de Marshal."}, [12]={npc="Ringo", tgt="Ringo", desc="Misión de escolta: en grupo, espera a que todos vayan igual antes de aceptarla y desactiva la aceptación automática."}, [13]={npc="Ringo", tgt="Ringo"}, [14]={hint="Lleva a Ringo con Spraggle Frock en el Refugio de Marshal.", tag="Escolta", desc="Lleva a Ringo de vuelta al Refugio de Marshal. Se desmayará por el camino; cuando lo haga, usa la Cantimplora de Spraggle con él."}, [15]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [16]={npc="Memo 01", tgt="Memo 01"}, [17]={npc="Memo 01", tgt="Memo 01"}, [18]={hint="Encuentra una envoltura de mitril y reúnete de nuevo con Memo 01 en el Cráter de Un'Goro.", desc="Compra la carcasa de mitril antes en la casa de subastas, o pídesela a un ingeniero."}, [19]={npc="Memo 01", tgt="Memo 01"}, [20]={hint="Llévale la pelambre de U'cha a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro."}, [21]={npc="Memo 01", tgt="Memo 01"}, [22]={hint="Lleva a Memo 01 de vuelta con Karna Tripirrem al Cráter de Un'Goro.", tag="Escolta", desc="Escolta a Memo 01 de vuelta con Karna Tripirrem; los monstruos del camino lo atacarán, así que protégelo."}, [23]={npc="Karna Tripirrem", tgt="Karna Tripirrem"}, [24]={hint="Recoge 7 cristales de poder de cada color: rojo, azul, amarillo y verde. Llévaselos a J.D. Collie en el Refugio de Marshal.", desc="Los cristales de cuatro colores están esparcidos por el suelo en todo el cráter; completa aquí los que te hayan faltado antes."}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="J.D. Collie", tgt="J.D. Collie"}, [28]={npc="J.D. Collie", tgt="J.D. Collie"}, [29]={hint="Descubre la localización de la Torre de Cristal del Norte en el Cráter de Un'Goro."}, [30]={hint="Descubre la localización de la Torre de Cristal del Este en el Cráter de Un'Goro."}, [31]={hint="Llévale una glándula secretora de olor Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.", tag="Opcional", desc="Busca avispas u obreros Gorishi junto a la colmena del sur para conseguir la glándula. Recoge tierra de los montones que encuentres hasta tener cinco. En solitario puedes atraer insectos aislados sin adentrarte en busca de la reina."}, [32]={hint="Llévale una glándula secretora de olor Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.", tag="Opcional", desc="Busca avispas u obreros Gorishi junto a la colmena del sur para conseguir la glándula. Recoge tierra de los montones que encuentres hasta tener cinco. En solitario puedes atraer insectos aislados sin adentrarte en busca de la reina."}, [33]={hint="Descubre la localización de la Torre de Cristal del Oeste."}, [34]={npc="Krakle", tgt="Krakle"}, [35]={npc="Krakle", tgt="Krakle"}, [36]={npc="J.D. Collie", tgt="J.D. Collie"}, [37]={npc="J.D. Collie", tgt="J.D. Collie"}, [38]={npc="J.D. Collie", tgt="J.D. Collie"}, [39]={npc="J.D. Collie", tgt="J.D. Collie"}, [40]={npc="J.D. Collie", tgt="J.D. Collie"}, [41]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [42]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [43]={hint="Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro."}, [44]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [45]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [46]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos"}, [47]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos", tag="Grupo recomendado, Opcional"}, [48]={hint="Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos.", tag="Grupo recomendado, Opcional"}, [49]={npc="Torwa Abrecaminos", tgt="Torwa Abrecaminos", tag="Grupo recomendado, Opcional"}, [50]={text="Si sigues en el norte y no tienes nada pendiente con Torwa, consulta el mapa de vuelo en el Refugio de Marshal y vuela a Gadgetzan si aparece como destino. Si vas a entregar la piel de U'cha o a hacer las misiones de druida de Torwa, visítalo primero en el sureste. Desde Torwa, o si no puedes volar, sube por la rampa del sureste hasta Tanaris y ve al noreste hacia Gadgetzan."}, [51]={npc="Tran'rek", tgt="Tran'rek"}, [52]={npc="Alquimista Morterozugg", tgt="Alquimista Morterozugg", tag="Opcional"}, [53]={to="Ratchet", toA="{a:392}", desc="Harás escala en Theramore."}, [54]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [55]={bindA="{a:415}"}, [56]={to="Auberdine"}, [57]={text="Vincula tu piedra de hogar con Tabernera Shaussiy en la posada de Auberdine (37.04, 44.13)."}, [58]={to="Rut'theran Village", toA="{a:702}"}, [59]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [60]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus."}, [61]={hint="Viaja a Darnassus y utiliza el vial de Eridan para recoger agua bendita del Templo de la Luna. Vuelve a Eridan con el vial lleno."}, [62]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran."}, [63]={to="Astranaar", toA="{a:415}"}, [64]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo"}, [65]={npc="Greta Pezuñamusgo", tgt="Greta Pezuñamusgo", tag="Opcional, If offered", desc="Misión de entrega de una carta: acéptala si el PNJ la ofrece y llévala al Monte Hyjal para entregarla al ermitaño Ketharas. Si no ves la misión, sáltala por ahora."}, [66]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [67]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [68]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [69]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [70]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul"}, [71]={hint="Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [72]={npc="Eridan Vientoazul", tgt="Eridan Vientoazul", tag="Opcional"}, [73]={desc="Si está en reutilización, camina de vuelta a Astranaar y vuela a Auberdine."}, [74]={to="Menethil Harbor", toA="{a:150}", from="Auberdine", desc="En Auberdine, toma el barco a Puerto de Menethil y baja en la siguiente parada."}, [75]={to="Forjaz"}, [76]={npc="Karnik el Historiador", tgt="Karnik el Historiador"}, [77]={npc="Karnik el Historiador", tgt="Karnik el Historiador"}, [78]={npc="Alto expedicionario Magellas", tgt="Alto expedicionario Magellas"}, [79]={npc="Alto expedicionario Magellas", tgt="Alto expedicionario Magellas"}, [80]={npc="Historiadora Real Archesonus", tgt="Historiadora Real Archesonus"}, [81]={npc="Historiadora Real Archesonus", tgt="Historiadora Real Archesonus"}, [82]={npc="Historiadora Real Archesonus", tgt="Historiadora Real Archesonus"}}},
    ["05-d11"] = {name="Profundidades de Roca Negra", entrance="La Garganta de Fuego 34.80, 85.30", pickup="En la ruta principal, forma un grupo en Forjaz al terminar tu segunda visita a Un'Goro. La siguiente parada son las Estepas Ardientes. Si ya encuentras grupo en la Garganta de Fuego, entra en la Montaña Roca Negra por el extremo sur de la garganta.", pickupS={{"En la ruta principal, forma un grupo en Forjaz al terminar tu segunda visita a Un'Goro"}, {"La siguiente parada son las Estepas Ardientes"}, {"Si ya encuentras grupo en la Garganta de Fuego, entra en la Montaña Roca Negra por el extremo sur de la garganta"}}, tips={{k="動線", text="Desde Forjaz, vuela al Puesto del Torio si tienes el vuelo y entra en la Montaña Roca Negra por el extremo sur de la Garganta de Fuego. Sin vuelo, sal de Dun Morogh hacia el este hasta Loch Modan. Ve al sur hacia las Tierras Inhóspitas y luego al oeste, rodeando Kargath, para entrar en la Garganta de Fuego. → Si encuentras grupo en Cuna del Invierno, vuela a Auberdine. Sin vuelo, vuelve por el Bastión Fauces de Madera a Frondavil y cruza Vallefresno hasta Auberdine, en Costa Oscura. Toma el barco a Ventormenta y vuela al Puesto del Torio. Si no tienes los vuelos del este, sal de Ventormenta por el Bosque de Elwynn hacia las Montañas Crestagrana. Desde Villa del Lago, sigue el camino al norte hasta las Estepas Ardientes y ve hacia el oeste a la Montaña Roca Negra. → Para continuar por las Estepas Ardientes, sal de la Montaña Roca Negra por la puerta sur y sigue el camino hacia el este hasta la Vigilia de Morgan. → Para regresar al Bastión Plumaluna, usa la piedra de hogar si está lista y vinculada a Astranaar. De lo contrario, ve desde las Estepas Ardientes por las Montañas Crestagrana y el Bosque de Elwynn hasta el puerto de Ventormenta. Toma el barco a Auberdine y vuela al Bastión Plumaluna. Sin vuelo, ve desde Vallefresno por la Sierra Espolón y Desolace hasta Feralas, y toma el barco a la isla desde el muelle de la costa oeste."}}, steps={[1]={npc="Franclorn Forjador", tgt="Franclorn Forjador", desc="Habla con Franclorn como fantasma dentro de la Montaña Roca Negra. Acepta y entrega la primera parte y acepta la segunda antes de resucitar. Esta página indica cómo llegar a la montaña."}, [2]={npc="Franclorn Forjador", tgt="Franclorn Forjador"}, [3]={npc="Franclorn Forjador", tgt="Franclorn Forjador"}, [4]={text="Entrada: Profundidades de Roca Negra"}, [5]={hint="Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador."}, [6]={npc="Monumento a Franclorn Forjador", npcObj=true, desc="Entrega aquí El legado de los Hierro Negro. Sal por la puerta sur de la Montaña Roca Negra para continuar por las Estepas Ardientes. Para volver a Kalimdor, sigue las indicaciones de esta página para el barco o la piedra de hogar."}}},
    ["04-54"] = {steps={[1]={text="Si ya abriste Vigilia de Morgan, vuela directo desde Forjaz. Si no, vuela a Villa del Lago y sigue el camino al norte hasta Las Estepas Ardientes; Vigilia de Morgan está justo en la entrada.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [2]={nodeA="{a:2418}", node="Morgan's Vigil"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Rivacuerno", tgt="Helendis Rivacuerno", tag="Grupo recomendado, Opcional"}, [6]={npc="Tinkee Vaporio", tgt="Tinkee Vaporio"}, [7]={npc="Maxwort Suprandor", tgt="Maxwort Suprandor"}, [8]={hint="Ve a las Ruinas de Thaurissan, en Las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa a la historiadora real Archesonus."}, [9]={hint="Lleva la trascripción de tablilla a Maxwort Suprandor en las Estepas Ardientes."}, [10]={hint="Mata a 15 ogros magos Pirontraña, 7 ogros Pirontraña y 7 brutos ogros Pirontraña, y vuelve con Oralius cuando hayas terminado."}, [11]={hint="Llévale 8 esencias de cría y el Draco-Incarcinatrix 900 a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes."}, [12]={hint="Mata 15 estirpes negras, 10 dragauros negros, 4 vermintes negros y 1 draco negro.", tag="Grupo recomendado, Opcional", desc="Los dragonantes negros y los dracos son élites de nivel 51-53."}, [13]={npc="Cyrus Therepentio", tgt="Cyrus Therepentio"}, [14]={npc="Cyrus Therepentio", tgt="Cyrus Therepentio"}, [15]={npc="Tinkee Vaporio", tgt="Tinkee Vaporio"}, [16]={npc="Maxwort Suprandor", tgt="Maxwort Suprandor"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius"}, [19]={npc="Helendis Rivacuerno", tgt="Helendis Rivacuerno", tag="Grupo recomendado, Opcional"}, [20]={npc="Helendis Rivacuerno", tgt="Helendis Rivacuerno"}, [21]={hint="Recoge la cabeza cortada de Gor'tesh."}, [22]={hint="Reúne 50 medallones Roca Negra."}, [23]={npc="Oralius", tgt="Oralius"}, [24]={npc="Oralius", tgt="Oralius"}, [25]={to="Lakeshire", toA="{a:69}", desc="Si no vas a hacer Los verdaderos maestros, vuela directo a Ventormenta y sáltate los dos pasos siguientes."}, [26]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [27]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [28]={to="Stormwind"}, [29]={npc="Wu Shen", tgt="Wu Shen", tag="Opcional"}, [31]={npc="Lord Grisillo Quiebrasombras", tgt="Lord Grisillo Quiebrasombras", desc="Entrégala en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}, [33]={npc="Alto señor Bolvar Fordragón", tgt="Alto señor Bolvar Fordragón"}, [34]={npc="Alto señor Bolvar Fordragón", tgt="Alto señor Bolvar Fordragón"}, [35]={npc="Alto señor Bolvar Fordragón", tgt="Alto señor Bolvar Fordragón"}, [36]={npc="Alto señor Bolvar Fordragón", tgt="Alto señor Bolvar Fordragón"}, [37]={npc="Pregonero Buenhombre", tgt="Pregonero Buenhombre"}, [38]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [39]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [40]={hint="Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al héroe caído de la Horda.", tag="Opcional"}, [41]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [42]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [43]={hint="Acaba con los Sombra Jurada en Las Tierras Devastadas y regresa junto al héroe caído de la Horda.", tag="Opcional"}, [44]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Opcional"}, [45]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Grupo recomendado, Opcional"}, [46]={hint="Llévale las plumas vudú de los trols del Templo Sumergido al héroe caído de la Horda.", tag="Grupo recomendado, Opcional"}, [47]={npc="Héroe caído de la Horda", tgt="Héroe caído de la Horda", tag="Grupo recomendado, Opcional"}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", toA="{a:348}", desc="Si ya abriste el Campamento del Orvallo, vuela directo y sáltate el siguiente paso. Si el Pico Nidal no está en tu mapa de vuelos, vuela a Costasur y corre al este hasta el Pico Nidal por el mismo camino que en la visita a las Tierras del Interior."}, [2]={text="Desde el Pico Nidal, toma el camino de montaña al norte hasta el extremo sureste de las Tierras de la Peste del Oeste (65.30, 86.80) y sigue la carretera al oeste hasta el Campamento del Orvallo.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [3]={nodeA="{a:3197}", node="Chillwind Camp"}, [4]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [5]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [6]={hint="Recoge 20 piedras de la Plaga del esbirro y entrégaselas al sumo sacerdote Thel'danis en las Tierras de la Peste del Oeste."}, [7]={npc="Sumo sacerdote Thel'danis", tgt="Sumo sacerdote Thel'danis"}, [8]={npc="Sumo sacerdote Thel'danis", tgt="Sumo sacerdote Thel'danis"}, [9]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [10]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor", tag="Grupo recomendado, Opcional", desc="Entrégala para conseguir la Piedra de poderío."}, [11]={hint="Llévale las plumas vudú a Ashlam Puñovalor.", tag="Grupo recomendado, Opcional", desc="Entrégala para conseguir la Piedra de poderío."}, [12]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor", tag="Grupo recomendado, Opcional", desc="Entrégala para conseguir la Piedra de poderío."}, [13]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [14]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [15]={npc="Oficial Argenta Purocorazón", tgt="Oficial Argenta Purocorazón"}, [16]={npc="Oficial Argenta Purocorazón", tgt="Oficial Argenta Purocorazón"}, [17]={npc="Oficial Argenta Purocorazón", tgt="Oficial Argenta Purocorazón"}, [18]={npc="Oficial Argenta Purocorazón", tgt="Oficial Argenta Purocorazón", desc="Misión de entrega de una carta; entrégala cerca de la entrada del Monte Hyjal."}, [19]={npc="Flint Sombramás", tgt="Flint Sombramás", tag="Opcional"}, [20]={npc="Flint Sombramás", tgt="Flint Sombramás", tag="Opcional"}, [21]={hint="Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas."}, [22]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [23]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [24]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [25]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [26]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [27]={hint="Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla."}, [28]={hint="Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [29]={npc="Caldera de la Plaga", npcObj=true}, [30]={npc="Caldera de la Plaga", npcObj=true}, [31]={npc="Janice Piedra Mácula", tgt="Janice Piedra Mácula"}, [32]={npc="Paquete de Janice", npcObj=true}, [33]={npc="Paquete de Janice", npcObj=true}, [34]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [35]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [36]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [37]={hint="Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [38]={npc="Caldera de la Plaga", npcObj=true}, [39]={npc="Caldera de la Plaga", npcObj=true}, [40]={npc="Diario de la señora Dalson", npcObj=true, desc="El diario que está en el granero junto al caldero."}, [41]={hint="Completa los objetivos de la misión."}, [42]={npc="Diario de la señora Dalson", npcObj=true}, [43]={npc="Letrina", npcObj=true, desc="Lee el diario y luego busca un Esqueleto errante. Abre la letrina y aparecerá el granjero."}, [44]={hint="Botín de: Esqueleto deambulante"}, [45]={npc="Letrina", npcObj=true}, [46]={npc="Armario cerrado", npcObj=true, desc="Despeja alrededor de la letrina. Abre el cofre y entrega de inmediato."}, [47]={hint="Botín de: Granjero Dalson"}, [48]={npc="Armario cerrado", npcObj=true}, [49]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [50]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={hint="Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [53]={npc="Caldera de la Plaga", npcObj=true}, [54]={npc="Caldera de la Plaga", npcObj=true}, [55]={npc="Mulgris Río Hondo", tgt="Mulgris Río Hondo"}, [56]={hint="Destruye 8 lobos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste."}, [57]={npc="Mulgris Río Hondo", tgt="Mulgris Río Hondo"}, [58]={npc="Mulgris Río Hondo", tgt="Mulgris Río Hondo"}, [59]={hint="Destruye 8 pardos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste."}, [60]={npc="Mulgris Río Hondo", tgt="Mulgris Río Hondo"}, [61]={npc="Mulgris Río Hondo", tgt="Mulgris Río Hondo"}, [62]={text="Ve al sureste y toma aquí el sendero de montaña hacia Tierras del Interior."}, [63]={text="Vincula tu piedra de hogar en la posada de Pico Nidal (13.80, 41.60).", bindA="{a:348}"}, [64]={npc="El tesoro de Cortello", npcObj=true, tag="Opcional", desc="El tesoro está en la costa este de las Tierras del Interior y hay que cruzar todo el mapa; después de entregarla, vuelve con la piedra de hogar."}, [65]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="Desde el Pico Nidal, toma el camino de montaña al norte hasta las Tierras de la Peste del Oeste y luego ve al este cruzando el río Thondroril hasta las Tierras de la Peste del Este. Tirión Vadín está en la cabaña junto a la entrada."}, [2]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [3]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [4]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [5]={hint="Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín."}, [6]={hint="Mata 30 murcipestes y vuelve con Tirion Vadín."}, [7]={hint="Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero."}, [8]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [9]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [10]={hint="Encuentra la muñeca de Pamela.", desc="En las casas en ruinas de Villa Darrow, recoge la cabeza, el lado izquierdo y el lado derecho, y combínalos con clic derecho."}, [11]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [12]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [13]={npc="Pamela Rutagrana", tgt="Pamela Rutagrana"}, [14]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff"}, [15]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado"}, [16]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado"}, [17]={npc="Leonid Barthalomew el Venerado", tgt="Leonid Barthalomew el Venerado", tag="Opcional, Grupo recomendado"}, [18]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Opcional, Grupo recomendado"}, [19]={node="Capilla de la Esperanza de la Luz"}, [20]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [21]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}, [22]={npc="Custodio Alen", tgt="Custodio Alen"}, [23]={hint="Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [24]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [25]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [26]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [27]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [28]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [29]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [30]={hint="Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín."}, [31]={hint="Lleva la cabeza de Zaeldarr al custodio Alen a la Capilla de la Esperanza de la Luz."}, [32]={npc="Pergamino roto", npcObj=true}, [33]={hint="Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamañublo\" y los agentes perdidos del IV:7. Si encuentras alguna insignia del IV:7 llévasela a Flint Sombramás en el Campamento del Orvallo.", tag="Opcional", desc="Recoge una insignia de cada uno de los tres cuerpos. Cuando tengas las tres, revisa el objetivo de exploración en el registro. Si sigue pendiente, explora cerca del punto marcado y mantente lejos del élite."}, [34]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [35]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [36]={npc="Custodio Alen", tgt="Custodio Alen"}, [37]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}}},
    ["04-53"] = {steps={[1]={to="Southshore", toA="{a:271}", desc="Harás escala en el Campamento del Orvallo o en el Pico Nidal; si Costasur no está en tu mapa de vuelos, vuela a Ventormenta como siempre y toma el barco a Auberdine en el puerto."}, [2]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Requiere materiales"}, [3]={to="Auberdine", from="Southshore", fromA="{a:271}", desc="Toma el barco a Auberdine en el muelle de Costasur. Si vuelas a Ventormenta, embarca en el puerto de Ventormenta."}, [4]={to="Everlook", toA="{a:2255}"}, [5]={hint="Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 vigías del cubil Nevada y 8 totémicos Nevada."}, [6]={hint="Salfa quiere que mates 8 chamanes Nevada, 8 vigías del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión Fauces de Madera en Cuna del Invierno."}, [7]={npc="Frasco vacío de aguardiente", npcObj=true, tag="Acepta si cae, Opcional", desc="Los furbolgs Nevada sueltan el Frasco vacío de aguardiente; cuando lo consigas, haz clic derecho para aceptar la misión; si aún no ha caído, sigue matando furbolgs."}, [8]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [9]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado", tag="Hazla si cae"}, [10]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [11]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [12]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado", desc="Explorar Garganta Negro Rumor se completa de camino al Monte Hyjal en el siguiente punto; entrégala antes de volver a Cuna del Invierno y seguir a Claro de la Luna. Entrégala antes de volver a Cuna del Invierno y seguir a Claro de la Luna."}, [13]={hint="Recoge 10 plumas Lunadón de Cuna del Invierno y regresa con Erelas Cieloámbar en Aldea Rut'theran."}, [14]={npc="Salfa", tgt="Salfa"}, [15]={npc="Caldera de Muertobosque", npcObj=true}, [16]={npc="Caldera de Muertobosque", npcObj=true}, [17]={to="Rut'theran Village", toA="{a:702}", desc="Desde la Caldera de Muertobosque, ve al sur hasta el punto de vuelo del Claro Ramaespolón (62.49, 24.24) y despega desde allí; harás escala en Auberdine."}, [18]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [19]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [20]={npc="Daryn Brisela", tgt="Daryn Brisela"}, [21]={to="Everlook", toA="{a:2255}"}, [22]={npc="Harlo Contorecio", tgt="Harlo Contorecio"}, [23]={npc="Harlo Contorecio", tgt="Harlo Contorecio", tag="Opcional", desc="Misión de solo hablar dentro del pueblo; la continuación pide matar gigantes élite, no la aceptes."}, [24]={npc="Médica bruja Mau'ari", tgt="Médica bruja Mau'ari", tag="Opcional"}, [25]={npc="Umi Risitas", tgt="Umi Risitas", desc="Pelea contra los yetis cuando vuelvas de donde está Donova, antes de partir hacia el sur."}, [26]={npc="Wynd Cazanoche", tgt="Wynd Cazanoche"}, [27]={npc="Wynd Cazanoche", tgt="Wynd Cazanoche"}, [28]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [29]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [30]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [31]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras"}, [32]={hint="Utiliza el pico de Gormir para encontrar los cuatro trozos de reliquia de los Altonato."}, [33]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [34]={hint="Reúne 10 pelajes de yeti gruesos para Umi Risitas en Vista Eterna."}, [35]={npc="Umi Risitas", tgt="Umi Risitas"}, [36]={npc="Umi Risitas", tgt="Umi Risitas", tag="Opcional", desc="Los cuernos solo los sueltan las matriarcas y los patriarcas de la cueva, y la probabilidad de botín es baja; hazla si quieres algo más de experiencia."}, [37]={hint="Reúne 2 cuernos prístinos de yeti para Umi Risitas en Vista Eterna.", tag="Opcional"}, [38]={npc="Umi Risitas", tgt="Umi Risitas", tag="Opcional", desc="La continuación te manda a Un'Goro y a Gadgetzan, no la aceptes."}, [39]={npc="Cajón dañado", npcObj=true}, [40]={npc="Cajón dañado", npcObj=true}, [41]={npc="Carro de Jaron", npcObj=true}, [42]={npc="Carro de Jaron", npcObj=true}, [43]={hint="Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico salvaje que robó el amuleto del que te habló Jaron."}, [44]={npc="Ranshalla", tgt="Ranshalla"}, [45]={npc="Ranshalla", tgt="Ranshalla"}, [46]={hint="Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Erelas Cieloámbar de Aldea Rut'theran."}}},
    ["04-57"] = {danger={[1]="Ghansurok (quimera élite de nivel 61) patrulla desde los hibiscos contaminados hasta el taller de Kaylaena (hacia x55-62,5, y61,5-72,2); mira dónde está al golpear los arbustos y al volver al taller.", [2]="Celastrus el Amargo (élite de nivel 57) merodea por los hibiscos contaminados; ten cuidado al golpear los arbustos.", [3]="El montón de huesos invoca un cieno élite de nivel 58; no hagas clic una segunda vez sin grupo."}, grind={[1]={note="La parte norte de la Cicatriz Sangrevil; todas las misiones de Felflick se pelean aquí."}}, supply={[1]={}}, steps={[1]={text="Desde donde está Ranshalla, ve al sur y entra en la Garganta Negro Rumor (59.82, 74.25); sigue el desfiladero hacia el oeste hasta el final y entrarás en el Monte Hyjal. Hay gigantes de escarcha élite en la boca del desfiladero y demonios élite dentro; pégate al camino y no te detengas.", tag="Aún no tienes este punto de vuelo. La primera vez debes ir a pie."}, [2]={hint="Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle.", desc="Se completa al atravesar el desfiladero hacia el Monte Hyjal; no hace falta dar ningún rodeo. Cuenta en cuanto el registro de misiones la muestre como completada."}, [3]={text="Entra en el Monte Hyjal por la esquina sureste y sigue el camino al oeste."}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="Un engranaje en el suelo junto al camino; haz clic derecho para recogerlo y aceptar la misión."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Opcional", desc="Entrégala solo si la aceptaste antes en Frondavil."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Botín de: Hyjal Stag, Predatory Hyjal Stag"}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", desc="Los restos de la ballesta, la catapulta y la máquina voladora cuentan cada uno como un objetivo, y hay que plantar los tres. Búscala en la ladera fuera de la Cueva del Ermitaño."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="Sigue el camino al oeste; el punto de vuelo está junto al puesto de los ancestros."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional", desc="El objetivo es una élite de nivel 57; si no puedes con él en solitario, no la aceptes."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Cuando vayas después a Vista Eterna, busca a Nami para las piezas."}, [36]={hint="Matar: Tainted Shrubbery", desc="Los mismos hibiscos sueltan también las hojas que detienen la hemorragia; golpéalos para ambas misiones a la vez. Entrégalo en el taller cuando lleves la caja."}, [37]={hint="Botín de: Tainted Shrubbery"}, [38]={hint="Botín de: Celastrus the Bitter", tag="Grupo recomendado, Opcional"}, [39]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Hyacinth", tgt="Hyacinth"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Matar: Fraxinus"}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional", desc="El objetivo, Sunderbark, es un ancestro élite de nivel 56; hazla cuando tengas grupo. Si no tienes grupo, sáltatela; la entrega de más adelante se omitirá automáticamente."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Matar: Ashen Acolyte", desc="Las notas las sueltan los mismos acólitos; pelea contra ellos para ambas misiones."}, [53]={hint="Botín de: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Curious Crow", tgt="Curious Crow"}, [58]={npc="Curious Crow", tgt="Curious Crow"}, [59]={npc="Curious Crow", tgt="Curious Crow"}, [60]={hint="Botín de: Babosa nociva"}, [61]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [62]={npc="Curious Crow", tgt="Curious Crow"}, [63]={npc="Curious Crow", tgt="Curious Crow"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Felflick", tgt="Felflick"}, [66]={npc="Felflick", tgt="Felflick"}, [67]={hint="Botín de: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz"}, [68]={hint="Matar: Brashann Grimdark"}, [69]={npc="Felflick", tgt="Felflick"}, [70]={npc="Felflick", tgt="Felflick"}, [71]={npc="Felflick", tgt="Felflick"}, [72]={npc="Bone Pile", npcObj=true, desc="Arroja los huesos de brujo al montón de huesos junto al charco de cieno."}, [73]={npc="Bone Pile", npcObj=true, tag="Grupo recomendado, Opcional", desc="Invoca un cieno élite de nivel 58; si no tienes grupo, sáltate Amalgamated Marrow y las misiones que le siguen."}, [74]={hint="Matar: Awakened Fel Ash Slime", tag="Grupo recomendado, Opcional"}, [75]={npc="Velician", tgt="Velician"}, [76]={npc="Felflick", tgt="Felflick", tag="Grupo recomendado, Opcional"}, [77]={npc="Felflick", tgt="Felflick"}, [78]={npc="Curious Crow", tgt="Curious Crow"}, [79]={npc="Curious Crow", tgt="Curious Crow"}, [80]={npc="Curious Crow", tgt="Curious Crow"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations."}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Entrégalo en Flora Antigua, al oeste, en el siguiente punto."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Grupo recomendado, Opcional", desc="En el camino de vuelta al este, hacia la Cueva del Ermitaño."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional"}, [89]={to="Everlook", toA="{a:2255}"}, [90]={npc="Nami", tgt="Nami", desc="La caja siguiente tiene límite de tiempo; acéptala cuando vuelvas de Claro de la Luna."}, [91]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras", desc="Desde Vista Eterna sigue el camino al oeste un trecho hasta Aldea Estrella Fugaz."}, [92]={text="Cabalga al suroeste por el camino desde Aldea Estrella Fugaz hasta las aguas termales y busca a Donova."}, [93]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [94]={to="Claro de la Luna", desc="Cabalga de vuelta de las aguas termales al punto de vuelo de Vista Eterna y vuela (el punto de vuelo de Claro de la Luna se abrió en {s:04-49}). Si tu reputación con los Fauces de Madera ya es neutral, cabalga al norte desde las aguas termales hasta la entrada de Bastión Fauces de Madera (27.70, 34.50); cruzar la cueva hasta la salida a Claro de la Luna queda más cerca; si no abriste el punto de vuelo de Claro de la Luna, toma también esta ruta y ábrelo primero al llegar (48.10, 67.34); por debajo de neutral te atacarán. Los druidas pueden usar Teletransporte: Claro de la Luna directamente; al llegar, ve al punto de vuelo normal (48.10, 67.34) y ábrelo para poder volver volando. Si no abriste el punto de vuelo de Claro de la Luna, toma también esta ruta y ábrelo primero al llegar (48.10, 67.34). Por debajo de neutral te atacarán. Los druidas pueden usar Teletransporte: Claro de la Luna directamente; al llegar, ve al punto de vuelo normal (48.10, 67.34) y ábrelo para poder volver volando."}, [95]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [96]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [101]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [102]={to="Everlook", toA="{a:2255}", desc="Despega desde el punto de vuelo normal de Claro de la Luna (48.10, 67.34) y baja en Vista Eterna para recoger la caja."}, [103]={npc="Nami", tgt="Nami", desc="Las pilas de la caja dejan de funcionar tras unas dos horas, así que entrégala directamente a Kaylaena desde el punto de vuelo."}, [104]={to="Tainted Foothills", toA="{a:16853}", desc="Desde el punto de vuelo cabalga directamente al norte hasta el taller de Kaylaena y entrega primero la caja."}}},
    ["04-58"] = {danger={[1]="Ghansurok (quimera élite de nivel 61) patrulla al este del Santuario de Aviana; ten cuidado al pelear contra arpías."}, supply={[1]={}, [2]={}}, steps={[1]={hint="Gently transport the crate of parts and baubles to Kaylaena Springwhisper in Mount Hyjal.", desc="Lleva la caja a Kaylaena en el taller y sigue su diálogo de misión."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Desde el punto de vuelo cabalga directamente al norte hasta el taller y entrega primero la caja."}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [4]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Los materiales están en los restos del campamento de la Horda en Dae'gun, al norte; recógelos cuando pases más tarde."}, [5]={npc="Ketharas", tgt="Ketharas", desc="Cabalga al sureste desde el taller de vuelta a la Cueva del Ermitaño."}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Ketharas", tgt="Ketharas"}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Cabalga al noroeste desde la Cueva del Ermitaño hasta el Santuario de Aviana."}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [13]={hint="Botín de: Wormwing Harpy, Wormwing Windwitch, Wormwing Ambusher"}, [14]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [15]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [16]={hint="Botín de: Zarrat Wormwing"}, [17]={npc="Corrupted Growth", npcObj=true, desc="Haz clic derecho en la masa corrupta del árbol para aceptar la misión."}, [18]={hint="Usar/recoger: Corrupted Growth"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [22]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [23]={npc="Curious Crow", tgt="Curious Crow"}, [24]={npc="Curious Crow", tgt="Curious Crow", desc="Solo puedes hacerla en el puente de Cuna de Tranquilidad, al norte, así que llévala contigo por ahora."}, [25]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="Sigue las faldas de la montaña hacia el oeste."}, [26]={hint="Locate a sturdy branch capable of reaching Fenwick Togglespring."}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [29]={hint="Matar: Tree Branch"}, [30]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [31]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [32]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [33]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [34]={hint="Wait until you can safely open the Personal Survival Pack."}, [35]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [36]={npc="Brerufa", tgt="Brerufa"}, [37]={hint="Matar: Deadwood Den Guardian"}, [38]={npc="Brerufa", tgt="Brerufa"}, [39]={npc="Brerufa", tgt="Brerufa", tag="Opcional, If offered", desc="Acéptala solo si ves la misión. Entrégala solo si ya tienes 8 sartas de cuentas; no hace falta farmear más."}, [40]={npc="Brerufa", tgt="Brerufa"}, [41]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [42]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [43]={hint="Gather 30 Bear Berries from Hyjal and return to Osi Mistpaw."}, [44]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [45]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [46]={hint="Find and speak with Elder Mistpaw and Elder Pinespeaker within Barkskin Burrow."}, [47]={npc="Elder Mistpaw", tgt="Elder Mistpaw"}, [48]={npc="Elder Mistpaw", tgt="Elder Mistpaw"}, [49]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [50]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [51]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Opcional, If offered", desc="