    ["04-60"] = {danger={[1]="Ghansurok (quimera élite de nivel 61) merodea por la cresta al sur del taller de Kaylaena.", [2]="Mazzogore (élite de nivel 60) patrulla al sur de Dae'gun; rodéalo al pelear contra los sabuesos.", [3]="Ve'han Talongrasp (élite de nivel 60) vigila la cabaña de Nordrassil; no te acerques demasiado durante las misiones de cultistas."}, grind={[1]={mob="Avizor guardia vil", note="La mitad sur de Dae'gun; recoge de paso los suministros abandonados y los materiales de los restos de la Horda."}, [2]={note="El campamento de cultistas al este de la Cima de la Eternidad; las misiones de la cima se pelean todas aquí."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Vuelve al este por el camino."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Witherbeard", tgt="Witherbeard"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Light the two bonfires in Dae'gun and return to Yashiro."}, [7]={text="Tras encender la hoguera del sureste, sigue al sureste hasta Renalard; entrega primero Criatura lista, acepta las misiones de las cenizas y del zorro y vuelve a limpiar Dae'gun una vez más al regresar."}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Collect 8 Abandoned Supplies.", desc="Usa el mechón de pelo de zorro (Tuft of Fox Fur) que te da la misión para alejar al demonio y luego recoge 8 suministros abandonados. Los suministros no están junto a Renalard."}, [12]={hint="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."}, [13]={hint="Botín de: Defiling Hound"}, [14]={hint="Matar: Felguard Sentinel"}, [15]={hint="Fetch a pinch of Azgalor's Ashes from the ruins of Dae'gun on Mount Hyjal."}, [16]={hint="Enter Dae'gun and locate a high vantage point, then report details to Johun."}, [17]={npc="Yashiro", tgt="Yashiro", desc="Tras limpiar Dae'gun, vuelve aquí con Yashiro para entregar."}, [18]={npc="Yashiro", tgt="Yashiro", tag="Opcional"}, [19]={hint="Fight your way through Dae'gun with Yashiro.", tag="Grupo recomendado, Opcional", desc="Sigue a Yashiro mientras despeja el camino; se completa al derrotar a la guardia apocalíptica Xarkul (Doomguard Xarkul) al final."}, [20]={npc="Yashiro", tgt="Yashiro", tag="Opcional", desc="Entrégala a Yashiro donde termine el evento, que no tiene por qué ser el punto de partida."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Grupo recomendado, Opcional", desc="Los dos objetivos son demonios élite de nivel 60; si no tienes grupo, sáltatela y las continuaciones se omitirán automáticamente."}, [23]={hint="Matar: Bethra'zel, Mazzogore", tag="Grupo recomendado, Opcional"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Grupo recomendado, Opcional"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [26]={npc="Witherbeard", tgt="Witherbeard"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="Ve al sureste."}, [29]={nodeA="{a:16849}", node="Summit of Eternity", desc="Desde Renalard, sube un trecho por la montaña hacia el este y aprende el punto de vuelo de Fayran Elthas. Entrega primero las misiones que subiste a la montaña para aligerar el registro."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Opcional", desc="Entrégala solo si la aceptaste antes en Un'Goro."}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Sebelia", tgt="Sebelia", desc="Entrega el paquete de cartas en Vista Eterna dentro de poco y luego haz la cadena del correo."}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Desde la Cima de la Eternidad baja la montaña al oeste, pasa por Renalard y luego ve al sur hasta el taller. Si el camino de la montaña no es transitable, vuela a Laderas Maculadas y cabalga al norte."}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [36]={hint="Turn the two gears and connect the two battery terminals on both sides of Kaylaena's Glaive Thrower."}, [37]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [38]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Grupo recomendado, Opcional", desc="El Ghansurok que atraes es una quimera élite de nivel 61."}, [39]={hint="Walk to the ridge south of Kaylaena's workshop and find a way to make a loud distracting commotion to draw the chimaera Ghansurok in range to be attacked.", tag="Grupo recomendado, Opcional", desc="Interactúa con el tambor en el acantilado al sur del taller y atrae a la quimera al alcance del lanzador de ruedas de cuchillas para que el PNJ lo use; no la arrastres lejos para pelear a la fuerza."}, [40]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Grupo recomendado, Opcional"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="Desde el taller, camina un trecho al suroeste hasta el Santuario de Aviana."}, [42]={npc="Ketharas", tgt="Ketharas", desc="Cabalga al sureste desde el santuario de vuelta a la Cueva del Ermitaño."}, [43]={npc="Ketharas", tgt="Ketharas"}, [44]={npc="Ketharas", tgt="Ketharas"}, [45]={npc="Ketharas", tgt="Ketharas"}, [46]={to="Everlook", toA="{a:2255}", desc="Cabalga al oeste desde la Cueva del Ermitaño y despega desde el punto de vuelo de Laderas Maculadas."}, [47]={npc="Tabernera Vizzie", tgt="Tabernera Vizzie"}, [48]={npc="Tabernera Vizzie", tgt="Tabernera Vizzie"}, [49]={hint="Find 4 pieces of Missing Mail in the hills north of Everlook and bring it back to Innkeeper Vizzie.", desc="El correo está esparcido por las colinas de las afueras de Vista Eterna; búscalo siguiendo las pistas del registro de misiones; si no lo encuentras, puedes saltártela por ahora."}, [50]={npc="Tabernera Vizzie", tgt="Tabernera Vizzie"}, [51]={npc="Tabernera Vizzie", tgt="Tabernera Vizzie", desc="Lleva el correo de vuelta a la cima del Monte Hyjal para entregarlo."}, [52]={to="Summit of Eternity", toA="{a:16849}", desc="Harás escala en Laderas Maculadas."}, [53]={npc="Sebelia", tgt="Sebelia"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [57]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [58]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [59]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={hint="Find thorn seeds in the forests at the summit of Mount Hyjal and bring them back to Tiala Whitemane."}, [62]={hint="Use the Staff of the Mountain on 10 members of the Blackthorne Pact on the Summit of Eternity to remove their wards and then kill them.", desc="Los mismos cultistas cuentan también para Acabar con el frenesí y Herramientas retorcidas; usa primero el bastón y luego mátalos, y haz las tres a la vez."}, [63]={hint="Matar: Blackthorne Cultist, Blackthorne Adept"}, [64]={hint="Botín de: Blackthorne Cultist, Blackthorne Outrunner, Blackthorne Adept"}, [65]={hint="Botín de: Mountain Squallclimber, Wildbreath Chimaerok"}, [66]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [67]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [68]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [69]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [70]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp."}, [71]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [72]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [73]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="Tras aceptarla, ve primero con Marn Euhorn para entregar Vientos de purificación y aceptar el Perdón de Archimonde (Archimonde's Pardon); haz las dos en el mismo viaje."}, [74]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [75]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [76]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", desc="Las piedras norte, oeste y sur cuentan cada una como un objetivo, y hay que visitar las tres."}, [77]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", desc="Libera al fuego fatuo que ya está bajo las raíces, en lugar de invocarlo con un objeto en el claro. Hazla en el mismo viaje que el Perdón de Archimonde."}, [78]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains."}, [79]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [80]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={to="Rut'theran Village", toA="{a:702}", desc="Harás escala en Laderas Maculadas y Vista Eterna."}, [84]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [85]={npc="Erelas Cieloámbar", tgt="Erelas Cieloámbar"}, [86]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus."}, [87]={npc="Archidruida Fandral Corzocelada", tgt="Archidruida Fandral Corzocelada"}, [88]={npc="Mathrengyl Garroso", tgt="Mathrengyl Garroso"}}},
    ["04-59"] = {name="Tierras de la Peste del Oeste", steps={[1]={bindA="{a:348}", desc="Usa la piedra de hogar solo si sigue vinculada a Pico Nidal y está disponible. Si no, usa la ruta en barco como alternativa: vuelve por el portal a la Aldea Rut'theran, vuela a Auberdine, ve primero en barco a Puerto de Menethil, sigue la ruta marítima del norte hasta Costasur, baja allí y vuela al Campamento Chillwind."}, [2]={to="Chillwind Camp", toA="{a:3197}", desc="Sáltalo si ya estás en el Campamento Chillwind. Si el mapa de vuelo no muestra el Campamento Chillwind, ve al norte por el camino de montaña desde Pico Nidal hasta Tierras de la Peste del Oeste y luego al oeste hasta el Campamento Chillwind."}, [3]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [4]={npc="Flint Sombramás", tgt="Flint Sombramás", tag="Opcional"}, [5]={npc="Flint Sombramás", tgt="Flint Sombramás", tag="Opcional"}, [6]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [7]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [8]={npc="Alquimista Arbington", tgt="Alquimista Arbington"}, [9]={npc="Alquimista Arbington", tgt="Alquimista Arbington", desc="Los Trozos esqueléticos solo empiezan a caer una vez que la aceptas; reúnelos de paso mientras matas esqueletos en la Colina de las Penas y en Andorhal."}, [10]={npc="Marlene Rutagrana", tgt="Marlene Rutagrana"}, [11]={npc="Marlene Rutagrana", tgt="Marlene Rutagrana"}, [12]={hint="Lleva la alianza de Joseph a Cromi."}, [13]={hint="Lleva 15 trozos esqueléticos al alquimista Arbington, en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}, [14]={npc="Cromi", tgt="Cromi"}, [15]={npc="Cromi", tgt="Cromi"}, [16]={npc="Cromi", tgt="Cromi"}, [17]={hint="Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal."}, [18]={hint="Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales."}, [19]={npc="Cromi", tgt="Cromi"}, [20]={npc="Cromi", tgt="Cromi"}, [21]={npc="Cromi", tgt="Cromi"}, [22]={hint="Localiza 5 relojes de Andorhal, los encontrarás en cajas fuertes entre las ruinas de la ciudad. Cuando los tengas regresa con Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}, [23]={npc="Cromi", tgt="Cromi"}, [24]={npc="Cromi", tgt="Cromi"}, [25]={to="Capilla de la Esperanza de la Luz", desc="Andorhal no tiene punto de vuelo. Primero camina de vuelta al sur hasta el Campamento del Orvallo y vuela desde allí."}, [26]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado"}, [27]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [28]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}, [29]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [30]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado"}, [31]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado", desc="Hazlo la próxima vez que tu grupo vaya al ala de los no-muertos."}, [32]={npc="Leonid Barthalomew el Venerado", tgt="Leonid Barthalomew el Venerado", tag="Opcional, Grupo recomendado"}, [33]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Opcional, Grupo recomendado"}, [34]={hint="Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín."}, [35]={hint="Mata al infiltrador Hameya. Usa su llave en el túmulo detrás de La Subgranja."}, [36]={npc="Aurora Llamacielo", tgt="Aurora Llamacielo"}, [37]={hint="Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Nathaniel Dumah al Campamento del Orvallo en las Tierras de la Peste del Oeste."}, [38]={hint="Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [39]={npc="Túmulo de barro", npcObj=true}, [40]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [41]={npc="Tirión Vadín", tgt="Tirión Vadín"}, [42]={hint="Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana."}, [43]={hint="Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera."}, [44]={npc="Caldera de la Plaga", npcObj=true}, [45]={npc="Caldera de la Plaga", npcObj=true}, [46]={npc="Artista Renfray", tgt="Artista Renfray"}, [47]={npc="Suma sacerdotisa MacDonnell", tgt="Suma sacerdotisa MacDonnell"}, [48]={npc="Alquimista Arbington", tgt="Alquimista Arbington", desc="La continuación te hace entrar en Scholomance, no la aceptes."}, [49]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [50]={npc="Comandante Ashlam Puñovalor", tgt="Comandante Ashlam Puñovalor"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [53]={npc="Barrica de termitas", npcObj=true}, [54]={npc="Barrica de termitas", npcObj=true}, [55]={hint="Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Nathaniel Dumah en el Campamento del Orvallo en las Tierras de la Peste del Oeste."}, [56]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [57]={hint="Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}, [58]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [59]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [60]={hint="Mata al montero Radley y al hidalgo Durgen antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}, [61]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [62]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [63]={hint="Entra en la Vega del Amparo y busca un punto elevado desde el que puedas ver la ciudad y calcular las fuerzas de la Cruzada Escarlata. Cuando lo hayas hecho regresa con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.", desc="Las coordenadas son aproximadas. Hay guardias de la Cruzada Escarlata en la entrada y junto a la torre; atráelos de uno en uno."}, [64]={npc="Kirsta Sombraprofunda", tgt="Kirsta Sombraprofunda"}, [65]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [66]={to="Capilla de la Esperanza de la Luz", desc="Ya estás en el Campamento del Orvallo; ve directamente con el maestro de vuelo."}, [67]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana", tag="Opcional"}, [68]={npc="Carlin Rutagrana", tgt="Carlin Rutagrana"}, [69]={to="Forjaz"}, [70]={npc="Historiadora Real Archesonus", tgt="Historiadora Real Archesonus"}, [71]={to="Stormwind"}, [72]={npc="Agente Real Bathrilor", tgt="Agente Real Bathrilor"}, [73]={npc="Agente Real Bathrilor", tgt="Agente Real Bathrilor"}, [74]={npc="Vieja Emma", tgt="Vieja Emma"}, [75]={npc="Alto señor Bolvar Fordragón", tgt="Alto señor Bolvar Fordragón", tag="Opcional"}, [76]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [77]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [78]={npc="Maestro Mathias Shaw", tgt="Maestro Mathias Shaw", tag="Opcional"}, [79]={to="Lakeshire", toA="{a:69}", tag="Opcional", desc="Ve a Villa del Lago solo si tienes Los verdaderos maestros. Si no la tienes, vuela directamente de Ventormenta a la Vigilia de Morgan."}, [80]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [81]={npc="Magistrado Solomon", tgt="Magistrado Solomon"}, [82]={to="Morgan's Vigil", toA="{a:2418}"}, [83]={npc="Mariscal Maxwell", tgt="Mariscal Maxwell"}, [84]={npc="Mariscal Maxwell", tgt="Mariscal Maxwell"}, [85]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [86]={hint="Habla con John Andrajoso."}, [87]={hint="Coge la cabeza cortada de Gor'tesh y colócala en lo alto de la Roca Machacamiedo. Busca un montículo de tierra blanda para clavar la pica.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [88]={npc="Mariscal Maxwell", tgt="Mariscal Maxwell"}, [89]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [90]={text="¿Aún no eres nivel 60? Haz una vez las Profundidades de Roca Negra. Si no basta, repite Stratholme o Scholomance."}}},
    ["05-d13"] = {name="Stratholme", entrance="Tierras de la Peste del Este 26.52, 10.36 (puerta principal escarlata; entrada de servicio de los no-muertos en 43.50, 19.40)", steps={[1]={text="Vuela al Campamento del Orvallo si necesitas visitar a la pintora de Castel Darrow, en las Tierras de la Peste del Oeste, para tomar De amor y familia. Si ya tienes la misión o solo necesitas las de la capilla, reúnete directamente con tu grupo."}, [2]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [3]={hint="Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín.", tag="Requisito de mazmorra"}, [4]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [5]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [6]={hint="Mata 30 murcipestes y vuelve con Tirion Vadín.", tag="Requisito de mazmorra"}, [7]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [8]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [9]={hint="Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero.", tag="Requisito de mazmorra"}, [10]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [11]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [12]={hint="Escucha lo que Tirion Vadín tiene que contarte.", tag="Requisito de mazmorra"}, [13]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [14]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [15]={hint="Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.", tag="Requisito de mazmorra"}, [16]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [17]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [18]={hint="Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.", tag="Requisito de mazmorra"}, [19]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [20]={npc="Tirión Vadín", tgt="Tirión Vadín", tag="Requisito de mazmorra"}, [21]={npc="Artista Renfray", tgt="Artista Renfray", tag="Requisito de mazmorra"}, [22]={npc="Artista Renfray", tgt="Artista Renfray"}, [23]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado"}, [24]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado"}, [25]={npc="Leonid Barthalomew el Venerado", tgt="Leonid Barthalomew el Venerado", tag="Opcional, Grupo recomendado"}, [26]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Opcional, Grupo recomendado"}, [27]={text="Parte de la Capilla de la Esperanza de la Luz con tu grupo hacia Stratholme. La marca señala la puerta principal escarlata que lleva al mercado y al Bastión Escarlata. Para el ala de los no-muertos, reúnete en la entrada de servicio del este con alguien que pueda abrirla."}, [28]={text="Entrada: Stratholme"}, [29]={hint="Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido.", tag="Opcional, Grupo recomendado", spot="Revisa los cajones de suministros de las calles de ambas alas. Guarda cinco frascos de agua bendita de Stratholme para tu entrega y repón los que uses."}, [30]={hint="Consigue 20 muestras de carne apestadas de Stratholme y llévaselas a Betina Bigglezink. Tienes la sospecha de que podrás obtener ese tipo de carne de cualquier criatura de Stratholme.", tag="Opcional, Grupo recomendado", spot="Recoge muestras de carne apestada mientras tu grupo avanza por cualquiera de las dos alas. Guarda las que tengas para otra visita y vuelve a la capilla cuando reúnas veinte."}, [31]={hint="Encuentra la Tienda de humo de Ezra Grimm en Stratholme y recupera una caja del tabaco de calidad de Grimm. Cuando lo hayas hecho, vuelve con Smokey LaRue.", tag="Opcional, Grupo recomendado", spot="En el ala Escarlata, entra por la puerta principal y ve al mercado. Abre el cajón de la tabaquería, derrota a Ezra Grimm y recoge una caja de su tabaco de calidad superior. Si tu grupo solo visita el ala de los no-muertos, déjalo para otra ocasión."}, [32]={hint="Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.", spot="Derroten primero a Galford. Antes de quemar el archivo, confirmen con el grupo que todos los que necesitan el cuadro de «Del amor y la familia» lo recogieron detrás del cuadro de las dos lunas. Si nadie lo necesita, ya pueden quemar el archivo."}, [33]={hint="Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata.", tag="Opcional, Grupo recomendado", spot="Derroten primero a Galford. Antes de quemar el archivo, confirmen con el grupo que todos los que necesitan el cuadro de «Del amor y la familia» lo recogieron detrás del cuadro de las dos lunas. Si nadie lo necesita, ya pueden quemar el archivo."}, [34]={npc="Cabeza de Balnazzar", npcObj=true, tag="Opcional, Grupo recomendado", desc="Tras entregar El archivista, haz clic derecho en la cabeza que hayas saqueado de Balnazzar para iniciar la misión."}, [35]={hint="Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink.", tag="Opcional, Grupo recomendado", spot="Busca el cofre pequeño en los tres zigurats del ala de no-muertos. Recoge tú mismo los datos."}, [36]={hint="Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff.", tag="Opcional, Grupo recomendado", spot="Pasa por el Matadero en el ala de no-muertos, derrota al barón Osahendido y recoge tú mismo su cabeza."}, [37]={hint="Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre.", tag="Opcional, Grupo recomendado", spot="Busca ciudadanos fantasmales por las calles de Stratholme. Usa el bláster de Egan sobre un ciudadano y luego sobre el alma que aparezca. Libera quince almas."}, [38]={npc="Tirión Vadín", tgt="Tirión Vadín", desc="Tirión Vadín está en la cabaña junto a la orilla del río, al oeste de las Tierras de la Peste del Este."}, [39]={text="Regresa a la Capilla de la Esperanza de la Luz. Si llevas el cuadro de «Del amor y la familia», entrégaselo primero a Tirion en la orilla occidental del río, en las Tierras de la Peste del Este, y vuelve a la capilla."}, [40]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado"}, [41]={npc="Cabeza de Balnazzar", npcObj=true, tag="Opcional, Grupo recomendado", desc="Tras entregar El archivista, haz clic derecho en la cabeza que hayas saqueado de Balnazzar para iniciar la misión."}, [42]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado"}, [43]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado", desc="Hazlo la próxima vez que tu grupo vaya al ala de los no-muertos."}, [44]={npc="Duque Nicholas Zverenhoff", tgt="Duque Nicholas Zverenhoff", tag="Opcional, Grupo recomendado"}, [45]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado"}, [46]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado", desc="Hazlo la próxima vez que tu grupo vaya al ala de los no-muertos."}, [47]={npc="Betina Bigglezink", tgt="Betina Bigglezink", tag="Opcional, Grupo recomendado"}, [48]={npc="Leonid Barthalomew el Venerado", tgt="Leonid Barthalomew el Venerado", tag="Opcional, Grupo recomendado"}, [49]={npc="Smokey LaRue", tgt="Smokey LaRue", tag="Opcional, Grupo recomendado"}, [50]={npc="Egan", tgt="Egan", tag="Opcional, Grupo recomendado"}, [51]={to="Forjaz"}}},
